    }

    // INV-04: mọi đòn kẻ địch có telegraph >= 18 frame
    [Test] public void INV04() {
        foreach (var a in LoadAll<AttackData>().Where(x => x.isEnemyAttack))
            Assert.GreaterOrEqual(a.startupFrames, 18, a.name);
    }

    // INV-05: meta-progression chỉ mở khoá lựa chọn
    [Test] public void INV05() {
        foreach (var u in LoadAll<UnlockDef>())
            Assert.AreNotEqual(UnlockKind.StatBoost, u.kind, u.name);
    }
}
```

**Ràng buộc riêng cho Unity — viết vào `CLAUDE.md`**

```markdown
## Không được tự ý (Unity)

- Sửa file .prefab, .unity, .asset bằng text → KHÔNG BAO GIỜ.
  Cần đổi prefab thì mô tả cho tôi làm trong Editor.
- Sửa ProjectSettings/*.asset → KHÔNG. Nói tôi setting nào cần đổi.
- Thêm package vào manifest.json → hỏi trước.
- Đổi Assembly Definition references → hỏi trước.
- Dùng `Input.GetKey` (Input Manager cũ) → dự án dùng Input System mới.
- `GameObject.Find` / `FindObjectOfType` trong Update → không bao giờ.
- Đổi số cân bằng trong ScriptableObject → đó là quyết định của tôi.
```

Dòng đầu quan trọng nhất: agent sửa prefab bằng text làm hỏng GUID reference, và lỗi chỉ lộ ra khi mở Editor.

**Rà soát cuối phiên — thêm mục Unity**

```
Rà thay đổi vừa rồi, đối chiếu CLAUDE.md. Báo cáo bảng:
| bất biến | vi phạm? | file | cách sửa |

Thêm vào báo cáo:
- File .prefab/.unity/.asset nào bị sửa? (phải là 0)
- Package mới nào được thêm?
- API nào dùng mà có thể đã deprecated ở Unity 6?
- Component nào tôi cần gán trong Inspector để code này chạy?

Chưa sửa gì.
```

**Kiểm tra nhanh**
- Test EditMode chạy trong CI chưa?
- `git diff --stat` sau một phiên agent: có `.prefab`/`.unity` nào không?
- `CLAUDE.md` có khối "không được tự ý (Unity)" chưa?

Trong Unity, phần khó không phải sinh asset — là **import nó vào mà không phá nhất quán**.

**Preset import cưỡng chế phong cách**

Xem [[art-direction]]. Điểm cốt lõi: đặt `TextureImporter` preset làm mặc định cho thư mục, để mọi asset mới (kể cả AI sinh) tự vào đúng khuôn.

**Pipeline xử lý hậu kỳ — AssetPostprocessor**

```csharp
// Chạy TỰ ĐỘNG mỗi lần có texture mới vào thư mục
public class ArtPostprocessor : AssetPostprocessor {
    void OnPreprocessTexture() {
        if (!assetPath.StartsWith("Assets/Art/Generated")) return;
        var ti = (TextureImporter)assetImporter;
        ti.spritePixelsPerUnit = 32;
        ti.filterMode = FilterMode.Point;
        ti.textureCompression = TextureImporterCompression.Uncompressed;
        ti.mipmapEnabled = false;
    }

    void OnPostprocessTexture(Texture2D tex) {
        if (!assetPath.StartsWith("Assets/Art/Generated")) return;
        QuantizeToPalette(tex);         // ép về palette dự án
    }
}
```

Đây là cách biến "nhất quán phong cách" từ kỷ luật con người thành cơ chế tự động. Thả 50 sprite AI sinh vào `Assets/Art/Generated/` là chúng tự về đúng palette và đúng PPU.

**SFX sinh tự động — import settings quan trọng hơn chất lượng clip**

Xem bảng ở [[unity-audio]]. Sai `Load Type` cho 200 SFX là cách nhanh nhất ăn hết RAM trên mobile.

**Asset tạm: hình khối màu tốt hơn art AI nửa vời**

Ở giai đoạn prototype, Unity có sẵn primitive và `Color`. Một `Cube` màu đỏ rõ ràng hơn một sprite AI sinh trông "gần giống quái vật" — và không làm bạn gắn bó với thứ sẽ phải bỏ.

**Giấy phép — kiểm tra trước khi ship**

Điều khoản từng công cụ khác nhau và thay đổi theo thời gian. Với Unity còn thêm một lớp: **Asset Store có điều khoản riêng** về việc redistribute. Đây là việc phải tự xác minh với nguồn chính thức tại thời điểm phát hành, không dựa vào ghi nhớ của AI hay của tài liệu này.

**Kiểm tra nhanh**
- Thả một PNG vào `Assets/Art/Generated/`: nó có tự về PPU 32 và palette không?
- Build mobile: dung lượng RAM cho texture và audio bao nhiêu?
- Có asset nào chưa rõ giấy phép trong build không?

Unity đẩy bạn về phía component sẵn rồi. Việc cần làm là **giữ logic tách khỏi MonoBehaviour**.

**Cấu trúc thư mục khuyến nghị**

```
Assets/Scripts/
├── Core/            ← C# thuần, KHÔNG using UnityEngine
│   ├── Combat/      DamageCalculator, StatusEffects
│   └── Economy/     ShopPricing, LootRoller
├── Unity/           ← MonoBehaviour, chỉ là lớp vỏ mỏng
└── Tests/
    └── EditMode/    ← test Core/, chạy trong mili giây
```

Ranh giới `Core/` không phụ thuộc `UnityEngine` là thứ cho bạn:
- Test chạy ở **EditMode** (mili giây) thay vì PlayMode (vài giây mỗi lần)
- Mô phỏng 10.000 trận không cần render — xem [[balancing-math]]
- AI agent tự kiểm chứng được thay đổi của nó

**Object pooling — Unity đã có sẵn**

Đừng tự viết pool. `UnityEngine.Pool.ObjectPool<T>` có từ Unity 2021:

```csharp
using UnityEngine.Pool;

public class BulletSpawner : MonoBehaviour {
    [SerializeField] Bullet prefab;
    ObjectPool<Bullet> pool;

    void Awake() {
        pool = new ObjectPool<Bullet>(
            createFunc:      () => Instantiate(prefab),
            actionOnGet:     b  => b.gameObject.SetActive(true),
            actionOnRelease: b  => b.gameObject.SetActive(false),
            actionOnDestroy: b  => Destroy(b.gameObject),
            collectionCheck: true,      // BẬT trong dev: bắt lỗi release hai lần
            defaultCapacity: 32,
            maxSize: 256);
    }

    public Bullet Spawn() {
        var b = pool.Get();
        b.Init(onDone: () => pool.Release(b));
        return b;
    }
}
```

`collectionCheck: true` bắt được lỗi trả cùng một object về pool hai lần — bug rất khó truy nếu không có nó. Tắt nó trong build release.

**Singleton — giới hạn số lượng**

Unity làm singleton quá dễ nên dự án nào cũng có 15 cái. Nguyên tắc: tối đa 3, và chúng phải là **dịch vụ không trạng thái game** (AudioManager, ConfigLoader, TimeManager). Mọi thứ khác truyền qua tham chiếu hoặc ScriptableObject.

**Cái bẫy `GetComponent` trong Update**

```csharp
// ❌ chạy 60 lần/giây × số object
void Update() => GetComponent<Rigidbody2D>().velocity = v;

// ✅ cache một lần
Rigidbody2D rb;
void Awake() => rb = GetComponent<Rigidbody2D>();
void Update() => rb.linearVelocity = v;      // Unity 6 đổi tên: velocity -> linearVelocity
```

**Kiểm tra nhanh**
- `grep -r "using UnityEngine" Assets/Scripts/Core/` → phải rỗng.
- Test EditMode chạy dưới 1 giây cho toàn bộ `Core/`.
- Không có `Instantiate`/`Destroy` nào trong code chạy mỗi frame.

nodes.body:
Nguyên tắc: **logic nằm trong code, con số nằm trong dữ liệu.**

Nghe hiển nhiên, nhưng nó là ranh giới quyết định bạn có cân bằng được game hay không — và có làm việc được với AI agent một cách an toàn hay không.

## Trước và sau

```csharp
// ❌ Số nằm trong code
void Attack() {
    float damage = 12f;
    if (Random.value < 0.15f) damage *= 2f;
    target.TakeDamage(damage);
    StartCoroutine(Cooldown(0.4f));
}
```

Muốn đổi sát thương: sửa code → build lại → chạy lại → mất vài phút cho mỗi lần thử. Với hàng trăm lần chỉnh trong quá trình cân bằng, đây là hàng chục giờ bị đốt.

```csharp
// ✅ Số nằm trong dữ liệu
[CreateAssetMenu]
public class WeaponData : ScriptableObject {
    public float damage = 12f;
    public float critChance = 0.15f;
    public float critMultiplier = 2f;
    public float cooldown = 0.4f;
}

void Attack() {
    float dmg = data.damage;
    if (Random.value < data.critChance) dmg *= data.critMultiplier;
    target.TakeDamage(dmg);
    StartCoroutine(Cooldown(data.cooldown));
}
```

Giờ chỉnh được **trong lúc game đang chạy**, và người không biết code cũng chỉnh được.

## Cái gì nên đưa ra dữ liệu

**Luôn luôn:**
- Mọi số cân bằng: sát thương, HP, tốc độ, chi phí, tỉ lệ
- Mọi giá trị thời gian: cooldown, thời lượng, độ trễ
- Bảng nội dung: kẻ địch, vật phẩm, kỹ năng, drop table
- Đường cong: XP, giá nâng cấp, tỉ lệ độ khó
- Tham số game feel: hitstop, screenshake, độ giật camera

**Thường nên:**
- Cấu hình màn chơi (spawn, bố trí, ngân sách)
- Cây hội thoại
- Luật procgen (xem [[procedural-generation]])

**Đừng:**
- Logic phức tạp — đừng tự viết ngôn ngữ kịch bản trong JSON. Đến lúc cần rẽ nhánh và vòng lặp trong dữ liệu, hãy dùng một ngôn ngữ nhúng thật (Lua, GDScript) thay vì phát minh lại.

## Chọn định dạng

| Định dạng | Mạnh | Yếu |
|---|---|---|
| ScriptableObject (Unity) | Tích hợp editor, kiểm tra kiểu, tham chiếu asset | Khó diff trong git, khó sửa hàng loạt |
| JSON | Dễ đọc, dễ diff, công cụ sẵn có, AI sửa tốt | Không kiểm tra kiểu, không tự validate |
| CSV | Sửa hàng loạt trên Excel/Sheets, cân bằng rất nhanh | Chỉ dữ liệu phẳng |
| YAML/TOML | Dễ đọc, hỗ trợ chú thích | Cần thư viện, dễ lỗi thụt lề |

Kết hợp thường dùng trong thực tế: **CSV cho bảng số lớn** (để cân bằng trên spreadsheet), **JSON cho cấu hình có cấu trúc**, và một bước import chuyển chúng thành định dạng của engine.

## Hot reload — thứ đáng đầu tư nhất

Nếu chỉ làm được một việc trong nhánh này, hãy làm việc này: **sửa file dữ liệu → game cập nhật ngay, không cần khởi động lại.**

```csharp
void Update() {
    if (Input.GetKeyDown(KeyCode.F5)) {
        ConfigLoader.ReloadAll();
        Debug.Log("Đã nạp lại cấu hình");
    }
}
```

Vòng lặp cân bằng rút từ *"sửa → build 90s → chơi lại từ đầu"* xuống *"sửa → F5 → thấy ngay"*. Khác biệt về số lần thử nghiệm bạn thực hiện được là hàng chục lần.

## Validation là bắt buộc

Dữ liệu ngoài code nghĩa là trình biên dịch không bảo vệ bạn nữa. Phải tự kiểm tra khi nạp:

```csharp
public bool Validate(out List<string> errors) {
    errors = new List<string>();
    if (damage <= 0)                   errors.Add($"{name}: damage phải > 0");
    if (critChance is < 0 or > 1)      errors.Add($"{name}: critChance ngoài [0,1]");
    if (cooldown < 0.05f)              errors.Add($"{name}: cooldown < 0.05s là quá ngắn");
    if (rewardId != null && !Database.Exists(rewardId))
                                       errors.Add($"{name}: rewardId '{rewardId}' không tồn tại");
    return errors.Count == 0;
}
```

Chạy validation lúc build và fail build nếu có lỗi. Dữ liệu hỏng phát hiện lúc build rẻ hơn nhiều so với phát hiện khi người chơi báo lỗi.

nodes.unity:
Unity có sẵn công cụ tốt nhất cho việc này: **ScriptableObject**. Nhưng nó có một điểm rất dễ dính bẫy.

**Component & nơi đặt**
- `Assets/Data/` — mọi ScriptableObject cấu hình
- `Assets/Data/Balance/*.csv` — bảng số lớn, import qua editor script

**Code**

```csharp
[CreateAssetMenu(menuName = "Game/Weapon Data")]
public class WeaponData : ScriptableObject {
    public float damage = 12f;
    public float cooldown = 0.4f;
    public AnimationCurve damageByLevel = AnimationCurve.Linear(1, 12, 50, 220);

    // Validate ngay trong Editor — dữ liệu hỏng lộ ra lúc sửa, không phải lúc chạy
    void OnValidate() {
        if (damage <= 0)      Debug.LogError($"{name}: damage phải > 0", this);
        if (cooldown < 0.05f) Debug.LogError($"{name}: cooldown < 0.05s là quá ngắn", this);
    }
}
```

**⚠️ Bẫy lớn nhất: ScriptableObject bị sửa vĩnh viễn trong Editor**

Nếu code làm `weaponData.damage += 5`, giá trị đó **ghi thẳng vào asset** và còn nguyên sau khi thoát Play Mode. Build thì không sao (asset chỉ đọc), nhưng trong Editor bạn sẽ âm thầm phá cân bằng game của chính mình.

```csharp
// ❌ SAI — sửa asset gốc
void ApplyBuff() => data.damage *= 1.5f;

// ✅ ĐÚNG — ScriptableObject chỉ đọc, trạng thái lúc chạy nằm ở instance
public class WeaponInstance {
    readonly WeaponData data;
    public float DamageMultiplier = 1f;
    public float Damage => data.damage * DamageMultiplier;
}
```

**Quy tắc: ScriptableObject = read-only lúc chạy.** Mọi thứ thay đổi được phải nằm trong class runtime riêng.

**Hot reload — chỉnh số khi game đang chạy**

Ưu điểm lớn của ScriptableObject: sửa giá trị trong Inspector **lúc Play Mode là có hiệu lực ngay**, và (khác với sửa field trên MonoBehaviour) giá trị **không bị revert** khi thoát Play.

Đây chính là vòng lặp cân bằng nhanh mà [[balancing-math]] cần. Tận dụng: mở Inspector khoá (lock) asset config, chơi, chỉnh, thấy ngay.

**Bảng số lớn thì dùng CSV**

Với 200 kẻ địch, Inspector không phải chỗ để sửa. Giữ CSV làm nguồn, viết editor script import thành ScriptableObject:

```csharp
[MenuItem("Tools/Import Balance CSV")]
static void Import() {
    foreach (var row in ReadCsv("Assets/Data/Balance/enemies.csv")) {
        var so = LoadOrCreate<EnemyData>($"Assets/Data/Enemies/{row["id"]}.asset");
        so.hp     = float.Parse(row["hp"]);
        so.damage = float.Parse(row["damage"]);
        EditorUtility.SetDirty(so);
    }
    AssetDatabase.SaveAssets();
}
```

Cân bằng trên Google Sheets, export CSV, bấm một nút. Xem [[agent-guardrails]] về việc phân quyền cho AI trên lớp dữ liệu này.

**Kiểm tra nhanh**
- Grep code tìm phép gán vào field của ScriptableObject — phải bằng 0.
- Sửa một giá trị lúc Play Mode: có hiệu lực ngay không?
- `OnValidate` có bắt được giá trị vô lý không? Thử nhập `damage = -5`.

Unity có sẵn công cụ đo rất tốt. Vấn đề là **đo sai chỗ** hoặc đo quá muộn.

**Đo trước, tối ưu sau**

`Window > Analysis > Profiler`. Ba cột cần nhìn đầu tiên:
- **GC Alloc** — cột quan trọng nhất. Bất kỳ giá trị nào > 0 B mỗi frame là nguồn giật lag tương lai.
- **Time ms** — so với ngân sách 16.6ms (60 FPS)
- **Calls** — số lần gọi bất thường thường lộ ra vòng lặp sai

**Bật Deep Profile chỉ khi cần** — nó làm chậm game 5–10 lần và bóp méo số liệu. Dùng để tìm hàm nào tốn, không dùng để đo con số tuyệt đối.

**Đo trong game, không chỉ trong Profiler**

```csharp
using Unity.Profiling;

public class PerfHud : MonoBehaviour {
    ProfilerRecorder mainThread, gcAlloc, drawCalls;

    void OnEnable() {
        mainThread = ProfilerRecorder.StartNew(ProfilerCategory.Internal, "Main Thread", 15);
        gcAlloc    = ProfilerRecorder.StartNew(ProfilerCategory.Memory, "GC Allocated In Frame");
        drawCalls  = ProfilerRecorder.StartNew(ProfilerCategory.Render, "Draw Calls Count");
    }
    void OnDisable() { mainThread.Dispose(); gcAlloc.Dispose(); drawCalls.Dispose(); }

    void OnGUI() {
        GUI.Label(new Rect(10, 10, 300, 60),
            $"CPU {mainThread.LastValue / 1e6f:F1} ms\n" +
            $"GC  {gcAlloc.LastValue} B\n" +
            $"Draw {drawCalls.LastValue}");
    }
}
```

Overlay này chạy được **trong build thật trên máy thật** — nơi số liệu mới đúng. Profiler trong Editor luôn lạc quan hơn thực tế.

**Ba nguồn cấp phát hay gặp trong Unity**

```csharp
// ❌ tạo mảng mới mỗi frame
void Update() { var hits = Physics2D.OverlapCircleAll(pos, r); }
// ✅ dùng NonAlloc + buffer dùng lại
readonly Collider2D[] buf = new Collider2D[16];
void Update() { int n = Physics2D.OverlapCircleNonAlloc(pos, r, buf); }

// ❌ nối chuỗi mỗi frame
scoreText.text = "Score: " + score;
// ✅ chỉ cập nhật khi đổi
if (score != lastScore) { scoreText.SetText("Score: {0}", score); lastScore = score; }

// ❌ LINQ trong vòng lặp nóng
var closest = enemies.OrderBy(e => Vector3.Distance(e.pos, p)).First();
// ✅ vòng for thường
```

`TMP_Text.SetText` với format không cấp phát, khác `text = string.Format(...)`.

**Giật lag quan trọng hơn FPS trung bình**

60 FPS với một cú khựng 200ms mỗi 10 giây cảm thấy tệ hơn 40 FPS ổn định. Trong Profiler, tìm các cột cao đột biến chứ không nhìn đường trung bình.

Hai nguồn khựng phổ biến: GC chạy (xem trên) và `Instantiate` lúc chạy (xem object pooling ở [[architecture-patterns]]).

**Kiểm tra nhanh**
- Profiler ở trạng thái chơi bình thường: GC Alloc = 0 B/frame?
- Build ra máy yếu nhất bạn nhắm tới — không phải máy dev.
- Khi có 100 kẻ địch: frame time có vượt ngân sách không?

Trong Unity, phần khó không phải thu thập số liệu — là **thu thập mà không làm giật game và không mất dữ liệu khi crash**.

**Nơi các quyết định sống**

- `Core/Analytics/EventLogger.cs` — buffer + ghi theo lô (C# thuần được)
- `Application.persistentDataPath` — nơi ghi file log
- `Assets/Editor/LogAnalyzer.cs` — đọc log, vẽ phễu

**Ghi log không gây giật**

```csharp
public class EventLogger {
    readonly List<string> buffer = new(256);
    float lastFlush;

    public void Log(string name, string json) {
        // Ghi vào buffer trong bộ nhớ — KHÔNG chạm đĩa ở đây
        buffer.Add($"{{\"t\":{Time.unscaledTime:F2},\"e\":\"{name}\",\"d\":{json}}}");
        if (buffer.Count >= 200) Flush();
    }

    public void Flush() {
        if (buffer.Count == 0) return;
        File.AppendAllLines(logPath, buffer);   // một lần ghi cho 200 dòng
        buffer.Clear();
    }
}
```

Ghi từng dòng ra đĩa mỗi sự kiện là nguồn giật lag rõ ràng. Ghi theo lô 200 dòng gần như miễn phí.

**Đừng mất dữ liệu khi crash**

```csharp
void OnApplicationPause(bool paused) { if (paused) logger.Flush(); }
void OnApplicationFocus(bool focus)  { if (!focus)  logger.Flush(); }
void OnApplicationQuit()             { logger.Flush(); }
```

Ba callback này bắt gần hết trường hợp. Crash cứng thì vẫn mất buffer — nên đặt ngưỡng flush thấp hơn (50 dòng) nếu đang tìm bug crash.

**`unscaledTime`, không `time`**

`Time.time` bị `timeScale` ảnh hưởng, nên hitstop và pause làm số liệu lệch. Mọi mốc thời gian trong log dùng `Time.unscaledTime`.

**Vẽ phễu ngay trong Editor**

```csharp
[MenuItem("Tools/Analytics/Funnel")]
static void Funnel() {
    var events = LoadAllSessions();          // đọc mọi file log
    var steps = new[] { "level_start", "level_complete" };
    // đếm session đi qua từng bước, in tỉ lệ rơi rụng
    // 1000 -> 780 -> 310 -> 295 : cú rơi 780->310 là chỗ cần sửa
}
```

Không cần dashboard bên ngoài cho giai đoạn playtest nội bộ. Một EditorWindow đọc file JSON là đủ và làm trong một buổi.

**Bẫy Unity cụ thể**
- **`Application.persistentDataPath` khác nhau mỗi nền tảng** — đừng hardcode đường dẫn.
- **`File.AppendAllLines` trên WebGL không hoạt động** — WebGL không có filesystem thật. Dùng `PlayerPrefs` hoặc gửi lên server.
- **Ghi log trong `Update`** — kể cả vào buffer, `string` interpolation cấp phát. Chỉ log sự kiện, không log mỗi frame.
- **Quên ẩn danh** — không log tên máy, đường dẫn chứa tên người dùng.

**Kiểm tra nhanh**
- Profiler khi đang log nhiều: GC Alloc có tăng không?
- Alt-Tab ra rồi vào: log có được flush không?
- Log dùng `unscaledTime` chứ?
- Có dữ liệu định danh cá nhân nào trong log không? (không được)

Unity không cho sẵn trợ năng — nhưng phần lớn hạng mục chỉ cần **một biến toàn cục đặt đúng chỗ**, nếu làm từ đầu.

**Component & nơi đặt**
- `AccessibilitySettings` (ScriptableObject hoặc static class) — nguồn chân lý duy nhất
- Mọi hệ thống đọc từ đây, không ai tự quyết

**Code — một biến chặn mọi screenshake**

```csharp
public static class A11y {
    public static float ShakeScale = 1f;    // 0 = tắt hẳn
    public static float FontScale  = 1f;    // 1.0 - 1.5
    public static bool  ReduceFlashing;
    public static bool  HoldToToggle;       // giữ nút -> bấm chuyển
}
```

```csharp
public class CameraShake : MonoBehaviour {
    // ĐIỂM DUY NHẤT được phép rung camera trong toàn dự án
    public void Shake(float amplitude, float ms) {
        float a = amplitude * A11y.ShakeScale;
        if (a <= 0.01f) return;
        StartCoroutine(Run(a, ms / 1000f));
    }
}
```

Ràng buộc thật nằm ở chữ **duy nhất**. Nếu có 12 chỗ tự cộng vào `transform.position`, không công tắc nào tắt hết được. Viết test grep tìm vi phạm.

**Đổi phím — Input System làm sẵn**

Với package **Input System**, rebinding có sẵn API:

```csharp
action.PerformInteractiveRebinding(bindingIndex)
    .WithControlsExcluding("<Mouse>/position")
    .OnComplete(op => {
        op.Dispose();
        PlayerPrefs.SetString("binds", actions.SaveBindingOverridesAsJson());
    })
    .Start();
```

Đây là lý do đáng chuyển sang Input System: với Input Manager cũ, rebinding phải tự viết từ đầu.

**Cỡ chữ chỉnh được**

uGUI:
```csharp
// Layout PHẢI co giãn: dùng ContentSizeFitter, KHÔNG đặt height cố định
text.fontSize = Mathf.RoundToInt(baseSize * A11y.FontScale);
```

UI Toolkit: đặt `--fs-body` trong USS rồi đổi biến — cả cây UI scale theo, không phải sửa từng phần tử.

**Mù màu — mã hoá kép**

Unity không giúp gì ở đây, đây là quyết định thiết kế. Thực hiện: mọi chỗ phân biệt bằng màu phải kèm **sprite icon khác nhau**. Kiểm tra bằng cách chụp màn hình rồi convert grayscale — còn phân biệt được không?

**Kiểm tra nhanh**
- Grep `transform.position +=` trong code camera — chỉ được có một chỗ.
- Đặt `A11y.ShakeScale = 0`: chơi hết một màn, không còn rung nào?
- Đặt `FontScale = 1.5`: có chữ nào bị cắt hoặc tràn khung không?
- Ảnh chụp chuyển grayscale: còn phân biệt được bạn/thù không?

Trong Unity, adaptive music đứng hoặc chết ở một API: **`AudioSettings.dspTime`**. Dùng `Time.time` là lệch nhịp, không có ngoại lệ.

**Vì sao không dùng `Time.time`**

`Time.time` cập nhật mỗi frame và trôi so với đồng hồ audio. Sau vài phút, "chờ tới cuối ô nhịp" tính bằng `Time.time` lệch cả trăm mili giây — tai nghe ra ngay.

```csharp
// ✅ đồng hồ của audio thread, không trôi
double nextBarTime = startDspTime + barsPlayed * (60d / bpm * beatsPerBar);
```

**Phát đúng nhịp: `PlayScheduled`**

```csharp
public class AdaptiveMusic : MonoBehaviour {
    [SerializeField] AudioSource[] layers;     // cùng độ dài, cùng tempo
    [SerializeField] float bpm = 120f;
    [SerializeField] int beatsPerBar = 4;
    double startDsp;

    void Start() {
        // Lên lịch TẤT CẢ lớp cùng một mốc dsp -> không bao giờ lệch nhau
        startDsp = AudioSettings.dspTime + 0.2;    // đệm 200ms để kịp lên lịch
        foreach (var a in layers) {
            a.volume = 0f;
            a.loop = true;
            a.PlayScheduled(startDsp);             // KHÔNG dùng Play()
        }
    }

    public double SecondsToNextBar() {
        double barLen = 60d / bpm * beatsPerBar;
        double elapsed = AudioSettings.dspTime - startDsp;
        return barLen - (elapsed % barLen);
    }
}
```

Điểm mấu chốt: **mọi lớp `PlayScheduled` cùng một mốc và không bao giờ `Stop()`**. Chỉ đổi `volume`. `Stop()` rồi `Play()` lại sẽ lệch timeline và không cách nào đồng bộ lại.

**Fade equal-power, không tuyến tính**

```csharp
// Hai lớp cùng ở volume 0.5 tuyến tính cho tổng NĂNG LƯỢNG thấp hơn một lớp ở 1.0
// -> nghe như âm thanh bị tụt ở giữa đoạn chuyển
float t = Mathf.Clamp01(elapsed / fadeDuration);
outgoing.volume = Mathf.Cos(t * Mathf.PI * 0.5f);
incoming.volume = Mathf.Sin(t * Mathf.PI * 0.5f);
```

Đây là lỗi AI gần như luôn mắc nếu không nêu rõ.

**Hysteresis — chống rung lớp**

```csharp
// intensity dao động quanh 0.5 sẽ bật/tắt lớp drums liên tục, nghe như lỗi
bool drumsOn;
drumsOn = drumsOn ? intensity > 0.35f : intensity > 0.50f;
```

Nguồn `intensity` nên là [[ai-director]] — nó đã có sẵn chỉ số 0..1.

**Bẫy Unity cụ thể**
- **`AudioSettings.dspTime` không nhích khi `timeScale = 0`?** Sai — nó *vẫn chạy*, vì nó là đồng hồ audio thread. Đây là điều tốt: nhạc không đứng khi hitstop. Nhưng nghĩa là không dùng nó để đo thời gian gameplay.
- **`AudioSettings.OnAudioConfigurationChanged`** bắn khi người chơi cắm tai nghe — mọi `PlayScheduled` đang chờ bị mất. Phải lên lịch lại.
- **Lớp có độ dài khác nhau** → lệch sau vài vòng loop. Mọi clip phải cùng số ô nhịp.

**Kiểm tra nhanh**
- Chơi 10 phút liên tục: các lớp còn khớp nhau không?
- Cắm/rút tai nghe giữa lúc chơi: nhạc có tiếp tục không?
- Đổi lớp giữa đoạn: có nghe ra chỗ nối không? (không được)
- `intensity` rung quanh ngưỡng: lớp có bật tắt liên tục không?

Phần kiến trúc audio trong Unity nằm ở [[unity-audio]]. Mục này chỉ nói cách nối **quyết định thiết kế SFX** vào Unity.

**Layering trong Unity: một SFX = nhiều clip phát cùng lúc**

```csharp
[CreateAssetMenu(menuName = "Audio/Sfx Event")]
public class SfxEvent : ScriptableObject {
    [System.Serializable] public struct Layer {
        public AudioClip[] variants;    // shuffle bag, không random thuần
        public float volumeDb;
        public float delayMs;           // transient 0ms, body 0ms, tail có thể trễ
    }
    public Layer[] layers;
    public float pitchVariance = 0.08f;
    public int maxInstances = 3;
    public int priority = 128;          // 0 = cao nhất trong Unity, KHÔNG phải 255
}
```

`AudioSource.priority` trong Unity ngược trực giác: **0 là ưu tiên cao nhất**, 256 là thấp nhất. Đặt ngược là lý do âm thanh quan trọng bị cắt trước.

**Shuffle bag, không `Random.Range`**

```csharp
// Random thuần sẽ phát cùng một clip hai lần liền — tai nghe ra ngay
public class ShuffleBag {
    readonly int[] order; int cursor;
    public int Next() {
        if (cursor == 0) Shuffle();          // trộn lại khi hết lượt
        return order[cursor++ % order.Length];
    }
}
```

**Import settings quyết định RAM nhiều hơn code**

Bảng quyết định đầy đủ ở [[unity-audio]]. Tóm lại:

| Loại | Load Type | Compression |
|---|---|---|
| SFX ngắn, phát thường xuyên | Decompress On Load | ADPCM hoặc PCM |
| SFX dài, thưa | Compressed In Memory | Vorbis |
| Nhạc, ambience | Streaming | Vorbis |

Để nhạc ở `Decompress On Load` là cách nhanh nhất ăn hết 200MB RAM.

**Chia dải tần — làm được trong Unity**

AudioMixer có sẵn EQ effect. Đặt trên bus `Music`: cắt nhẹ 2–6 kHz (khoảng −3 dB) để nhường dải đó cho SFX gameplay. Đây là cách kỹ thuật thực hiện nguyên tắc ở phần trên, và nó hiệu quả hơn việc hạ toàn bộ âm lượng nhạc.

**Kiểm tra nhanh**
- Cho 20 viên đạn bắn cùng frame: có bị clip/méo không? (`maxInstances` phải chặn)
- `priority` của âm cảnh báo có **nhỏ hơn** âm phụ không?
- Profiler mục Audio: bao nhiêu voice đang phát? Vượt 32 là không ai nghe ra gì.
- Build ra máy thật: dung lượng RAM cho audio bao nhiêu?

Unity có sẵn AudioMixer — dùng nó, đừng tự quản volume bằng `AudioSource.volume` rải rác.

**Component & nơi đặt**
- `Assets/Audio/MainMixer.mixer` — một AudioMixer asset
- Bus = AudioMixerGroup con trong mixer đó
- `AudioManager.cs` — singleton, nơi duy nhất gọi `SetFloat` lên mixer

**Setup mixer (làm bằng tay trong Editor)**

1. `Assets > Create > Audio Mixer`
2. Tạo cây group: `Master > Music, SFX (> Player, Enemy, World), UI, Ambience`
3. Với mỗi group cần chỉnh từ code: chuột phải vào **Volume** trong Inspector → **Expose 'Volume' to script**
4. Ở cửa sổ Audio Mixer, góc trên phải **Exposed Parameters** → đổi tên thành `MusicVol`, `SfxVol`, `UiVol`, `AmbienceVol`

Bước 3 là bước hay bị quên — không expose thì `SetFloat` trả về `false` và không có gì xảy ra, **không báo lỗi**.

**Code — chuyển đổi slider sang dB**

```csharp
public class AudioManager : MonoBehaviour {
    [SerializeField] AudioMixer mixer;

    /// slider 0..1 -> dB. Tai người nghe theo thang logarit, nên KHÔNG
    /// gán tuyến tính — slider ở 0.5 phải là ~ -6 dB, không phải nửa biên độ.
    public void SetBusVolume(string exposedParam, float linear01) {
        float dB = linear01 <= 0.0001f
            ? -80f                                   // tắt hẳn
            : Mathf.Log10(Mathf.Clamp01(linear01)) * 20f;
        mixer.SetFloat(exposedParam, dB);
    }
}
```

Nếu bỏ qua công thức này, người chơi sẽ thấy slider "chỉ có tác dụng ở đoạn cuối" — lỗi cảm nhận rất phổ biến.

**Ducking bằng Snapshot**

AudioMixer có **Snapshot** — lưu lại toàn bộ trạng thái mixer và chuyển mượt giữa chúng:

```csharp
[SerializeField] AudioMixerSnapshot normal, ducked;

public void DuckForHit() {
    ducked.TransitionTo(0.04f);                          // attack 40ms
    StartCoroutine(Restore(0.4f));
}
IEnumerator Restore(float delay) {
    yield return new WaitForSeconds(delay);
    normal.TransitionTo(0.6f);                           // release 600ms
}
```

Cách này gọn hơn nhiều so với tự lerp từng bus, và Unity lo phần nội suy.

**Lưu ý version:** `AudioMixer.SetFloat` **không hoạt động trong `Awake()`** — mixer chưa khởi tạo xong. Gọi trong `Start()` hoặc muộn hơn.

**Kiểm tra nhanh**
- Grep `AudioSource.volume` và `.PlayOneShot` không qua bus — phải bằng 0.
- Kéo slider Music xuống 50%: có nghe giảm khoảng một nửa *độ to cảm nhận* không?
- Tạm dừng game: SFX tắt, nhạc vẫn chạy?

Unity có hai hệ UI. Chọn sai là làm lại từ đầu, nên quyết định trước khi vẽ màn hình đầu tiên.

**uGUI (Canvas) hay UI Toolkit?**

| | uGUI | UI Toolkit |
|---|---|---|
| Độ chín | Rất ổn định, tài liệu nhiều | Mới hơn, còn thay đổi |
| Trong world space | Có (Canvas World Space) | Hạn chế |
| Styling | Từng component | USS (giống CSS) — hợp design system |
| AI agent sửa được | Prefab là YAML, khó sửa tay | UXML/USS là text, **agent sửa tốt** |
| HUD game 2D/3D | Phù hợp | Phù hợp cho UI phẳng |

Với dự án làm cùng AI agent, **UI Toolkit có lợi thế rõ**: UXML và USS là text thuần, agent đọc và sửa trực tiếp được. uGUI thì mọi thứ nằm trong prefab YAML, sửa tay rất dễ hỏng.

**Setup bắt buộc: CanvasScaler**

Đây là thứ quyết định UI có scale đúng qua các độ phân giải hay không.

```
Canvas > Canvas Scaler
  UI Scale Mode : Scale With Screen Size
  Reference Resolution : 1920 x 1080
  Screen Match Mode : Match Width Or Height
  Match : 1   ← khớp theo CHIỀU CAO
```

`Match = 1` nghĩa là UI giữ tỉ lệ với chiều cao màn hình; màn rộng hơn chỉ có thêm khoảng trống hai bên. Đây là lựa chọn đúng cho hầu hết game — dễ đoán, và ultrawide không làm vỡ layout.

Để mặc định `Match = 0` (khớp theo chiều rộng) là lỗi phổ biến: trên màn hình cao, UI phình to vượt khung.

**Design system bằng USS (UI Toolkit)**

```css
:root {
  --space-1: 4px;  --space-2: 8px;  --space-3: 12px;
  --space-4: 16px; --space-6: 24px; --space-8: 32px;
  --fs-title: 32px; --fs-h2: 20px; --fs-body: 16px; --fs-small: 13px;
  --c-bg: #12161F;  --c-text: #E6E9F0;  --c-accent: #6EA8FE;
}
.btn {
  min-height: 44px;            /* vùng chạm tối thiểu */
  padding: var(--space-2) var(--space-4);
  font-size: var(--fs-body);
  background-color: var(--c-bg);
}
.btn:focus {                   /* BẮT BUỘC — điều hướng bàn phím/tay cầm */
  border-color: var(--c-accent);
  border-width: 2px;
}
```

**Điều hướng bằng tay cầm (uGUI)**

```csharp
// Mỗi màn hình phải set focus mặc định khi mở, nếu không tay cầm bấm vào hư không
void OnEnable() => EventSystem.current.SetSelectedGameObject(firstButton);
```

Và kiểm tra `Navigation` của mỗi `Selectable` — chế độ `Automatic` thường đoán sai ở layout phức tạp; khi đó set `Explicit` và nối tay.

**Kiểm tra nhanh**
- Chạy ở 1920×1080, 1280×800, 2560×1080 — UI có vỡ không?
- Rút chuột ra, chỉ dùng bàn phím: tới được mọi nút chứ?
- Mọi nút có `:focus` / `Selected` state nhìn thấy rõ không? Xem [[accessibility]].

Luồng menu trong Unity là câu hỏi **scene hay panel**, và trả lời sai thì mọi màn hình sau đều mệt.

**Scene hay panel?**

| | Scene riêng | Panel trong một scene |
|---|---|---|
| Tải | Có màn hình loading | Tức thì |
| Trạng thái | Reset sạch | Phải tự dọn |
| Quay lại game | Load lại scene game | Chỉ tắt panel |
| Phù hợp | Main menu | Pause, settings, inventory |

Kết hợp thường dùng: **một `Bootstrap` scene luôn tồn tại** (chứa AudioManager, ConfigLoader, UI Root), cộng scene gameplay load additive. Main menu là panel trong Bootstrap, không phải scene riêng. Chi tiết ở [[unity-game-loop]].

**UI phải chạy khi `timeScale = 0`**

Đây là bẫy làm mất cả buổi:

```csharp
// ❌ đứng mãi khi pause
yield return new WaitForSeconds(0.3f);

// ✅
yield return new WaitForSecondsRealtime(0.3f);
```

Và với Animator trên UI: `Update Mode = Unscaled Time`. Với Input System, Actions vẫn chạy khi pause (tốt), nhưng `Time.deltaTime` bằng 0 — mọi animation UI tính theo `unscaledDeltaTime`.

**Settings áp dụng ngay — đừng bắt Apply**

```csharp
volumeSlider.onValueChanged.AddListener(v => {
    AudioManager.I.SetBusVolume("MusicVol", v);   // hiệu lực ngay
    settings.musicVolume = v;
    settings.SaveDebounced();                      // ghi file sau 0.5s im lặng
});
```

`SaveDebounced` quan trọng: `onValueChanged` bắn mỗi frame khi kéo slider, ghi file mỗi frame sẽ giật.

**Lưu game — ghi atomic, luôn giữ backup**

Chi tiết ở [[unity-save-data]]. Điểm tối thiểu:

```csharp
// Ghi ra file tạm rồi đổi tên. Tắt máy giữa lúc ghi không làm hỏng save cũ.
File.WriteAllText(tmp, json);
if (File.Exists(path)) File.Replace(tmp, path, backup);
else File.Move(tmp, path);
```

**Không dùng `PlayerPrefs` cho tiến trình.** Nó nằm trong registry (Windows), không sao lưu được, và giới hạn kích thước. `PlayerPrefs` chỉ cho settings.

**Điều hướng tay cầm — focus mặc định mỗi màn hình**

```csharp
void OnEnable() {
    EventSystem.current.SetSelectedGameObject(null);   // xoá focus cũ trước
    EventSystem.current.SetSelectedGameObject(firstButton);
}
```

Bước `SetSelectedGameObject(null)` trước là cần thiết — nếu không, mở lại cùng panel đôi khi không đổi focus.

**Kiểm tra nhanh**
- Pause game rồi mở settings: animation UI còn chạy không?
- Kéo slider âm lượng liên tục 5 giây: có ghi file mỗi frame không?
- Rút chuột, chỉ dùng bàn phím: tới được mọi màn hình và thoát ra được chứ?
- Tắt game giữa lúc đang lưu (Task Manager): save cũ còn nguyên không?

HUD là nơi Canvas rebuild giết frame rate. Quyết định thiết kế "hiện cái gì" ảnh hưởng trực tiếp tới hiệu năng, và đó là điều ít ai nối lại với nhau.

**Nguyên tắc Unity quan trọng nhất: phân tầng Canvas theo tần suất đổi**

```
Canvas_Static     ← khung, nền, icon không đổi          (rebuild: gần như không bao giờ)
Canvas_Frequent   ← thanh máu, cooldown, số đạn          (rebuild: nhiều lần/giây)
Canvas_Rare       ← tên màn, mục tiêu, buff              (rebuild: vài giây một lần)
Canvas_Overlay    ← số sát thương bay lên                (pool, không Instantiate)
```

Một phần tử đổi làm **rebuild toàn bộ Canvas chứa nó**. Nhét thanh máu (đổi 60 lần/giây) cùng Canvas với khung tĩnh nghĩa là rebuild cả khung 60 lần/giây. Tách ra là xong — chi tiết ở [[unity-ui]].

Điều này nối thẳng với bài test câu hỏi ở phần trên: **phần tử nào được hỏi liên tục thì nằm Canvas riêng**, phần tử hỏi thỉnh thoảng thì Canvas khác. Thiết kế và hiệu năng cùng một câu trả lời.

**Máu thấp đọc bằng thị giác ngoại vi**

Không làm bằng cách phóng to thanh máu. Làm bằng post-processing toàn màn hình:

```csharp
// URP: Volume có Vignette + Color Adjustments, điều khiển weight theo HP
[SerializeField] Volume lowHpVolume;

void OnHealthChanged(float hp01) {
    // chỉ bắt đầu hiện dưới 30% máu
    lowHpVolume.weight = Mathf.InverseLerp(0.3f, 0.05f, hp01);
}
```

`Volume.weight` rẻ và không gây Canvas rebuild. Nhớ nhân với hệ số trợ năng nếu người chơi đã tắt hiệu ứng mạnh — xem [[accessibility]].

**Số sát thương bay lên — pool, đừng Instantiate**

```csharp
// 20 con quái trúng đòn cùng lúc = 20 Instantiate + 20 TMP_Text mới = giật
readonly ObjectPool<DamageNumber> pool = new(...);
```

Và dùng `TMP_Text.SetText("{0}", value)` chứ không `text = value.ToString()` — bản đầu không cấp phát.

**Chỉ báo hướng nguy hiểm ở rìa màn hình**

```csharp
// Chuyển vị trí thế giới thành góc quanh tâm màn hình
Vector3 vp = cam.WorldToViewportPoint(threat.position);
bool offScreen = vp.z < 0 || vp.x is < 0 or > 1 || vp.y is < 0 or > 1;
if (offScreen) {
    Vector2 dir = ((Vector2)vp - Vector2.one * 0.5f).normalized;
    arrow.anchoredPosition = dir * edgeRadius;
    arrow.up = dir;
}
```

Kiểm tra `vp.z < 0` là bắt buộc — mục tiêu sau lưng camera cho viewport point đảo dấu, thiếu nó thì mũi tên chỉ ngược.

**Kiểm tra nhanh**
- Profiler mục `Canvas.BuildBatch` / `Canvas.SendWillRenderCanvases`: dưới 1ms?
- Đặt breakpoint: thanh máu đổi có làm rebuild Canvas chứa khung tĩnh không?
- Số sát thương: GC Alloc = 0 B khi 20 con trúng đòn cùng lúc?

nodes.body:
Hai quyết định định hình toàn bộ phần animation của dự án. **Một:** Animator Controller chỉ *hiển thị* trạng thái do code quyết định, hay nó *là* state machine của nhân vật? Chọn cách hai thì tháng thứ ba bạn sẽ có một đồ thị 60 state không ai dám sửa và luật chơi nằm trong file binary. **Hai:** dùng Animator, hay điều khiển clip hoàn toàn bằng code (Playables/Animancer, hoặc tự đổi sprite)? Câu trả lời phụ thuộc vào số state và ai chỉnh chúng — designer cần nhìn đồ thị, lập trình viên cần code đọc được.

Lý thuyết frame 1, frame data, cancel đã ở [[animation-game]] và [[combat-systems]]. Node này chỉ nói cách làm những điều đó trong Unity mà không hỏng.

## Đồ thị Animator thành spaghetti sau 30 state

Đồ thị Animator không có công cụ refactor. Không diff được trên Git, không tìm-thay được, và mỗi transition là một đường vẽ tay. Ở 10 state nó dễ hiểu, ở 30 state nó là mạng nhện, ở 60 state chỉ người vẽ ra nó mới sửa được — và người đó đã nghỉ.

Ba kỹ thuật giữ đồ thị đọc được:

- **Sub-State Machine** theo nhóm hành vi: `Locomotion`, `Combat`, `Airborne`, `Hurt`. Mỗi sub-machine dưới 10 state, transition giữa các nhóm đi qua Entry/Exit. Quy tắc: nếu phải kéo một đường xuyên qua hai nhóm, hãy tự hỏi có nên chuyển bằng `CrossFade` từ code không.
- **Any State chỉ dành cho thứ thật sự đến từ bất kỳ đâu** — `Hurt`, `Death`, `Stun`. Mỗi transition từ Any State là *N* transition ẩn (N = số state). Có 8 đường từ Any State với 40 state là 320 transition được đánh giá mỗi frame, và quan trọng hơn là không ai lần ra được vì sao nhân vật nhảy sang `Idle`. Bỏ tick **Can Transition To Self** trên các transition này — không thì `Hurt` khởi động lại mỗi frame khi tham số còn true, và animation bị đánh "kẹt ở frame 0".
- **Layer + Avatar Mask cho thân trên.** Bắn súng khi chạy không phải một state `RunShoot` — nó là layer `UpperBody` (weight 1, blending Override, mask từ xương spine lên) phát `Shoot` trên nền `Run` của Base Layer. Thêm layer `Additive` weight 0.3 cho thở/lắc đầu là cách rẻ nhất để đám NPC không trông như tượng. Mỗi layer là một lần đánh giá skeleton thêm, nên 2–3 layer là đủ; 6 layer là dấu hiệu đang lấy layer thay cho code.

## Has Exit Time và Transition Duration — hai con số quyết định "chậm"

Transition mặc định của Unity: `Has Exit Time` bật, `Exit Time` 0.75, `Transition Duration` 0.25s. Dịch sang cảm giác: nhân vật chạy hết ¾ animation hiện tại rồi mới bắt đầu chuyển sang hành động bạn vừa bấm, và mất thêm 250ms để chuyển xong. Đó là 400–600ms trễ được cài sẵn vào mọi dự án mới.

Bảng dùng trong thực tế:

| Transition | Has Exit Time | Duration (Fixed) | Interruption Source |
|---|---|---|---|
| → Attack, Dodge, Jump (người chơi khởi xướng) | **Tắt** | 0.05–0.1s | Current State (cho phép cancel) |
| → Hurt, Death | **Tắt** | **0** | Current State |
| Idle ↔ Walk/Run | Tắt | 0.1–0.15s | None |
| Attack → Idle (thu về) | Bật, Exit Time 1.0 | 0.15–0.2s | Next State |
| Jump → Fall | Tắt, điều kiện `VelocityY < 0` | 0.1s | None |

Đổi **Fixed Duration** thành bật (đơn vị giây) thay vì normalized — 0.1 normalized trên clip 2 giây là 200ms, trên clip 0.3 giây là 30ms, bạn không thể tinh chỉnh cảm giác bằng số nhảy múa theo độ dài clip.

Tham số kiểu **Trigger** là cái bẫy thứ hai: trigger được xếp hàng và chờ tới khi có transition nào tiêu thụ. Người chơi bấm đánh lúc đang `Hurt` (không có transition Hurt → Attack), 1 giây sau hết Hurt về Idle, trigger còn đó, nhân vật tự vung tay. Gọi `animator.ResetTrigger(AttackHash)` mỗi khi vào state không nhận đòn, hoặc bỏ trigger mà dùng `CrossFade` từ code.

## Blend Tree cho locomotion và bẫy chân trượt

Blend Tree 1D theo `Speed` cho Idle/Walk/Run, 2D Freeform Directional theo `(VelX, VelZ)` cho strafe — đây là chỗ Animator thật sự giỏi và code khó thay. Bẫy nằm ở **threshold**: clip Run được diễn hoạt ở 5 m/s (đo bằng "Compute Thresholds → Speed" từ root motion của clip), nhưng code cho nhân vật chạy 6.5 m/s → chân đạp chậm hơn mặt đất 30%, trượt như đi trên băng. Ba cách sửa theo thứ tự nên chọn: đổi tốc độ code cho khớp clip; đặt threshold đúng tốc độ thật của clip và để blend tree co giãn; hoặc nhân `animator.speed` theo tỉ lệ `velocity / clipSpeed` (chỉ với locomotion, không được ảnh hưởng đòn đánh — dùng tham số `Multiplier` trên motion trong blend tree thay vì `animator.speed` toàn cục).

Giá trị đưa vào tham số Blend Tree phải **làm mịn** (`SetFloat(hash, value, 0.1f, Time.deltaTime)` — bản có damp time), không thì Walk → Run nhảy phựt khi người chơi nghiêng stick.

## Điều khiển bằng code: hash, CrossFade, và đọc trạng thái đúng chỗ

```csharp
public class CharacterAnimator : MonoBehaviour {
    [SerializeField] Animator anim;
    static readonly int SpeedHash  = Animator.StringToHash("Speed");
    static readonly int AttackL    = Animator.StringToHash("Attack_Light");
    static readonly int Hurt       = Animator.StringToHash("Hurt");

    public void SetSpeed(float v) => anim.SetFloat(SpeedHash, v, 0.1f, Time.deltaTime);

    // Duration tính bằng GIÂY (InFixedTime), không phụ thuộc độ dài clip đích
    public void PlayAttackLight() => anim.CrossFadeInFixedTime(AttackL, 0.05f, 0);
    public void PlayHurt()        => anim.CrossFadeInFixedTime(Hurt, 0f, 0, 0f);   // cắt thẳng, từ frame 0

    // Đọc trạng thái CHỈ cho presentation (VFX, âm bước chân) — không cho luật chơi
    public bool AttackAnimNearEnd() {
        var s = anim.GetCurrentAnimatorStateInfo(0);
        return s.shortNameHash == AttackL && s.normalizedTime >= 0.9f && !anim.IsInTransition(0);
    }
}
```

`Animator.StringToHash` không chỉ để tiết kiệm vài µs — nó bắt lỗi chính tả ở một chỗ thay vì rải `"Atack_Light"` khắp 12 file. Khi state trên 20, `CrossFade` từ code thay cho transition vẽ tay: đồ thị chỉ còn các state và vài transition "thu về", còn *ai được sang đâu* nằm trong bảng cancel bằng dữ liệu, test được. `CrossFade` (không InFixedTime) nhận duration **normalized theo clip đích** — 0.1 trên clip 0.2s là 20ms, chính là nguồn của "blend lúc nhanh lúc chậm không hiểu vì sao".

## Animation Event không đáng tin — và thay bằng gì

Animation Event được kích khi thời gian clip **đi qua** mốc. Nếu một transition cắt ngang trước mốc, event không bao giờ chạy: âm rút kiếm không có, particle trail không tắt, cờ `isAttacking` không hạ. Nếu blend hai clip cùng có event thì cả hai đều chạy. Và event gọi hàm **bằng tên qua reflection** — đổi tên hàm không báo lỗi biên dịch, IL2CPP với stripping High có thể xoá hàm không ai gọi trực tiếp (đánh `[Preserve]` lên nó).

Dùng Animation Event cho thứ **được phép mất**: bước chân, bụi, tia sáng. Thứ phải đảm bảo xảy ra dùng một trong hai:

```csharp
// Gắn lên state Attack trong Animator. OnStateExit LUÔN chạy dù bị cắt ngang.
public class AttackStateBehaviour : StateMachineBehaviour {
    public override void OnStateExit(Animator animator, AnimatorStateInfo info, int layer) {
        animator.GetComponentInParent<AttackExecutor>()?.OnAttackAnimEnded();   // chỉ chạy lúc thoát state, không phải mỗi frame
    }
}
```

hoặc kiểm `normalizedTime` trong `Update` như hàm `AttackAnimNearEnd` ở trên. `StateMachineBehaviour` không serialize tham chiếu scene, nên nó phải tìm component qua Animator — chấp nhận được vì chỉ chạy lúc vào/ra state.

## Hitbox: bật/tắt collider con, nguồn chân lý là frame data

Hitbox theo animation làm bằng nhiều `Collider` con tắt sẵn, mỗi đòn bật đúng collider của nó trong khoảng active — [[combat-systems]] đã có `AttackExecutor` đếm frame bằng `WaitForFixedUpdate`. Điều Unity thêm vào: **không scale collider theo animation**, engine dựng lại shape mỗi lần đổi kích cỡ (xem [[unity-physics]]); 3 collider cố định bật/tắt rẻ hơn 1 collider scale. Nếu team nhất định muốn animator đặt hitbox bằng Animation Event, viết một Editor test đọc mọi event trong clip và đối chiếu với `AttackData` — không thì tuần nào cũng có đòn "trúng mà không ăn".

Với 2D, hitbox theo frame chuẩn nhất là **mảng `Collider2D[] hitboxPerFrame`** trong ScriptableObject của đòn, bật theo chỉ số frame — không cần Animator biết gì cả.

## Root motion hay code-driven

[[animation-game]] đã nêu lý do game hành động nhanh nên code-driven. Phần Unity: root motion **bật** = `Animator` ghi `transform` mỗi frame trong `OnAnimatorMove`, đè lên mọi thứ Rigidbody tính, nên bạn phải chọn một. Kết hợp đúng cách khi muốn "đòn lao tới" có khoảng dịch chuyển từ animation nhưng va chạm vẫn đúng:

```csharp
void OnAnimatorMove() {
    // Lấy quãng dịch từ animation, đưa qua Rigidbody để va chạm vẫn hoạt động
    rb.MovePosition(rb.position + anim.deltaPosition);
    rb.MoveRotation(rb.rotation * anim.deltaRotation);
}
```

Nếu có `OnAnimatorMove` thì Unity không tự áp dụng root motion nữa — bạn kiểm soát hoàn toàn, kể cả nhân với hệ số để designer chỉnh tầm lao mà không đụng clip. Chọn root motion khi nhịp chậm, chân thực, và nhân vật không cần đổi hướng giữa đòn. Chọn code-driven cho mọi thứ khác — và tắt **Apply Root Motion** trên Animator, vì bật nó với clip có xương root dịch chuyển nhẹ là nhân vật "trôi" 2cm mỗi vòng idle.

## Khi Animator không xứng

**3D với nhiều clip từ dữ liệu** (mỗi vũ khí một bộ đòn, moveset nạp từ ScriptableObject): Animator Controller bắt bạn kéo mọi clip vào đồ thị trước. **Animancer** (trả phí, ~2 ngày học) hoặc **Playables API** (có sẵn, dài dòng) cho phép `Play(clip, fadeSeconds)` bất kỳ clip nào, layer và mask từ code, không có đồ thị. Ngưỡng chuyển: trên 40 state, hoặc clip được chọn bằng dữ liệu. Dưới đó Animator vẫn đúng vì designer nhìn được.

**2D sprite animation:** Animator cho một nhân vật 8 clip là dùng dao mổ trâu — mỗi Animator tốn ~0.02–0.05ms/frame kể cả đứng yên, 200 kẻ địch là 4–10ms. Tự đổi sprite theo chỉ số frame rẻ hơn 20 lần và điều khiển frame chính xác:

```csharp
public class SpriteFlipbook : MonoBehaviour {
    [SerializeField] SpriteRenderer sr;
    Sprite[] frames; float fps; bool loop; float t; int index;

    public bool Finished => !loop && frames != null && index >= frames.Length - 1;
    public int  Frame    => index;                    // dùng để bật hitbox theo frame

    public void Play(Sprite[] clip, float clipFps = 12f, bool clipLoop = true) {
        frames = clip; fps = clipFps; loop = clipLoop; t = 0f; index = 0;
        sr.sprite = frames[0];
    }

    void Update() {
        if (frames == null) return;
        t += Time.deltaTime * fps;
        int next = loop ? (int)t % frames.Length : Mathf.Min((int)t, frames.Length - 1);
        if (next != index) { index = next; sr.sprite = frames[index]; }
    }
}
```

Skin/trang bị cho 2D dùng **Sprite Library** (package 2D Animation): `SpriteResolver.SetCategoryAndLabel("Body", "Idle_03")` — một bộ animation, N bộ sprite, không nhân đôi clip cho mỗi skin.

## Timing: timeScale, updateMode, và pool

- `Animator.updateMode`: `Normal` cho nhân vật — hitstop bằng `timeScale = 0` phải làm animation đứng theo. `UnscaledTime` cho UI và menu pause. **`Fixed`** (Unity 6; bản 2022 gọi là `AnimatePhysics`) cho nhân vật di chuyển bằng Rigidbody có root motion — Animator cập nhật cùng nhịp physics, hết rung lệch 50/60Hz.
- **Pool:** GameObject tắt rồi bật lại, Animator mặc định **reset về state mặc định và xoá tham số** — kẻ địch từ pool ra ở `Idle` khi code nghĩ nó đang `Death`. Bật `animator.keepAnimatorStateOnDisable = true` nếu muốn giữ, hoặc gọi `animator.Rebind(); animator.Update(0f);` ngay khi lấy từ pool để về trạng thái sạch **rồi** đặt tham số. Không gọi `Update(0f)` thì frame đầu tiên hiện pose của lần dùng trước.
- **Culling:** `Cull Update Transforms` cho NPC — ngoài màn hình vẫn chạy state machine nhưng không ghi bone. `Cull Completely` làm root motion và Animation Event dừng hẳn, NPC "đóng băng" rồi teleport khi vào tầm.

## Tween cho UI và thứ procedural — không dùng Animator

Animator trên phần tử UGUI đánh dấu **Canvas dirty mỗi frame** kể cả khi giá trị không đổi → Canvas rebuild liên tục, đúng thứ [[unity-ui]] bảo tránh. Nút phóng to khi hover, panel trượt vào, số điểm đếm lên: dùng **DOTween** hoặc **PrimeTween** (không cấp phát), 0.15–0.25s, ease OutBack cho popup, OutQuad cho trượt. Tween cũng đúng cho thứ procedural trong gameplay: squash & stretch khi tiếp đất, đổi màu chớp trắng, lắc vật phẩm — mọi thứ ở [[game-feel]] chỉnh bằng số, không cần clip.

**Animation Rigging / IK** (`TwoBoneIKConstraint` cho chân bám dốc, `MultiAimConstraint` cho đầu nhìn theo) chỉ khi camera đủ gần để thấy chân lơ lửng. Mỗi constraint tốn ~0.05–0.1ms/nhân vật trên mobile; bật cho nhân vật chính, tắt hẳn cho đám đông.

## Bẫy lộ ra khi build

- **Humanoid vs Generic:** Humanoid retarget mọi frame, đắt gấp ~1.5–2 lần Generic. Chỉ dùng Humanoid khi thật sự chia sẻ clip giữa các rig khác nhau.
- **Optimize Game Objects** trên rig import xoá transform của xương → `transform.Find("Hand_R")` để gắn vũ khí trả về null. Khai xương cần giữ trong **Extra Transforms to Expose**.
- **Anim. Compression = Optimal** (mặc định) làm ngón tay, mắt rung nhẹ ở clip chậm. Đổi thành Keyframe Reduction với Rotation Error 0.1 cho nhân vật chính; giữ Optimal cho đám đông.
- Animation Event gọi hàm bị strip trong IL2CPP — chỉ lộ trên build, log `AnimationEvent has no receiver`. Đánh `[Preserve]`.
- `Animator` trên object có `Rigidbody` non-kinematic với **Apply Root Motion** bật: hai hệ cùng ghi transform, nhân vật rung. Chọn một.

## Kiểm tra nhanh
- Bấm đòn đánh lúc đang chạy, quay màn hình 60fps: hình đổi trong **≤ 2 frame**?
- Base Layer < 30 state, Any State ≤ 3 transition, mọi transition từ Any State đã bỏ Can Transition To Self?
- Nhân vật chạy tốc độ tối đa cạnh một hàng ô 1m: chân trượt hơn 10cm mỗi bước không?
- Profiler `Animators.Update` với 50 nhân vật trong tầm nhìn < 2ms; ra khỏi tầm nhìn còn < 0.5ms?
- Lấy kẻ địch từ pool 10 lần liên tiếp sau khi chết: lần nào cũng ra ở Idle frame 0?

Kiến trúc bus, mức dB tham chiếu, ducking, và công thức slider → dB đã nằm ở [[audio-implementation]] (kể cả code `SetBusVolume` và Snapshot). Node này bắt đầu từ chỗ đó kết thúc: **những quyết định Unity-specific mà sound designer không thấy và lập trình viên không biết là mình đã quyết**.

Hai quyết định đắt nhất: **import settings của từng loại clip** (sai là ăn 200 MB RAM hoặc khựng 80 ms mỗi lần phát) và **cách phát nhạc** (`Play()` + timer không bao giờ khớp nhịp, dù code trông đúng).

## AudioMixer — ba thứ ngoài bus

**Snapshot cho trạng thái, không chỉ cho ducking.** Mỗi trạng thái game có một snapshot: `Normal`, `Paused` (lowpass 800 Hz trên Master, Music −6 dB, SFX −80), `Underwater`, `Menu`. Chuyển bằng `snapshot.TransitionTo(0.25f)`. Rẻ hơn viết state machine audio riêng, và sound designer chỉnh trong Editor không cần code. Giới hạn: snapshot lưu **giá trị**, không lưu bật/tắt effect — effect luôn chạy, chỉ tham số đổi; lowpass cutoff 22000 Hz coi như tắt.

**Expose parameter phải làm bằng tay** — chuột phải vào tham số → *Expose to script* — và `SetFloat` trả `false` âm thầm nếu quên. Đặt tên expose vào một `static class MixerParams` với `const string`, không rải string khắp code.

**Volume expose là dB, không phải 0–1.** Slider 0–1 → `Mathf.Log10(Mathf.Max(v, 0.0001f)) * 20f`. Người mới gán thẳng `SetFloat("MusicVol", slider.value)` và slider chỉ có tác dụng ở 0.9–1.0 vì mixer nhận 0 dB = full, 1 = +1 dB.

`AudioMixer.SetFloat` không chạy trong `Awake` (mixer chưa init) — gọi từ `Start` trở đi, và **snapshot đang transition đè lên `SetFloat`** cho cùng tham số. Tham số người chơi chỉnh (volume bus) không được nằm trong snapshot; để snapshot đụng effect và các group con thôi.

## Pool AudioSource — không PlayOneShot, không PlayClipAtPoint

`audioSource.PlayOneShot(clip)` trên một source chung: không dừng được từng tiếng, mọi tiếng chung `pitch`/`volume`/`spatialBlend` của source đó, không biết cái nào đang phát để giới hạn instance. Đủ cho prototype, hỏng khi cần `maxInstances` như [[audio-design]] yêu cầu.

`AudioSource.PlayClipAtPoint` tệ hơn: tạo GameObject "One shot audio" **mới mỗi lần gọi**, `Destroy` sau khi hết clip, và **không đi qua AudioMixerGroup nào** — tiếng đó lọt khỏi bus, settings volume không đụng được, ducking vô hiệu. Cấm trong codebase; grep khi review.

Pool 8–16 `AudioSource` cho SFX là đủ cho game 2D/3D indie (voice tổng 24–32 tính cả nhạc và ambience):

```csharp
public class SfxPool : MonoBehaviour {
    [SerializeField] AudioMixerGroup sfxGroup;
    [SerializeField, Range(4, 32)] int size = 12;
    AudioSource[] pool; int cursor;

    void Awake() {
        pool = new AudioSource[size];
        for (int i = 0; i < size; i++) {
            var src = new GameObject($"Sfx_{i}").AddComponent<AudioSource>();
            src.transform.SetParent(transform, false);
            src.outputAudioMixerGroup = sfxGroup;       // mọi tiếng qua bus, không ngoại lệ
            src.playOnAwake = false;
            src.dopplerLevel = 0f;                      // Doppler tắt, xem audio-implementation
            src.rolloffMode = AudioRolloffMode.Linear;
            src.minDistance = 2f; src.maxDistance = 30f;
            pool[i] = src;
        }
    }

    public AudioSource Play(AudioClip clip, Vector3 pos, float volume = 1f,
                            float spatialBlend = 1f, int priority = 128, float pitchVar = 0.05f) {
        var src = Acquire();
        src.transform.position = pos;
        src.clip = clip;
        src.volume = volume;
        src.spatialBlend = spatialBlend;                // 0 = 2D (UI, cảnh báo boss), 1 = 3D
        src.priority = priority;                        // 0 cao nhất … 256 thấp nhất
        src.pitch = 1f + Random.Range(-pitchVar, pitchVar);
        src.Play();
        return src;                                     // caller giữ để Stop nếu cần
    }

    AudioSource Acquire() {
        for (int i = 0; i < pool.Length; i++) {
            var s = pool[(cursor + i) % pool.Length];
            if (!s.isPlaying) { cursor = (cursor + i + 1) % pool.Length; return s; }
        }
        var victim = pool[0];                           // hết source: cướp tiếng ít quan trọng nhất
        foreach (var s in pool) if (s.priority > victim.priority) victim = s;
        return victim;
    }
}
```

Quy tắc `priority` phải viết ra: nhạc 0, giọng/cảnh báo boss 16, đòn trúng người chơi 32, nổ 48, đòn thường 96, bước chân/va chạm nhỏ 200. Không đặt thì mọi thứ 128 và Unity cắt ngẫu nhiên.

## Import settings — bảng quyết định

Đây là phần lập trình viên phải làm chủ, vì mặc định của Unity (`Vorbis`, `Decompress On Load`, quality 100) sai cho **mọi** loại clip.

| Loại clip | Load Type | Compression | Vì sao | 1 phút stereo 44.1k chiếm |
|---|---|---|---|---|
| SFX ngắn < 1 s, phát nhiều (đòn, bước chân, UI) | Decompress On Load | **ADPCM** (hoặc PCM nếu < 0.2 s và cần sạch) | Phát tức thì, giải nén 1 lần lúc load, CPU gần 0 khi phát | ~2.6 MB (ADPCM 3.5:1) |
| SFX dài 1–10 s, ít phát (kết liễu, cutscene) | Compressed In Memory | Vorbis q 0.5–0.7 | Không chiếm RAM PCM, giải nén lúc phát tốn CPU nhưng ít instance | ~1.1 MB |
| Nhạc 1–5 phút | **Streaming** | Vorbis q 0.6–0.8 | Không nạp vào RAM, đọc từ đĩa ~200 KB buffer; tối đa 2–4 stream cùng lúc | ~1.2 MB trên đĩa, ~0.2 MB RAM |
| Ambience loop 20–60 s | Compressed In Memory | Vorbis q 0.4–0.6 | Streaming nhiều file loop cùng lúc làm seek đĩa; in-memory nén là cân bằng | ~0.8 MB |
| Giọng nói | Streaming hoặc Compressed In Memory | Vorbis q 0.5 | Nhiều file, mỗi file phát một lần | — |

Đối chiếu: **PCM không nén 1 phút stereo = 10.6 MB**. Nhạc `Decompress On Load` + Vorbis là bẫy kinh điển: Unity giải nén Vorbis ra PCM đầy đủ lúc load → 3 bài nhạc 3 phút = 95 MB RAM trên điện thoại 3 GB, và load scene khựng 400 ms để giải nén.

Ba checkbox đi kèm:
- **Force To Mono** cho mọi SFX 3D. Spatializer trộn về mono trước khi pan; giữ stereo là tốn gấp đôi RAM cho thứ bị vứt đi. Chỉ giữ stereo cho nhạc, ambience 2D, và UI có ý đồ stereo.
- **Sample Rate: Override 22050 Hz** cho SFX không có nội dung > 10 kHz (bước chân, va chạm trầm, UI trầm). Giảm nửa RAM, tai không phân biệt trong game. Không đụng nhạc và cymbal/kính vỡ.
- **Load In Background** cho clip > 1 s để `LoadAudioData` không chặn main thread; **Preload Audio Data** tắt cho clip hiếm dùng — nhưng phải tự gọi `clip.LoadAudioData()` trước khi cần (lúc load level, khi enemy spawn), không thì **lần đầu phát khựng 20–80 ms** đúng lúc đòn trúng. Đó là lý do "tiếng nổ đầu tiên mỗi màn bị trễ" mà không ai đo ra.

Ép settings theo thư mục bằng `AssetPostprocessor` ([[unity-editor-tools]]) — `Assets/Audio/SFX/` = ADPCM + mono + Decompress, `Assets/Audio/Music/` = Vorbis + Streaming. Không dựa vào tay người.

## Nhạc đúng nhịp: `PlayScheduled` và `dspTime`

`source.Play()` bắt đầu ở lần mixer tick kế tiếp — trễ 5–20 ms không xác định. Coroutine `WaitForSeconds(barLength)` rồi `Play()` lệch cộng dồn theo frame time. Với nhạc, cách duy nhất chính xác đến mẫu là **lịch theo đồng hồ DSP**:

```csharp
public class MusicScheduler : MonoBehaviour {
    [SerializeField] AudioSource[] layers;      // vertical layering: cùng độ dài, cùng BPM
    [SerializeField] float bpm = 120f;
    [SerializeField] int beatsPerBar = 4;
    double startDsp;

    public void StartAll() {
        startDsp = AudioSettings.dspTime + 0.2;             // 200 ms lead để mọi source kịp prepare
        foreach (var l in layers) { l.loop = true; l.PlayScheduled(startDsp); }
        // sau đó CHỈ đổi l.volume — không Play/Stop từng layer, xem adaptive-music
    }

    double BarLength => 60.0 / bpm * beatsPerBar;

    public double NextBarDsp() {
        double elapsed = AudioSettings.dspTime - startDsp;
        return startDsp + (System.Math.Floor(elapsed / BarLength) + 1) * BarLength;
    }

    /// Horizontal resequencing: đoạn mới vào đúng đầu ô nhịp, đoạn cũ kết thúc cùng thời điểm.
    public void SwitchSegment(AudioSource current, AudioSource next, AudioSource stinger = null) {
        double t = NextBarDsp();
        if (t - AudioSettings.dspTime < 0.05) t += BarLength;   // quá gần, dời sang ô sau
        next.PlayScheduled(t);
        current.SetScheduledEndTime(t);
        if (stinger) stinger.PlayScheduled(t - 0.12);           // stinger đè lên chỗ nối, xem adaptive-music
    }
}
```

Điểm mấu chốt: `dspTime` là `double`, độc lập `Time.timeScale` và frame rate. **Mọi phép tính nhịp dùng `double`**, không ép về `float` — sai số float sau 10 phút là vài ms, đủ nghe lệch.

**Loop không khớp:** Vorbis và ADPCM loop sạch nếu file được cắt đúng ở DAW; MP3 có padding đầu/cuối từ encoder → **không bao giờ dùng MP3 cho loop**. Loop kiểu "intro rồi vào loop" làm bằng hai clip và `PlayScheduled(startDsp + intro.length)` cho clip loop, không dùng `loopStart`.

**Crossfade** dùng đường equal-power (`cos`/`sin` của góc), không tuyến tính — [[adaptive-music]] có lý do. Fade volume trên `AudioSource.volume` là tuyến tính amplitude, nên `volume = Mathf.Cos(t * Mathf.PI / 2)` cho bên ra và `Sin` cho bên vào.

## 3D sound — số thực tế

Mặc định `Logarithmic Rolloff`, min 1, max 500. Nghĩa là: ở 500 m **vẫn nghe** (log không về 0, chỉ clamp ở max). Đây là lý do người chơi nghe bước chân enemy ở đầu kia bản đồ.

- **Linear** với min 2–3, max 25–40 (đơn vị thế giới) cho game hành động: designer đoán được "ngoài 30 m là im".
- **Custom curve** khi cần "gần thì to đều, xa thì tụt nhanh" — vẽ trong Inspector, và lưu thành preset để dùng chung.
- **Spread** 0 = điểm, 180 = bao quanh. Đặt 40–60 cho tiếng người chơi tự phát ra (bước chân của mình) để không "nhảy" trái phải khi xoay camera.
- **Doppler Level = 0** trừ game đua/máy bay.
- Tiếng cảnh báo, boss telegraph, UI: `spatialBlend = 0`.

`AudioListener` một cái, trên camera (3D) hoặc trên nhân vật (top-down 2D — camera xa nên listener trên camera làm mọi thứ nhỏ và trung tính). Hai listener → Unity cảnh báo và chỉ dùng một.

## Voice limit và priority

`Project Settings > Audio > Max Real Voices` mặc định 32 — số tiếng thực sự được trộn; `Max Virtual Voices` 512 — số tiếng được theo dõi. Vượt 32, Unity **ảo hoá** (im nhưng vẫn chạy thời gian) những tiếng có `priority` số lớn nhất và volume nghe nhỏ nhất. Không đặt priority thì tiếng bước chân của 8 enemy (mỗi tiếng 0.3 s, liên tục) nuốt mất tiếng nổ boss — bug người chơi mô tả là "đôi khi không có tiếng".

Bảng priority phía trên giải quyết. Thêm hai kiểm soát ở tầng game: `maxInstances` mỗi SFX (3 cho bước chân, 2 cho đòn) và `minInterval` 40 ms — đều là logic trong `SfxPool`, không phải của Unity.

Mobile: giảm `Max Real Voices` xuống 24 và **`DSP Buffer Size`** để `Good Latency` (512 mẫu ≈ 11 ms) — `Best Latency` (256) crackle trên Android tầm thấp khi CPU bận, `Best Performance` (1024, ~23 ms) đủ thấy trễ ở game nhịp. Android vốn có latency hệ thống 20–80 ms ngoài tầm Unity; iOS ~10 ms. Tiếng đòn đánh trên Android nên **phát ở frame va chạm**, không đợi animation event như PC.

## Pause, focus, và `timeScale`

`Time.timeScale = 0` **không dừng audio** — nhạc chạy tiếp, SFX đang phát chạy tiếp, và coroutine phát SFX theo `WaitForSeconds` thì đứng. Hai cách:
- `AudioListener.pause = true` dừng **mọi** source, kể cả tiếng UI menu pause → đặt `ignoreListenerPause = true` trên source UI.
- Snapshot `Paused` (lowpass + duck Music) nếu muốn nhạc vẫn nghe nhỏ dưới menu như [[ux-flow]] khuyên. Đây là cách phần lớn game làm.

`OnApplicationPause(true)` (điện thoại nhận cuộc gọi, ra Home) → `AudioListener.pause = true` và lưu `dspTime` để tính lại lịch nhạc khi về; nhạc `PlayScheduled` đã lên lịch trước khi pause sẽ **lệch** sau khi resume — gọi lại `StartAll()` từ đầu ô nhịp là rẻ nhất. iOS: `Mute Other Audio Sources` tắt trong Player Settings nếu muốn người chơi nghe Spotify song song (game puzzle nên tắt, game có nhạc quan trọng nên bật).

## FMOD / Wwise — khi nào đáng

Đáng khi **có sound designer riêng** làm việc toàn thời gian với audio, hoặc adaptive music nhiều hơn 2 trạng thái + layering ([[adaptive-music]] mức 3–4). Họ chỉnh ducking, RTPC, transition trong tool riêng, không đụng Unity, không đợi build. Chi phí: license (miễn phí dưới ngưỡng doanh thu, vẫn phải đăng ký), 1–2 tuần tích hợp, build size +5–10 MB, bank phải load/unload tay, và **AI agent gần như không sửa được** vì project FMOD là binary.

Team ≤ 5 người, không có sound designer chuyên trách: AudioMixer + pool + `PlayScheduled` như trên đủ đến ship. Đừng tích hợp FMOD vì "sau này cần".

## Bẫy lộ ra khi build

- `Decompress On Load` + Vorbis trên clip dài — Editor không thấy vì RAM dư, build mobile bị kill khi load scene 2. Đo bằng Memory Profiler, cột AudioClip.
- Clip có `Preload Audio Data` tắt và không ai gọi `LoadAudioData` → lần phát đầu khựng; Editor đã cache nên không thấy.
- WebGL: **không có streaming**, không có `PlayScheduled` chính xác trước khi người dùng tương tác (autoplay policy), và mọi clip nén phải giải nén trong trình duyệt. Nhạc trên WebGL = Compressed In Memory, và nút "Chạm để bắt đầu" là bắt buộc.
- Android: `AudioSource.time` không chính xác với Vorbis streaming (sai vài chục ms). Đồng bộ theo `dspTime` đã lưu, không đọc `source.time`.
- Sample rate hệ thống Android có thể là 48000 trong khi clip 44100 → Unity resample lúc chạy, tốn CPU. Đặt `Project Settings > Audio > System Sample Rate` khớp phần lớn máy đích, hoặc để 0 (theo máy) và import clip ở 48 k.

## Kiểm tra nhanh

- Profiler > Audio: `Total Audio CPU` ở cảnh đông nhất < 5% trên máy yếu nhất; `Playing Audio Sources` không vượt `Max Real Voices`.
- Memory Profiler: tổng AudioClip trong RAM < 25 MB (mobile) — clip nào > 3 MB phải là Streaming hoặc Compressed In Memory.
- Grep `PlayClipAtPoint` và `PlayOneShot` ngoài `SfxPool`: kết quả rỗng.
- Bật `Audio Profiler` chi tiết, chạy nhạc 3 phút, so `dspTime` của điểm chuyển với lý thuyết: sai số < 5 ms.
- Nhận cuộc gọi (hoặc bấm Home) giữa trận rồi quay lại: nhạc còn khớp nhịp không, SFX có "dồn" một lượt không?

Camera quyết định người chơi **thấy gì và không thấy gì** — nó là công cụ dẫn dắt của [[level-design]] và là một nửa của cảm giác tốc độ ở [[game-feel]]. Vậy mà camera thường là script `Lerp` 15 dòng viết ở tuần 1 rồi vá thêm 200 dòng trong 6 tháng: dead zone, look-ahead, giới hạn biên, rung, zoom khi boss, không xuyên tường. **Cinemachine đã giải hết các bài đó**, có Inspector cho designer chỉnh, và cái giá là học đúng 5 khái niệm: Brain, virtual camera, priority, composer, extension.

Toàn bộ node này nói về **Cinemachine 3.x** (Unity 6): namespace `Unity.Cinemachine`, component `CinemachineCamera` (bản 2.x là `CinemachineVirtualCamera`), `Position Composer` thay `Framing Transposer`, `Rotation Composer` thay `Composer`, `Deoccluder` thay `Collider`, `Orbital Follow` thay `FreeLook`. Code cho 2.x không biên dịch trên 3.x — đừng dán từ tutorial cũ.

## Tự viết hay Cinemachine

| Trường hợp | Chọn | Vì sao |
|---|---|---|
| 2D pixel-perfect, camera chỉ bám hoặc khoá phòng | **Tự viết** 30 dòng | Cần vị trí camera là bội số của 1/PPU, dễ kiểm soát hơn khi không có damping |
| 2D có dead zone, look-ahead, biên level, rung | Cinemachine | Mỗi thứ là một checkbox thay cho 40 dòng có bug |
| 3D third-person, top-down, isometric | Cinemachine | Collision avoidance và blend giữa camera là thứ tự viết tốn hàng tuần |
| Cutscene, nhiều góc máy | Cinemachine + Timeline | Không có lựa chọn khác hợp lý |
| Camera cố định hoàn toàn (puzzle một màn) | Không cần gì | Đừng thêm Brain cho một camera đứng yên |

Chi phí: Brain + 1 camera đang hoạt động khoảng 0.05–0.1ms. Camera **không hoạt động vẫn được cập nhật** theo `Standby Update` (mặc định Round Robin). Có 20 virtual camera "Always" là tự phạt mình; đặt `Never` cho camera cutscene và camera một lần.

## Cấu trúc: một Brain, nhiều virtual camera, blend bằng priority

`CinemachineBrain` nằm trên **Main Camera duy nhất** trong scene. Nó không tự quyết gì — mỗi frame nó chọn `CinemachineCamera` có **priority cao nhất** đang bật, rồi blend từ camera cũ sang camera mới theo `Default Blend` (mặc định EaseInOut 2s — quá dài cho gameplay, đặt 0.5s) hoặc bảng `Custom Blends` cho từng cặp. Mỗi trạng thái camera là một `CinemachineCamera` riêng trong scene: `CM_Follow` (10), `CM_Aim` (20 khi bật), `CM_Boss` (30), `CM_Cutscene` (100).

```csharp
using Unity.Cinemachine;
using UnityEngine;

public class CameraDirector : MonoBehaviour {
    [SerializeField] CinemachineBrain brain;
    [SerializeField] CinemachineCamera followCam, aimCam, bossCam;
    [SerializeField] CinemachineImpulseSource hitImpulse;
    [SerializeField] CinemachineImpulseListener listener;
    CinemachineCamera current;

    void Awake() {
        brain.IgnoreTimeScale = true;                 // rung/blend vẫn chạy trong hitstop timeScale = 0
        listener.Gain = A11y.ShakeScale;              // hệ số trợ năng nhân MỘT lần ở listener, không ở từng nguồn
        Switch(followCam);
    }

    public void Switch(CinemachineCamera next) {
        if (current == next) return;
        if (current != null) current.Priority = 10;   // CM3: gán int được nhờ implicit conversion sang PrioritySettings
        next.Priority = 20;
        current = next;
    }

    /// Điểm DUY NHẤT trong dự án được rung camera. force ~ 0.3 đòn nhẹ, 1.0 đòn nặng, 2.0 boss chết.
    public void Shake(float force) => hitImpulse.GenerateImpulseWithForce(force);

    public void Zoom(float fov, float seconds) => StartCoroutine(LerpFov(fov, seconds));

    System.Collections.IEnumerator LerpFov(float target, float seconds) {
        float start = current.Lens.FieldOfView, t = 0f;
        while (t < seconds) {
            t += Time.unscaledDeltaTime;
            current.Lens.FieldOfView = Mathf.Lerp(start, target, t / seconds);
            yield return null;
        }
    }
}
```

Với 4–5 trạng thái, đổi priority từ code là đủ. Trên 8 trạng thái theo vùng level, dùng **trigger volume** bật/tắt camera con, hoặc `CinemachineStateDrivenCamera` nếu trạng thái đã có trong Animator. Đừng viết switch-case 15 nhánh.

## 2D: Position Composer, dead zone, look-ahead, Confiner

`CinemachineCamera` với **Position Composer** là camera 2D chuẩn. Bốn tham số quyết định cảm giác:

- **Dead Zone** 0.1–0.2 (tỉ lệ màn hình) — nhân vật di chuyển trong vùng này camera không nhúc nhích. Không có dead zone, mọi bước nhỏ đều kéo camera, người chơi say. Dead zone rộng quá thì cảm giác camera "lười".
- **Damping** 0.3–0.6 cho x, 0.8–1.2 cho y trong platformer — y chậm hơn để nhảy không kéo camera nảy theo. Damping trên 1s là nhân vật dash lọt khỏi khung.
- **Look-ahead** `Time` 0.3–0.5s, `Smoothing` 10, bật `IgnoreY` — camera nhìn trước theo hướng chạy, cho người chơi thấy kẻ địch trước khi lao vào. Bẫy: look-ahead tính từ **vận tốc target**, nên quay đầu liên tục là camera lắc qua lại; smoothing cao chữa được nhưng trễ thêm.
- **Hard Limits** — hộp mà nhân vật không bao giờ ra khỏi, dù damping chưa đuổi kịp. Đây là chốt an toàn cho dash.

**`CinemachineConfiner2D`** (extension) giữ khung camera trong một `PolygonCollider2D` bao level. Nó tự tính vùng hợp lệ cho orthographic size hiện tại; đổi zoom phải gọi `InvalidateBoundingShapeCache()`. Collider biên đặt trên layer riêng **không va chạm với gì** (xem collision matrix ở [[unity-physics]]) — không thì đạn nổ vào biên camera.

## 3D third-person: Orbital Follow + Rotation Composer + Deoccluder

Bộ chuẩn: **Orbital Follow** (kiểu `ThreeRing`: Top/Center/Bottom, mỗi vòng bán kính và độ cao riêng — cho phép camera gần khi nhìn từ trên, xa khi ngang) + **Rotation Composer** nhìn vào một `Tracking Target` là điểm ở **ngang vai**, không phải chân nhân vật + `CinemachineInputAxisController` đọc action Look từ Input System, không đọc `Mouse.delta` tay.

**Deoccluder** là extension chống camera xuyên tường: `Collide Against` = layer tường (không gồm Player, không gồm trigger), `Minimum Distance From Target` 0.3, strategy `Pull Camera Forward` cho hành động nhanh, `Preserve Camera Height` cho khám phá. Bẫy kinh điển: mọi thứ ở layer Default → Deoccluder né cả cây cỏ, cột nhỏ, và chính nhân vật; camera nhảy phựt liên tục. Tạo layer `CameraBlock` chỉ cho tường và địa hình, gán tag `IgnoreTag` cho nhân vật. `Damping When Occluded` 0 (né ngay), `Damping` 0.5 (trở về từ tốn).

## Bám Rigidbody: Update Method và interpolation

Camera bám vật thể chạy bằng physics là nơi rung xuất hiện nhiều nhất, và người ta đi chỉnh damping thay vì chỉnh đúng chỗ. Hai điều kiện phải cùng có:

1. **Rigidbody bật Interpolate** — không thì vị trí chỉ đổi 50 lần/giây, camera 144Hz thấy nó nhảy bậc. Đây là việc của [[unity-physics]].
2. **Brain `Update Method` = Smart Update** (mặc định) hoặc `Late Update`. Smart Update tự phát hiện target đổi trong FixedUpdate và theo nhịp đó. Nếu vẫn rung sau khi bật interpolation: đặt hẳn `Late Update` và `Blend Update Method` = `Late Update`. Chỉ dùng `Fixed Update` khi *mọi thứ* camera nhìn đều là physics và không interpolate — hiếm.

Kiểm tra ở màn hình **144Hz**, không phải 60 — lệch 50/60 khó thấy, lệch 50/144 rõ như ban ngày.

## Impulse: rung có ngân sách

`CinemachineImpulseSource` (trên nguồn rung: nhân vật, vũ khí, boss) phát tín hiệu; `CinemachineImpulseListener` (extension trên camera) nhận và rung. Ưu điểm so với tự viết: rung theo **khoảng cách** (nổ xa rung nhẹ), nhiều nguồn cộng dồn đúng, và `Gain` trên listener là **một nút vặn duy nhất** cho trợ năng — điều [[accessibility]] yêu cầu.

Ngân sách rung: Impulse Shape `Bump` 0.15–0.2s cho đòn thường, `Explosion` 0.3–0.4s cho nổ, `Rumble` chỉ cho môi trường (động đất). Force 0.3 / 1.0 / 2.0 cho nhẹ / nặng / kết liễu — tỉ lệ 1:3:6, để đòn thường không lẫn với đòn lớn. Rung liên tục quá 0.5s là say. Đặt `Channel` riêng cho rung UI (trúng đòn hiện màu đỏ) và rung gameplay để tắt riêng.

Hitstop `timeScale = 0` làm Impulse đứng hình giữa chừng nếu Brain không `IgnoreTimeScale` — rung, hitstop và flash phải cùng chạy trên đồng hồ thực; phối hợp ba thứ này ở [[unity-vfx]].

## Target Group cho co-op và boss

`CinemachineTargetGroup` với 2–4 target (mỗi target có `Weight` và `Radius`) làm một `Tracking Target` — camera tự đặt ở tâm và **Group Framing** trên Position Composer tự zoom để bao hết. Boss fight: nhân vật weight 1, boss weight 0.6, để camera nghiêng về người chơi. Bẫy co-op: hai người chạy hai hướng, camera zoom ra tới `Maximum Ortho Size` rồi vẫn không đủ — cần luật gameplay (kéo người tụt lại, hoặc chặn ở mép) chứ không phải camera.

## Pixel perfect: PPU, orthographic size, và jitter

Game pixel art có ba con số phải khớp: **PPU** của sprite (16 hoặc 32), **độ phân giải tham chiếu** (320×180 hoặc 640×360), và **orthographic size** = `refResY / (2 × PPU)` — 180 / (2×16) = 5.625. Lệch một trong ba là pixel không đều: một hàng pixel dày, hàng kế mỏng.

Component **Pixel Perfect Camera** (URP có sẵn, `UnityEngine.Rendering.Universal`) ép orthographic size và làm tròn vị trí camera về lưới pixel. Với Cinemachine, thêm extension `CinemachinePixelPerfect` lên virtual camera — không thì damping của Composer cho vị trí lẻ pixel và sprite **nhấp nháy** khi camera chạy, rõ nhất ở đường viền 1px. Tuỳ chọn `Upscale Render Texture` render ở 320×180 rồi phóng — rẻ hơn nhiều trên mobile và pixel luôn đều, đổi lại xoay sprite bị răng cưa (thường là điều pixel art muốn).

## Camera stacking trong URP

Camera Main là `Base`; thêm camera `Overlay` cho UI world-space không bị post-processing, hoặc cho vũ khí FPS không xuyên tường (FOV riêng). Mỗi camera thêm tốn một lượt culling + setup, ~0.3–0.8ms trên mobile — 2 camera là bình thường, 4 là phải có lý do. Minimap không nên là camera thứ ba render mỗi frame: render vào `RenderTexture` **10 lần/giây** bằng `camera.Render()` thủ công với `enabled = false`, hoặc tốt hơn là vẽ minimap bằng UI từ dữ liệu vị trí — không cần camera.

Overlay camera **không** nhận post-processing riêng và không clear background — đúng ý cho UI, nhưng nếu muốn vũ khí FPS có bloom thì phải bật trên Base.

## Những thứ nhỏ

- `Camera.main` được cache nội bộ từ Unity 2020.2, nhưng vẫn trả về **null** khi camera có tag MainCamera bị tắt hoặc chưa có. Cache vào field ở `Awake`, và hỏi `CinemachineBrain.OutputCamera` nếu đang dùng Cinemachine.
- **FOV và tốc độ:** Unity dùng FOV dọc. 60° mặc định, third-person 50–65, racing 75–90. Tăng 8–12° trong 0.15–0.2s khi sprint/dash rồi trả về — cảm giác nhanh hơn thật mà không đổi tốc độ. Ultrawide: chuyển sang FOV ngang cố định bằng `Camera.HorizontalToVerticalFieldOfView(hFov, aspect)`, không thì người chơi 21:9 thấy ít hơn 16:9.
- **Cutscene:** Timeline có `Cinemachine Track`; mỗi clip là một `Cinemachine Shot` trỏ vào virtual camera, chồng hai clip là blend. Cùng Brain, nên kết thúc cutscene tự blend về camera gameplay — không cần code.

## Bẫy lộ ra khi build

- Test trên màn hình 60Hz trong Editor, ship cho người chơi 144Hz — rung do thiếu interpolation chỉ họ thấy.
- Composer dùng `Screen` ratio — UI safe area trên điện thoại tai thỏ che mất phần dead zone bên trái; kiểm với tỉ lệ 20:9.
- Confiner2D cache theo orthographic size; đổi độ phân giải lúc chạy (đổi cửa sổ) mà không invalidate là camera thoát khỏi biên.
- Deoccluder raycast mỗi frame vào layer `Collide Against` — layer chứa 5000 mesh collider địa hình chi tiết là 0.5ms chỉ để né. Gộp địa hình vào collider đơn giản hơn trên layer `CameraBlock`.
- Quên `Standby Update = Never` cho 30 camera cutscene → 30 camera tính toán mỗi frame ở màn không có cutscene.

## Kiểm tra nhanh
- Màn 144Hz, nhân vật Rigidbody chạy thẳng 5 giây: nền có rung bậc không? Không là interpolation + Update Method đúng.
- Dash tốc độ tối đa liên tiếp 3 lần: nhân vật có chạm Hard Limits không? Chạm là damping quá cao.
- `A11y.ShakeScale = 0`: chơi hết một trận boss, không còn rung nào (chỉ có một `Listener.Gain` để tắt).
- Profiler `CinemachineBrain.LateUpdate` với 5 virtual camera bật < 0.3ms.
- Pixel art: quay video 60fps lúc camera chạy, dừng frame, zoom 400%: viền sprite có hàng pixel dày mỏng không đều không?

[[architecture-patterns]] đã nói vì sao composition, event bus có chừng mực, và pool. Node này chỉ nói **pattern đó biến thành gì khi chạm MonoBehaviour**: cái gì Unity serialize được, cái gì sống qua scene, cái gì dính vào asset trong Editor mà không dính trên build.

Quyết định quan trọng nhất: **dữ liệu và kênh giao tiếp nằm trong ScriptableObject; logic nằm trong class C# thường; MonoBehaviour chỉ là chỗ móc vào vòng đời**. Ba lớp này càng rõ thì project càng ít singleton.

## ScriptableObject: ba vai, một bẫy

**Vai 1 — config bất biến.** `WeaponData`, `EnemyData`: chỉ đọc lúc chạy. [[data-driven-design]] đã nói kỹ, kể cả bẫy `data.damage += 5` ghi thẳng vào asset.

**Vai 2 — event channel.** Một asset `OnPlayerDied` mà UI, audio, quest cùng tham chiếu qua Inspector. Hai scene additive không tham chiếu được nhau qua Inspector, nhưng cùng tham chiếu một SO thì được:

```csharp
using System; using UnityEngine;

[CreateAssetMenu(menuName = "Events/Int Channel")]
public sealed class IntEventChannel : ScriptableObject {
    [NonSerialized] Action<int> listeners;             // KHÔNG serialize — không được ghi vào asset
    public void Raise(int v) => listeners?.Invoke(v);
    public void Subscribe(Action<int> a)   => listeners += a;
    public void Unsubscribe(Action<int> a) => listeners -= a;
}

// Người nghe: luôn cặp OnEnable/OnDisable
public sealed class GoldLabel : MonoBehaviour {
    [SerializeField] IntEventChannel goldChanged;
    void OnEnable()  => goldChanged.Subscribe(Refresh);
    void OnDisable() => goldChanged.Unsubscribe(Refresh);
    void Refresh(int gold) { /* … */ }
}
```

**Vai 3 — runtime set.** `EnemyRuntimeSet` chứa `List<Enemy>` đang sống; enemy tự `Add` trong `OnEnable`, `Remove` trong `OnDisable`. Spawner, UI đếm quái, AI director cùng đọc một danh sách mà không ai `FindObjectsByType`.

**Bẫy chung cho vai 2 và 3:** trong Editor, SO **sống xuyên các lần Play**. Field runtime không có `[NonSerialized]` sẽ được ghi vào asset khi bạn Save Project — lần Play sau `currentHp` bắt đầu từ 37, và danh sách enemy chứa tham chiếu tới object đã destroy. Trên build asset chỉ đọc nên mọi thứ reset mỗi lần mở game. Hai hành vi khác nhau nghĩa là bug chỉ xuất hiện ở một trong hai nơi. Luật: mọi field thay đổi lúc chạy trong SO mang `[NonSerialized]`, và mọi subscriber gỡ trong `OnDisable` để khi thoát Play danh sách tự rỗng. Nếu tắt Domain Reload, thêm reset qua `[RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.SubsystemRegistration)]` cho static.

## Singleton: hai cái, viết đúng

Chấp nhận singleton cho **1–2 thứ thật sự chỉ có một và không giữ trạng thái game**: `GameFlow` (xem [[unity-game-loop]]) và có thể `AudioService`. `GameManager` phình vì nó là chỗ **dễ với tới nhất** từ mọi nơi; mỗi lần ai đó lười truyền tham chiếu, một field mới mọc ở đó.

```csharp
public abstract class PersistentSingleton<T> : MonoBehaviour where T : PersistentSingleton<T> {
    public static T I { get; private set; }
    protected virtual void Awake() {
        if (I != null && I != this) { Destroy(gameObject); return; }   // huỷ bản MỚI
        I = (T)this;
    }
    protected virtual void OnDestroy() { if (I == this) I = null; }     // cần khi tắt Domain Reload
}
```

Không tạo lazy trong getter (`new GameObject` khi `I == null`): nó che thứ tự khởi tạo, và khi được gọi trong `OnDestroy` lúc thoát Play, nó sinh object ma với cảnh báo "Some objects were not cleaned up".

## Service Locator có kỷ luật vs DI framework

```csharp
public static class Services {
    static readonly Dictionary<Type, object> map = new();
    public static void Register<T>(T s) where T : class => map[typeof(T)] = s;
    public static T Get<T>() where T : class =>
        map.TryGetValue(typeof(T), out var s) ? (T)s
        : throw new InvalidOperationException($"{typeof(T).Name} chưa đăng ký — gọi trong Awake?");
    [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.SubsystemRegistration)]
    static void Reset() => map.Clear();
}
```

Kỷ luật là bốn luật, không có luật nào là code: đăng ký **chỉ trong Bootstrapper**; đăng ký **interface** (`IAudioService`), không đăng ký class; `Get` **trong `Start`**, không trong `Awake`; `Get` ném lỗi, **không trả null**. Thiếu một luật, Service Locator thành singleton có thêm một bước.

| Quy mô | Dùng gì |
|---|---|
| 1 người, dưới 15 hệ thống | 1–2 singleton + SO event channel. Xong. |
| 2–5 người, 6–12 tháng | Service Locator theo bốn luật trên. Thêm interface để test được. |
| 5+ người, cần scope (per-match, per-scene), test nhiều | **VContainer**: nhanh, ít reflection, có source generator cho IL2CPP. Zenject/Extenject nặng hơn, resolve chậm hơn, ít được bảo trì. |

DI framework trả giá bằng thời gian khởi động và một tầng trừu tượng người mới phải học. Nó đáng khi bạn có nhiều scope sống độc lập; không đáng để "cho sạch".

## State machine bằng class thường

```csharp
public interface IState { void Enter(); void Tick(float dt); void Exit(); }

public sealed class StateMachine {
    public IState Current { get; private set; }
    public void Set(IState next) {
        if (ReferenceEquals(next, Current)) return;
        Current?.Exit();
        Current = next;
        Current?.Enter();
    }
    public void Tick(float dt) => Current?.Tick(dt);
}
```

Mỗi state là một class nhận tham chiếu tới context (`EnemyContext` chứa transform, data, animator). MonoBehaviour chỉ gọi `fsm.Tick(Time.deltaTime)` trong `Update`. **Không dùng Animator làm FSM logic**: transition của nó được đánh giá ở bước animator (trễ một frame), `Has Exit Time` chen vào, tham số là string, và không unit test được. Logic FSM **điều khiển** Animator (`SetBool("Attacking")`), không phải ngược lại. Lý thuyết ở [[fsm]], phần animation ở [[unity-animation]]. Quá 8 state với transition chéo thì sang [[behavior-tree]].

## Command cho undo và replay

```csharp
public interface ICommand { void Execute(); void Undo(); }

public sealed class MoveUnitCommand : ICommand {
    readonly Unit unit; readonly Vector2Int from, to;
    public MoveUnitCommand(Unit u, Vector2Int target) { unit = u; from = u.Cell; to = target; }
    public void Execute() => unit.SetCell(to);
    public void Undo()    => unit.SetCell(from);
}
```

Đáng dùng ở game theo lượt, level editor, và replay (ghi command + số tick, phát lại với cùng seed). **Không đáng** cho input hành động thời gian thực: không có nghĩa "undo một cú nhảy", và input buffer 5 dòng trong hệ input làm việc đó tốt hơn.

## Object pool: dùng cái có sẵn, reset cho đủ

`UnityEngine.Pool.ObjectPool<T>` có từ 2021 (code mẫu ở [[architecture-patterns]]). Đừng tự viết. Việc của bạn là **reset**, và đây là chỗ 90% bug pool nằm:

```csharp
public interface IPoolable { void OnGet(); void OnRelease(); }

public sealed class Bullet : MonoBehaviour, IPoolable {
    Rigidbody2D rb; TrailRenderer trail;
    void Awake() { rb = GetComponent<Rigidbody2D>(); trail = GetComponent<TrailRenderer>(); }
    public void OnGet()     { trail.Clear(); rb.linearVelocity = Vector2.zero; rb.simulated = true; }
    public void OnRelease() { rb.simulated = false; StopAllCoroutines(); }
}
```

Danh sách những gì **không tự reset** khi SetActive: vận tốc rigidbody, trail renderer (vẽ một vệt từ vị trí cũ sang vị trí mới), particle đang phát, coroutine đang chạy, animator state, `transform.localScale` nếu từng bị parent vào object có scale khác, và mọi field bool `isDead`. Pool sống ở Boot mà object trong pool thuộc scene Level → unload scene, stack chứa null. Pool theo scene hoặc `Clear()` khi `sceneUnloaded`.

Cho mảng tạm: `ListPool<T>.Get()` / `Release` và `CollectionPool` — hết `new List<>()` trong hàm nóng.

## Observer: C# event vs UnityEvent

| | `event Action<T>` | `UnityEvent<T>` |
|---|---|---|
| Nối trong Inspector | Không | Có — designer nối được |
| Hiệu năng | Gọi trực tiếp | Persistent listener qua reflection, chậm hơn nhiều lần, có thể cấp phát khi Invoke |
| Đổi tên hàm | Lỗi biên dịch (tốt) | Kết nối **mất âm thầm**, Inspector hiện "Missing" |
| Gỡ đăng ký | Code phải tự gỡ | Persistent listener theo object; `AddListener` lúc chạy vẫn phải gỡ |

Luật: `UnityEvent` cho **hook của designer trên prefab** (nút, trigger vùng, cutscene); C# event **giữa các hệ thống**. Luôn khai `event`, không khai `public Action<T>` trần — ai cũng có thể `=` ghi đè cả danh sách.

## Một `Update()` thay cho 500

Mỗi `Update()` là một lần vượt ranh giới native → managed. Unity đo 10.000 `Update()` rỗng tốn khoảng 1ms trên PC trước khi làm bất cứ việc gì; một manager gọi 10.000 hàm C# tốn khoảng một phần mười. Trên điện thoại nhân 3–5.

```csharp
public interface ITickable { void Tick(float dt); }

public sealed class TickManager : MonoBehaviour {
    readonly List<ITickable> items = new(512), toAdd = new(), toRemove = new();
    public void Add(ITickable t)    => toAdd.Add(t);
    public void Remove(ITickable t) => toRemove.Add(t);

    void Update() {
        foreach (var t in toAdd)    items.Add(t);       // sửa danh sách NGOÀI vòng lặp
        foreach (var t in toRemove) items.Remove(t);
        toAdd.Clear(); toRemove.Clear();
        float dt = Time.deltaTime;
        for (int i = 0; i < items.Count; i++) items[i].Tick(dt);
    }
}
```

Lợi thứ hai lớn hơn lợi thứ nhất: bạn có **một chỗ** để chạy AI ở 10Hz thay vì 60Hz, tick theo khoảng cách tới camera, hay tạm dừng cả nhóm. Xem [[unity-optimization]]. Object quên `Remove` trước khi destroy → `MissingReferenceException` ở frame kế; lại là cặp `OnEnable`/`OnDisable`.

## Strategy qua ScriptableObject

```csharp
public abstract class BulletBehaviour : ScriptableObject {
    public abstract void Tick(Bullet b, float dt);     // KHÔNG giữ trạng thái — trạng thái ở Bullet
}

[CreateAssetMenu(menuName = "Bullets/Homing")]
public sealed class HomingBehaviour : BulletBehaviour {
    [SerializeField] float turnDegPerSec = 240f;
    public override void Tick(Bullet b, float dt) { /* xoay b.Direction về b.Target */ }
}
```

`WeaponData` giữ một `BulletBehaviour`; designer kéo `Homing`, `Bounce`, `Pierce` vào mà không cần dev. Một asset dùng cho 500 viên đạn nên **không được có field runtime** — mọi trạng thái nằm trên `Bullet`.

## MVP cho UI

Model là dữ liệu thuần, View là MonoBehaviour chỉ hiện, Presenter nối hai bên qua event. UI không đọc `PlayerStats` trực tiếp. Chi tiết và code ở [[unity-ui]].

## Interface vs abstract MonoBehaviour

`[SerializeField] IDamageable target;` hiện **trống** trong Inspector: Unity không serialize interface. Bốn lối ra:
- Serialize `Component`, `TryGetComponent<IDamageable>` trong `Awake`, kiểm tra trong `OnValidate`.
- `[SerializeReference]` cho class thường đa hình (không phải `UnityEngine.Object`); cần drawer chọn kiểu.
- Strategy qua SO như trên — đa hình có Inspector, không cần drawer.
- Abstract MonoBehaviour: kéo thả được, đa hình được, nhưng ăn slot kế thừa duy nhất.

Luật: interface cho **hợp đồng logic** (test giả lập được); abstract MonoBehaviour hoặc SO khi cần **tham chiếu trong Inspector**. Generic MonoBehaviour (`Pool<T> : MonoBehaviour`) không gắn được vào GameObject; phải có lớp con cụ thể.

## Bẫy hay gặp

- `target?.Invoke()` với `target` là `UnityEngine.Object` đã destroy: `?.` không dùng toán tử `==` mà Unity nạp chồng, object "giả null" lọt qua rồi ném `MissingReferenceException`. Dùng `if (target != null)`.
- `e += () => Foo();` rồi `e -= () => Foo();` không gỡ gì — lambda mới. Giữ delegate trong field hoặc dùng method group.
- SO event channel không được scene/prefab nào trong build tham chiếu → **không có trong build**; `Resources.Load` nó trả null. Mọi channel nằm trong một `ChannelRegistry` SO mà Boot tham chiếu.
- Tắt Domain Reload để Play nhanh hơn rồi mọi static và SO runtime dính từ lần trước; bật lại khi debug hành vi lạ trước khi nghi code.

## Kiểm tra nhanh
- Play → Stop → Play với Domain Reload tắt: log giống hệt lần đầu? Event nào bắn hai lần?
- Grep `.I.` và `.Instance`: chỉ ≤ 2 kiểu xuất hiện?
- Grep `void Update()` rồi đếm cái chỉ có `if (…) return;`: chuyển sang event hoặc TickManager.
- Profiler `BehaviourUpdate` với 500 enemy active: dưới 0.5ms trên máy mục tiêu?
- Grep `+= () =>` và `+= delegate`: mỗi cái có gỡ được không?

Luận điểm: **mỗi lần designer phải hỏi lập trình viên "số này ở đâu" hay "làm sao thử cái này" là một lỗi tooling.** Team 3 người mất 20 phút mỗi ngày cho những câu như vậy là 100 giờ một năm — đủ để viết mọi tool trong node này ba lần. Và đây là loại code AI agent viết tốt nhất: phạm vi hẹp, không cần cảm nhận gameplay, kiểm chứng ngay trong Editor. Dữ liệu tách khỏi code ([[data-driven-design]]) chỉ có ích khi có tool để nhìn, sửa và kiểm tra dữ liệu đó.

Quyết định quan trọng nhất: **viết tool ở tuần 2, không phải tuần 20.** Tool viết muộn phải tương thích với 200 asset đã lệch chuẩn; tool viết sớm ép chuẩn từ asset đầu.

## Tầng 0: attribute — miễn phí, làm ngay

Trước khi viết một dòng editor code, Inspector mặc định đã đi được 60% đường:

```csharp
[CreateAssetMenu(menuName = "Game/Enemy")]
public class EnemyData : ScriptableObject {
    [Header("Chiến đấu")]
    [Min(1)] public int hp = 30;
    [Range(0f, 20f), Tooltip("Đơn vị/giây. Player là 8.")] public float speed = 4f;
    [Min(0.05f)] public float attackCooldown = 0.8f;

    [Header("Hành vi")]
    [SerializeReference] public IEnemyBrain brain;      // đa hình trong Inspector — cần drawer hoặc Odin để chọn type

    [TextArea(2, 5)] public string designNote;

    [ContextMenu("Copy từ Player làm mốc")]              // chuột phải vào header component
    void CopyPlayerBaseline() { speed = 8f; hp = 100; }

    void OnValidate() {                                  // chạy mỗi lần chỉnh trong Inspector và khi load
        if (attackCooldown * speed > 20f)
            Debug.LogWarning($"{name}: nhanh và đánh liên tục — kiểm tra lại", this);
    }
}
```

`[Min]`, `[Range]` chặn giá trị vô lý trước khi vào game; `[Tooltip]` là tài liệu duy nhất designer đọc; `OnValidate` là validator rẻ nhất — truyền `this` vào `Debug.LogWarning` để bấm log là nhảy tới asset. `OnValidate` không được gọi `AssetDatabase` hay sửa asset khác — nó chạy cả lúc load domain, làm việc nặng ở đó là Editor treo khi mở project.

## Tầng 1: Odin, NaughtyAttributes, hay tự viết

| | NaughtyAttributes (MIT) | Odin Inspector (~$55/seat) | Tự viết PropertyDrawer |
|---|---|---|---|
| `[Button]`, `[ShowIf]`, `[ReorderableList]`, `[Expandable]` | Có | Có, nhiều hơn | Tự viết từng cái |
| Serialize Dictionary, đa hình, nested SO inline | Không | **Có** (Odin Serializer) | Không thực tế |
| Ảnh hưởng build | Không | Không nếu chỉ dùng attribute; Odin Serializer thì có | Không |
| Khi team lớn / nhiều SO phức tạp | Đủ đến ~50 loại SO | Đáng tiền từ ngày 1 | — |
| AI agent sinh code | Rất tốt, API nhỏ | Tốt, API rộng dễ dùng sai version | Tốt cho drawer ≤ 50 dòng |

Khuyến nghị: **NaughtyAttributes cho dự án indie**, Odin khi có ≥ 2 designer làm dữ liệu cả ngày. PropertyDrawer tự viết chỉ cho thứ hai package không có (chọn id từ bảng, preview curve theo level).

## Tầng 2: custom Editor bằng UI Toolkit

Unity 6 khuyến nghị UI Toolkit cho Editor; IMGUI vẫn chạy và đôi khi ngắn hơn cho một nút. Mẫu chuẩn — Inspector mặc định + một nút:

```csharp
#if UNITY_EDITOR
using UnityEditor;
using UnityEditor.UIElements;
using UnityEngine.UIElements;

[CustomEditor(typeof(EnemyData))]
public class EnemyDataEditor : Editor {
    public override VisualElement CreateInspectorGUI() {
        var root = new VisualElement();
        InspectorElement.FillDefaultInspector(root, serializedObject, this);   // giữ mọi field mặc định

        var status = new HelpBox("", HelpBoxMessageType.None);
        var validate = new Button(() => {
            var data = (EnemyData)target;
            if (data.Validate(out var errors)) { status.text = "OK"; status.messageType = HelpBoxMessageType.Info; }
            else { status.text = string.Join("\n", errors); status.messageType = HelpBoxMessageType.Error; }
        }) { text = "Validate" };

        root.Add(validate);
        root.Add(status);
        return root;
    }
}
#endif
```

Editor script đặt trong thư mục `Editor/` hoặc asmdef `Editor-only` ([[unity-project-structure]]) — không thì build lỗi vì `UnityEditor` không tồn tại trong player. `#if UNITY_EDITOR` là lưới an toàn thứ hai, không thay được thư mục.

`Validate(out List<string>)` nằm trên data class, không trong Editor — cùng hàm đó chạy ở build step và ở test.

## Gizmo và Handles: nhìn thấy dữ liệu

Tầm đánh, bán kính nhận biết, đường tuần tra, spawn point — designer chỉnh số mà không thấy hình là chỉnh mù:

```csharp
public class EnemySpawner : MonoBehaviour {
    [SerializeField] EnemyData data;
    [SerializeField] Transform[] patrolPoints;

    void OnDrawGizmosSelected() {                        // CHỈ khi chọn — không phải OnDrawGizmos
        if (data == null) return;
        Gizmos.color = new Color(1f, 0.3f, 0.3f, 0.6f);
        Gizmos.DrawWireSphere(transform.position, data.attackRange);
        Gizmos.color = Color.yellow;
        for (int i = 0; i < patrolPoints.Length; i++) {
            if (!patrolPoints[i]) continue;
            var next = patrolPoints[(i + 1) % patrolPoints.Length];
            if (next) Gizmos.DrawLine(patrolPoints[i].position, next.position);
#if UNITY_EDITOR
            UnityEditor.Handles.Label(patrolPoints[i].position + Vector3.up * 0.5f, $"P{i}");
#endif
        }
    }
}
```

`OnDrawGizmos` (không `Selected`) chạy cho **mọi** instance mỗi lần Scene view vẽ lại — 3000 object có gizmo là Scene view 8 FPS và người ta tưởng máy chậm. Dùng `OnDrawGizmosSelected`, hoặc `[DrawGizmo(GizmoType.NonSelected)]` static trong Editor script với cờ bật/tắt trong `EditorPrefs`. `Handles` (thuộc `UnityEditor`) cho label, disc, và **handle kéo được** (`Handles.PositionHandle`) — designer kéo điểm tuần tra trực tiếp trong Scene thay vì gõ toạ độ.

## EditorWindow cho công cụ level

Paint prefab, snap grid, đặt hàng loạt: `EditorWindow` + `SceneView.duringSceneGui`. Khung tối thiểu:

```csharp
#if UNITY_EDITOR
using UnityEditor;
using UnityEngine;

public class PrefabPainter : EditorWindow {
    GameObject prefab; float grid = 1f; bool painting;

    [MenuItem("Tools/Level/Prefab Painter")]
    static void Open() => GetWindow<PrefabPainter>("Painter");

    void OnEnable()  => SceneView.duringSceneGui += OnScene;
    void OnDisable() => SceneView.duringSceneGui -= OnScene;

    void OnGUI() {
        prefab = (GameObject)EditorGUILayout.ObjectField("Prefab", prefab, typeof(GameObject), false);
        grid = EditorGUILayout.FloatField("Grid", grid);
        painting = GUILayout.Toggle(painting, painting ? "Đang paint (Esc để dừng)" : "Bắt đầu paint", "Button");
    }

    void OnScene(SceneView sv) {
        if (!painting || prefab == null) return;
        var e = Event.current;
        HandleUtility.AddDefaultControl(GUIUtility.GetControlID(FocusType.Passive)); // chặn chọn object khi click
        if (e.type == EventType.KeyDown && e.keyCode == KeyCode.Escape) { painting = false; Repaint(); return; }
        if (e.type != EventType.MouseDown || e.button != 0) return;

        var ray = HandleUtility.GUIPointToWorldRay(e.mousePosition);
        if (!Physics.Raycast(ray, out var hit, 500f)) return;
        var p = hit.point;
        p.x = Mathf.Round(p.x / grid) * grid; p.z = Mathf.Round(p.z / grid) * grid;

        var go = (GameObject)PrefabUtility.InstantiatePrefab(prefab);       // giữ liên kết prefab, không Instantiate
        go.transform.position = p;
        Undo.RegisterCreatedObjectUndo(go, "Paint prefab");                 // Ctrl+Z hoạt động — bắt buộc
        e.Use();
    }
}
#endif
```

Hai thứ mọi tool Scene phải có: **`Undo`** (tool không undo được là tool designer sợ dùng) và **`PrefabUtility.InstantiatePrefab`** thay `Instantiate` để object trong scene vẫn là prefab instance. Trạng thái tool (prefab đang chọn, grid) lưu vào `EditorPrefs` (qua các phiên) hoặc `SessionState` (chỉ trong phiên Editor, mất khi tắt) — field của EditorWindow reset khi domain reload.

## Sinh asset hàng loạt

Menu item + `AssetDatabase`, và **luôn** bọc trong `StartAssetEditing`:

```csharp
[MenuItem("Tools/Data/Sinh 20 biến thể Enemy")]
static void GenerateVariants() {
    var basePath = "Assets/Data/Enemies";
    AssetDatabase.StartAssetEditing();                   // gom import — không có là 20 lần refresh, 20 lần chậm
    try {
        for (int i = 1; i <= 20; i++) {
            var so = ScriptableObject.CreateInstance<EnemyData>();
            so.hp = 30 + i * 5; so.speed = 4f + i * 0.1f;
            AssetDatabase.CreateAsset(so, $"{basePath}/Enemy_T{i:00}.asset");
        }
    } finally {
        AssetDatabase.StopAssetEditing();                // finally: exception giữa chừng mà không Stop là Editor kẹt
    }
    AssetDatabase.SaveAssets();
}
```

Import CSV → ScriptableObject ở [[data-driven-design]] dùng đúng khung này. `ScriptableWizard` là lựa chọn cũ có sẵn form nhập; EditorWindow linh hoạt hơn và cùng công.

## AssetPostprocessor: import settings là code

Texture 2048 chưa nén, audio `Decompress On Load` 3 phút — mỗi cái tốn hơn mọi tối ưu thuật toán. Ép theo thư mục, tự động, không cần ai nhớ:

```csharp
#if UNITY_EDITOR
using UnityEditor;

class ImportRules : AssetPostprocessor {
    void OnPreprocessTexture() {
        var imp = (TextureImporter)assetImporter;
        if (assetPath.StartsWith("Assets/Art/UI/")) {
            imp.textureType = TextureImporterType.Sprite;
            imp.mipmapEnabled = false;                    // UI không cần mip
            imp.maxTextureSize = 1024;
        }
        var android = imp.GetPlatformTextureSettings("Android");
        android.overridden = true;
        android.format = TextureImporterFormat.ASTC_6x6; // không để mặc định RGBA32 lọt vào build
        imp.SetPlatformTextureSettings(android);
    }

    void OnPreprocessAudio() {
        var imp = (AudioImporter)assetImporter;
        var s = imp.defaultSampleSettings;
        if (assetPath.StartsWith("Assets/Audio/Music/")) {
            s.loadType = AudioClipLoadType.Streaming;
            s.compressionFormat = AudioCompressionFormat.Vorbis; s.quality = 0.7f;
        } else if (assetPath.StartsWith("Assets/Audio/SFX/")) {
            s.loadType = AudioClipLoadType.DecompressOnLoad;
            s.compressionFormat = AudioCompressionFormat.ADPCM;
            imp.forceToMono = true;
        }
        imp.defaultSampleSettings = s;
    }
}
#endif
```

Postprocessor chỉ chạy **khi import** — asset đã có phải `Reimport` (chuột phải thư mục) một lần sau khi thêm rule. Cách không cần code: **Preset** + `Preset Manager` với filter theo đường dẫn (`glob:"Assets/Art/UI/**"`) — designer tự sửa được, nhưng không có logic điều kiện. Thêm một menu item `Tools/Validate/Import Settings` duyệt mọi asset và log cái lệch chuẩn, chạy trong CI trước build ([[unity-build-platform]]).

## Cheat console và debug overlay trong build

QA và designer cần god mode, spawn enemy, nhảy level, đổi tốc độ — **trong build trên máy thật**, không chỉ Editor. Bọc bằng `#if DEVELOPMENT_BUILD || UNITY_EDITOR` để bản release không có:

```csharp
#if DEVELOPMENT_BUILD || UNITY_EDITOR
public class CheatConsole : MonoBehaviour {
    readonly Dictionary<string, Action<string[]>> cmds = new();
    string input = ""; bool open;
    [SerializeField] EnemySpawner spawner; [SerializeField] PlayerHealth player;

    void Awake() {
        cmds["god"]   = _ => player.Invulnerable = !player.Invulnerable;
        cmds["spawn"] = a => spawner.SpawnById(a[0], int.Parse(a.Length > 1 ? a[1] : "1"));
        cmds["level"] = a => GameFlow.I.LoadLevel(int.Parse(a[0]));
        cmds["speed"] = a => Time.timeScale = float.Parse(a[0]);   // chỉ chỗ này được đụng timeScale ngoài TimeManager
    }

    void Update() {
        if (Keyboard.current.backquoteKey.wasPressedThisFrame) open = !open;      // Input System
        if (Touchscreen.current != null && Touchscreen.current.touches.Count(t => t.isInProgress) >= 3) open = true;
    }

    void OnGUI() {                                          // IMGUI đủ cho tool debug, không cần Canvas
        if (!open) return;
        GUI.SetNextControlName("cheat");
        input = GUI.TextField(new Rect(10, 10, 400, 30), input);
        GUI.FocusControl("cheat");
        if (Event.current.isKey && Event.current.keyCode == KeyCode.Return && input.Length > 0) {
            var parts = input.Split(' ');
            if (cmds.TryGetValue(parts[0], out var cmd)) cmd(parts[1..]); else Debug.LogWarning($"Không có lệnh {parts[0]}");
            input = "";
        }
    }
}
#endif
```

Cùng file, thêm **debug overlay** hiện state hiện tại của FSM nhân vật/enemy, giá trị input, số enemy sống — chữ trắng góc trên bằng `GUI.Label`. Với behavior tree hoặc utility AI, overlay hiện điểm của từng lựa chọn là cách duy nhất debug được "vì sao nó làm thế". Playtest có overlay bật cho biết thứ mà người chơi không nói ra ([[playtesting-metrics]]).

Log có cấu trúc và strip khỏi release:

```csharp
public static class Log {
    [System.Diagnostics.Conditional("UNITY_EDITOR"), System.Diagnostics.Conditional("DEVELOPMENT_BUILD")]
    public static void Dev(string tag, string msg, UnityEngine.Object ctx = null) => Debug.Log($"[{tag}] {msg}", ctx);
}
// Log.Dev("Combat", $"hit {target.name} dmg={dmg}");  -> cả lời gọi VÀ phép nối chuỗi biến mất ở release
```

`[Conditional]` xoá **cả lời gọi lẫn việc đánh giá tham số** — khác với `if (Debug.isDebugBuild)` vẫn tạo string. `Debug.Log` trong release còn tốn thêm vì stack trace: `Project Settings > Player > Stack Trace` đặt `None` cho `Log`, giữ `ScriptOnly` cho `Error`.

## Vòng lặp Editor nhanh hơn

**Enter Play Mode Options** (`Project Settings > Editor`): tắt `Reload Domain` giảm thời gian bấm Play từ 5–15 s xuống dưới 1 s ở dự án trung bình. Đổi lại: **static field không reset** giữa các lần Play — `static int score` giữ giá trị cũ, `static event` giữ subscriber của lần trước (gọi vào object đã destroy → `MissingReferenceException` khó hiểu). Sửa: mọi static có trạng thái được reset trong

```csharp
[RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.SubsystemRegistration)]
static void ResetStatics() { Instance = null; OnScoreChanged = null; }
```

Quy tắc team: bật tắt Domain Reload từ ngày 1 để lỗi static lộ sớm, không phải khi đã có 80 static.

`[InitializeOnLoad]` (static constructor chạy khi Editor load/recompile) và `[InitializeOnLoadMethod]` để đăng ký callback, kiểm tra settings project khi mở (ví dụ cảnh báo nếu `Color Space` không phải Linear). `EditorApplication.playModeStateChanged` để chạy validator trước khi vào Play.

## Test cho logic thuần

Unity Test Framework (package `com.unity.test-framework`) chạy `[Test]` NUnit trong Edit Mode cho code không đụng MonoBehaviour: công thức sát thương, drop table, state machine, parser save. Điều kiện: logic đó phải nằm trong class C# thuần trong asmdef riêng — đó cũng là lý do [[unity-project-structure]] khuyên tách `Gameplay.Core` khỏi `Gameplay.Unity`. Test cho MonoBehaviour (Play Mode test) chậm và giòn; giữ số lượng ít, chỉ cho luồng bootstrap.

```csharp
[Test]
public void CritMultiplier_ClampsAtCap() {
    var f = new DamageFormula(critCap: 3f);
    Assert.AreEqual(3f, f.Multiplier(critLevel: 99));
}
```

Validator asset (`Validate()` trên mọi SO) cũng chạy như test: một `[Test]` duyệt `AssetDatabase.FindAssets("t:EnemyData")` và fail khi bất kỳ asset nào trả lỗi. CI chạy `-runTests -testPlatform EditMode` là bước chặn dữ liệu hỏng trước build.

## AI agent viết editor tool

Đây là nhiệm vụ agent làm tốt hơn phần lớn việc khác ([[ai-workflow]]): phạm vi rõ, kiểm chứng tức thì, không cần chơi thử. Cách yêu cầu khác với code gameplay:
- Nêu **API Editor cụ thể** (UI Toolkit hay IMGUI, `SceneView.duringSceneGui` hay `Editor.OnSceneGUI`) — agent trộn API 2019 và Unity 6 nếu không nêu.
- Yêu cầu **Undo cho mọi thay đổi** và `SetDirty`/`SaveAssets` đúng chỗ.
- Cấm `AssetDatabase.Refresh()` trong vòng lặp và cấm `Resources.FindObjectsOfTypeAll` mỗi frame.
- Chỉ đường dẫn `Editor/` hoặc asmdef Editor, và `#if UNITY_EDITOR` cho code trong runtime assembly.
- Bảo agent **chạy tool trên asset thật** rồi báo cái gì đổi — agent có thể dùng `-executeMethod` từ dòng lệnh nếu môi trường cho phép.

Guardrail như [[agent-guardrails]]: agent được viết tool sinh/kiểm dữ liệu, không được tự đổi số cân bằng trong asset đã có.

## Bẫy lộ ra khi build

- Script trong runtime assembly `using UnityEditor;` không bọc `#if UNITY_EDITOR` → build fail ở phút cuối. Asmdef Editor-only là cách chặn cấu trúc.
- `CheatConsole` để ngoài `#if DEVELOPMENT_BUILD` "tạm thời" → người chơi bấm `~` là god mode. Kiểm tra bằng grep trước mỗi release.
- `OnValidate` gọi `AssetDatabase.SaveAssets` → mỗi lần gõ một chữ trong Inspector là lưu toàn project.
- `EditorPrefs` là **toàn máy**, chung cho mọi project — đặt key có tiền tố tên project, không thì tool của hai dự án ghi đè nhau.
- `[SerializeReference]` với IL2CPP `Managed Stripping Level = High` strip class không được tham chiếu tĩnh → deserialize ra `null` trên build. `[Preserve]` hoặc `link.xml`.

## Kiểm tra nhanh

- Bấm Play ở dự án hiện tại: < 2 s. Trên 5 s là chưa tắt Domain Reload hoặc có `[InitializeOnLoad]` nặng.
- Mở Scene lớn nhất, chọn không gì cả: Scene view ≥ 60 FPS. Thấp hơn là có `OnDrawGizmos` không `Selected` trên object đông.
- Chọn 10 asset ngẫu nhiên trong `Assets/Art/` và `Assets/Audio/`: import settings đúng bảng 10/10.
- Development Build trên máy thật: mở cheat console bằng 3 ngón, gõ `level 5` — nhảy được. Release build: không mở được.
- `Window > General > Test Runner` > Run All Edit Mode: xanh, dưới 30 s.

Quyết định đầu tiên của dự án, trước cả nhân vật đầu tiên: **hệ thống sống ở đâu, và ai quyết định game đang ở trạng thái nào?** Dự án trả lời "ở scene Menu, trong GameManager" thì đến tháng thứ ba không Play được từ scene Level, không test được màn Result, và mỗi lần thêm màn hình là thêm một `if` vào GameManager.

Câu trả lời đã chứng minh: một **Bootstrap scene** chỉ chứa hệ thống, một **state machine cấp ứng dụng** nhỏ, và mọi scene gameplay được nạp **additive**. [[core-loop]] là vòng lặp của người chơi; node này là vòng lặp của chương trình bao quanh nó.

## Bootstrap scene: scene 0 không có gameplay

Scene đầu tiên trong Build Settings tên `Boot`, chứa đúng một GameObject `Systems` với các service (audio, save, input, UI root, scene loader) và **không có gì khác** — không camera gameplay, không nhân vật. Boot nạp `Menu` additive rồi đứng đó mãi.

Ba lợi ích không thấy ngay ở tuần 1:
- Hệ thống khởi tạo **một lần** theo thứ tự bạn kiểm soát, không phụ thuộc scene nào được mở.
- Chuyển scene không phá hệ thống — không cần `DontDestroyOnLoad` cho từng cái (Boot không bao giờ bị unload).
- Play từ bất kỳ scene nào trong Editor vẫn chạy, nhờ đoạn này:

```csharp
#if UNITY_EDITOR
public static class BootGuard {
    [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.AfterSceneLoad)]
    static void EnsureBoot() {
        if (!SceneManager.GetSceneByName("Boot").isLoaded)
            SceneManager.LoadScene("Boot", LoadSceneMode.Additive);
    }
}
#endif
```

Hệ thống lúc này chỉ sẵn sàng từ frame thứ hai, nên gameplay script **không được đụng service trong `Awake`** — điều bạn vốn nên tuân theo dù có Boot hay không (xem mục thứ tự thực thi).

## State machine cấp ứng dụng

`Boot → Menu → Loading → Gameplay ⇄ Pause → Result`. Sáu trạng thái, một bảng chuyển hợp lệ, và **mọi thay đổi trạng thái đi qua một hàm**. Không phải để đẹp: để khi màn Result hiện giữa lúc đang Loading, bạn có một dòng log nói rõ ai gọi.

```csharp
using System; using System.Collections.Generic; using UnityEngine;

public enum GameState { Boot, Menu, Loading, Gameplay, Pause, Result }

public sealed class GameFlow : MonoBehaviour {
    public static GameFlow I { get; private set; }
    public GameState State { get; private set; } = GameState.Boot;
    public event Action<GameState, GameState> StateChanged;

    static readonly Dictionary<GameState, GameState[]> allowed = new() {
        [GameState.Boot]     = new[] { GameState.Menu },
        [GameState.Menu]     = new[] { GameState.Loading },
        [GameState.Loading]  = new[] { GameState.Gameplay, GameState.Menu },
        [GameState.Gameplay] = new[] { GameState.Pause, GameState.Result, GameState.Loading },
        [GameState.Pause]    = new[] { GameState.Gameplay, GameState.Loading },
        [GameState.Result]   = new[] { GameState.Loading, GameState.Menu },
    };

    void Awake() {
        if (I != null && I != this) { Destroy(gameObject); return; }   // chống trùng bản
        I = this;
    }

    public bool TrySet(GameState next) {
        if (Array.IndexOf(allowed[State], next) < 0) {
            Debug.LogError($"Chuyển trạng thái cấm: {State} → {next}", this);
            return false;
        }
        var prev = State;
        State = next;
        Time.timeScale = next == GameState.Pause ? 0f : 1f;   // nơi DUY NHẤT đụng timeScale
        StateChanged?.Invoke(prev, next);
        return true;
    }
}
```

Enum + bảng đủ cho cấp ứng dụng. FSM đầy đủ với class per-state (xem [[unity-design-patterns]]) dành cho gameplay, nơi trạng thái có logic riêng mỗi frame. Đừng nhét logic tính điểm, spawn, hay UI vào `GameFlow` — nó chỉ **phát sự kiện**, các hệ thống tự nghe. Đây chính là chỗ `GameManager` phình ra nếu bạn không kỷ luật.

## Thứ tự thực thi: Awake là của mình, Start là của người khác

Trong một scene, Unity gọi `Awake` của **mọi** object, rồi `OnEnable` của mọi object, rồi `Start` của mọi object, trước `Update` đầu tiên. Thứ tự **giữa các object trong cùng pha là không xác định** — nó trông ổn định trong Editor và đổi trên build hoặc sau khi bạn thêm một prefab.

Hệ quả thành luật:
- `Awake`: `GetComponent` trên **chính mình**, khởi tạo field. Không gọi sang object khác — object đó có thể chưa `Awake`.
- `OnEnable`: đăng ký event. Nhưng nếu đăng ký vào một singleton, singleton đó phải `Awake` trước — nghĩa là nó phải nằm ở Boot.
- `Start`: nói chuyện với người khác. Mọi thứ đã `Awake` xong.
- Object `Instantiate` lúc chạy: `Awake` và `OnEnable` chạy **ngay trong lệnh Instantiate**, `Start` chạy trước `Update` kế. Truyền dữ liệu cho object vừa spawn qua hàm `Init()` gọi sau `Instantiate`, đừng trông vào `Start` đọc field đã gán kịp.

Khi bắt buộc cần thứ tự, dùng attribute thay Project Settings để nó nằm trong code và trong Git:

```csharp
[DefaultExecutionOrder(-100)]          // chạy Awake/Update trước mọi script mặc định (0)
public sealed class InputReader : MonoBehaviour { … }
```

Số âm cho hệ thống đọc input và thời gian; số dương lớn cho camera (chạy sau mọi chuyển động). Không quá 5 script có số khác 0 — nhiều hơn là dấu hiệu bạn đang dùng thứ tự thực thi để che phụ thuộc ngầm.

## `Time.timeScale = 0` không dừng những gì bạn nghĩ

| Dừng theo timeScale | Không dừng |
|---|---|
| `Time.deltaTime` về 0; `FixedUpdate` không chạy | `Update`/`LateUpdate` **vẫn được gọi** mỗi frame |
| Animator (`Update Mode = Normal`) | Animator `Unscaled Time` — dùng cho UI menu pause |
| Particle System (`Simulation Speed` theo scaled) | `Time.unscaledDeltaTime`, `Time.realtimeSinceStartup` |
| `WaitForSeconds`, `Invoke`, `InvokeRepeating` | `WaitForSecondsRealtime`; `Awaitable.NextFrameAsync` |
| DOTween mặc định | DOTween `.SetUpdate(true)` |
| Physics, NavMeshAgent | **AudioSource** — nhạc vẫn chạy, `pitch` không đổi |

Hậu quả thực tế: menu pause dùng `WaitForSeconds(0.3f)` cho hiệu ứng mở → menu **không bao giờ mở**. Coroutine đếm cooldown bằng `WaitForSeconds` bị pause là đúng; tween của menu bằng `WaitForSeconds` là sai. Audio thì ngược lại: muốn nhạc tạm dừng phải gọi `AudioListener.pause = true` (hoặc chuyển snapshot mixer, xem [[unity-audio]]), timeScale không giúp gì.

Luật một dòng: **gameplay đo bằng `deltaTime`, UI và hệ thống đo bằng `unscaledDeltaTime`**. Slow-motion (`timeScale = 0.3`) đi qua đúng đường này miễn phí. Từ Unity 2022 không cần tự scale `fixedDeltaTime` theo `timeScale` nữa trừ khi vật lý trông giật khi quay chậm.

## Loading không khựng

`SceneManager.LoadScene` đồng bộ đóng băng frame 0.5–4 giây trên mobile. Thanh loading không nhích, người chơi tưởng treo. Dùng async và giữ scene ở 90% cho tới khi UI sẵn sàng:

```csharp
using UnityEngine; using UnityEngine.SceneManagement;

public sealed class SceneLoader : MonoBehaviour {
    public async Awaitable LoadLevelAsync(string sceneName, System.IProgress<float> progress = null) {
        if (!GameFlow.I.TrySet(GameState.Loading)) return;
        var previous = SceneManager.GetActiveScene();

        var op = SceneManager.LoadSceneAsync(sceneName, LoadSceneMode.Additive);
        op.allowSceneActivation = false;                 // giữ ở 0.9 — nạp xong nhưng chưa Awake
        while (op.progress < 0.9f) {
            progress?.Report(op.progress / 0.9f);
            await Awaitable.NextFrameAsync();
        }
        await Awaitable.WaitForSecondsAsync(0.25f);      // chống nhấp nháy khi nạp quá nhanh
        op.allowSceneActivation = true;                  // frame này sẽ nặng: Awake của cả scene
        await op;                                        // Unity 6: AsyncOperation await được trực tiếp

        SceneManager.SetActiveScene(SceneManager.GetSceneByName(sceneName));
        if (previous.name != "Boot") await SceneManager.UnloadSceneAsync(previous);
        GameFlow.I.TrySet(GameState.Gameplay);
    }
}
```

`Awaitable` có từ Unity 2023.1; bản 2022 dùng coroutine hoặc UniTask (`op.ToUniTask()`). UniTask là tuỳ chọn tốt nếu team đã quen, nhưng đừng thêm chỉ vì đoạn này. Khoảnh khắc `allowSceneActivation = true` **vẫn khựng** một frame vì toàn bộ `Awake` của scene mới chạy trong frame đó — scene có 2.000 object thì khựng 200ms; đó là lý do thanh loading nên đứng ở 100% thêm một nhịp thay vì hứa "sẵn sàng" sớm.

Hai bẫy đi kèm: `Awaitable.WaitForSecondsAsync` **theo scaled time** (dừng khi pause), và mọi `await` sống lâu hơn object gọi nó — truyền `destroyCancellationToken` nếu hàm có thể bị huỷ giữa đường.

## `DontDestroyOnLoad` và bản trùng

Có Boot scene thì gần như không cần `DontDestroyOnLoad`. Nếu vẫn dùng (prefab hệ thống tự spawn), ba tình huống tạo bản trùng: quay về Menu bằng `LoadScene("Boot")`, Play từ scene có sẵn một bản trong Editor, hoặc prefab bị kéo vào hai scene. Guard trong `Awake` (như `GameFlow` ở trên) là bắt buộc, và **nên `Destroy(gameObject)` bản mới, không phải bản cũ** — bản cũ đang có người đăng ký event.

## Thứ tự init hệ thống và chờ nhau

Hệ thống có phụ thuộc: input cần save (để nạp rebinding), UI cần input và audio (tiếng bấm nút). Viết thứ tự đó **thành một hàm tuần tự**, không rải qua `Awake` của từng service với `[DefaultExecutionOrder]`:

```csharp
public sealed class Bootstrapper : MonoBehaviour {
    [SerializeField] AudioService audio;
    [SerializeField] SaveService save;
    [SerializeField] InputService input;
    [SerializeField] UIRoot ui;

    async void Start() {                    // async void CHỈ ở điểm vào này; nơi khác trả Awaitable
        try {
            await audio.InitAsync();        // nhanh, nhưng phải xong trước tiếng bấm nút đầu tiên
            await save.LoadAsync();         // đọc file, có thể 50–300ms trên mobile
            await input.InitAsync(save.Data.bindings);
            await ui.InitAsync();
            GameFlow.I.TrySet(GameState.Menu);
        } catch (System.Exception e) {
            Debug.LogException(e);
            ui.ShowFatal("Không khởi động được. Thử cài lại.");   // đừng để màn đen im lặng
        }
    }
}
```

Mỗi service có `InitAsync` trả `Awaitable` và **không làm gì trong `Awake`** ngoài cache tham chiếu. Thêm service mới = thêm một dòng `await`, và thứ tự nằm ngay trước mắt. Save/load chi tiết ở [[unity-save-data]].

## Dọn dẹp khi rời scene

Object trong scene Level đăng ký `GameFlow.I.StateChanged += OnState` trong `Start`, rồi scene bị unload. Delegate vẫn giữ tham chiếu tới object đã destroy. Lần đổi trạng thái kế: `MissingReferenceException` — hoặc tệ hơn, handler chạy trên object "chết" và ghi vào field của nó mà không báo gì.

- Đăng ký trong `OnEnable`, gỡ trong `OnDisable`. **Không** cặp `Start`/`OnDestroy`: object bị disable rồi enable lại sẽ đăng ký hai lần.
- Không đăng ký bằng lambda — `-=` với lambda mới là no-op, không gỡ được.
- Static event và static field **sống qua scene**, và nếu tắt Domain Reload trong Enter Play Mode Options thì sống qua cả lần Play sau. Reset chúng bằng `[RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.SubsystemRegistration)]`.
- Coroutine chạy trên object bị destroy tự dừng; `Awaitable`/`Task` thì **không** — kiểm tra `this == null` sau mỗi `await` hoặc dùng `destroyCancellationToken`.

## Mobile: pause là lúc phải lưu

Trên Android, `OnApplicationPause(true)` là **thời điểm đáng tin cuối cùng** trước khi hệ điều hành có thể giết tiến trình; `OnApplicationQuit` thường không được gọi. Trên iOS gần như không bao giờ được gọi. Vì vậy:

```csharp
void OnApplicationPause(bool paused) {
    if (paused) { SaveService.I.SaveNow(); AudioListener.pause = true; }   // đồng bộ, KHÔNG await — bạn không có thời gian
    else        { AudioListener.pause = false; ResumeTimers(); }
}
void OnApplicationFocus(bool focus) {
    if (!focus && GameFlow.I.State == GameState.Gameplay) GameFlow.I.TrySet(GameState.Pause);   // popup thông báo cũng mất focus
}
```

Thứ tự trên Android: `OnApplicationFocus(false)` → `OnApplicationPause(true)`. Focus mất khi có popup quyền, quảng cáo, thông báo hệ thống — chỉ nên pause gameplay ở đó, **không lưu** (lưu 5 lần trong 3 giây khi người dùng kéo notification). Khi resume, `Time.unscaledDeltaTime` của frame đầu **không bị kẹp** bởi `Maximum Delta Time` — bộ đếm dùng unscaled sẽ nhảy 20 phút; tính thời gian rời game bằng `DateTime.UtcNow` lưu lúc pause, đừng trông vào delta.

## Bẫy lộ ra khi build

- `Application.targetFrameRate` mặc định trên mobile là 30 (theo vSync). Editor chạy không giới hạn nên bạn không biết game mình 30 FPS cho tới khi cài lên máy. Đặt tường minh trong Boot.
- Nạp scene theo **index** rồi ai đó kéo lại thứ tự Build Settings → nạp sai scene, không có lỗi biên dịch. Nạp theo tên, hoặc giữ tên trong ScriptableObject.
- WebGL không có thread: `Task.Run`, `Task.Delay` không chạy hoặc treo. Dùng `Awaitable` và coroutine nếu WebGL là mục tiêu. Xem [[unity-build-platform]].
- Trong Editor, `Task` tiếp tục chạy sau khi thoát Play Mode và ghi vào asset. `Awaitable` được huỷ khi thoát Play — một lý do để chọn nó.
- Scene có Auto Generate Lighting bật sẽ bake lại mỗi lần mở → mở scene chậm và Git thay đổi liên tục. Tắt, bake tay.

## Kiểm tra nhanh
- Bấm Play từ **mỗi** scene trong project: không NullReference nào trong 2 giây đầu.
- Pause 30 giây rồi tiếp tục: cooldown, timer, nhạc đúng vị trí? Menu pause có mở được khi `timeScale = 0`?
- Menu → Level → Menu → Level 5 vòng: Hierarchy `DontDestroyOnLoad` không tăng object; Memory Profiler không tăng quá 10MB mỗi vòng.
- Nạp scene nặng nhất: thanh loading giữ trên 30 FPS, frame khựng duy nhất là lúc kích hoạt.
- Android: nhận thưởng → bấm Home ngay → kill từ Recent Apps → mở lại: thưởng còn không?

Quyết định quan trọng nhất không phải "package nào" — câu đó đã có đáp án — mà là **input đi vào game qua đúng một cửa**. Dự án có `Input.GetKey` trong 5 script, `PlayerInput` Unity Events trong 3 prefab, và `action.ReadValue` rải trong controller là dự án không bao giờ làm được rebinding, không chuyển được sang tay cầm, và không pause được cho đúng. Một lớp `InputReader` là điểm duy nhất chạm vào Input System; phần còn lại của game chỉ biết `Move`, `JumpPressed`, `Attack` — không biết phím nào.

## Mới hay cũ — và cái bẫy "Both"

**Input System** (package, 1.x) thắng Input Manager cũ ở mọi thứ cần cho game ship được: rebinding, control scheme, nhiều tay cầm, touch, và event thay cho polling. Cái duy nhất cũ làm tốt hơn là *bắt đầu nhanh* — 1 dòng `Input.GetAxis("Horizontal")` — và đó chính là cách nó lọt vào dự án.

`Project Settings > Player > Active Input Handling` có ba giá trị. **"Both"** là bẫy: cả `UnityEngine.Input` lẫn package đều chạy, nên team viết lẫn lộn mà không ai bị báo lỗi, `EventSystem` với `StandaloneInputModule` cũ vẫn hoạt động, và bạn phát hiện ra sau 4 tháng khi làm rebinding. Đặt **"Input System Package (New)"**: mọi `Input.GetKey` ném `InvalidOperationException` ngay — đó là tính năng, không phải lỗi.

## Action Map theo ngữ cảnh

Một asset `.inputactions` với ít nhất hai map: **Player** (Move, Jump, Attack, Interact, Pause) và **UI** (Navigate, Submit, Cancel, Point, Click — Unity sinh sẵn). Thường thêm **Menu**/**Dialogue** nếu ngữ cảnh đó có nút riêng. Bệnh kinh điển "mở menu, bấm A để chọn, nhân vật phía sau nhảy" là vì cả hai map cùng bật. Mở menu = tắt Player, bật UI; đóng = ngược lại. Không bật hai map có phím trùng cùng lúc, trừ map "Global" chỉ chứa Pause/Screenshot.

`Pause` nằm ở map Player, `Unpause` (cùng phím) nằm ở map UI — hai action, cùng binding, không bao giờ cùng bật, nên không có chuyện bấm một lần mở-đóng-mở.

## Ba cách đọc — chọn một

| Cách | Ưu | Nhược | Dùng khi |
|---|---|---|---|
| **Generated C# class** (tick "Generate C# Class" trên asset) | Kiểu tĩnh, đổi tên action là lỗi biên dịch, không tham chiếu scene | Phải commit file sinh ra; một instance mỗi người chơi | **Mặc định.** Mọi game 1 người chơi |
| `PlayerInput` component + Unity Events / Send Messages | Kéo thả, tự chia thiết bị cho local co-op, `onControlsChanged` sẵn | Logic trong Inspector không grep được; Send Messages dùng reflection theo tên | Local co-op split-device 2–4 người |
| Polling `action.ReadValue<T>()` / `WasPressedThisFrame()` mỗi frame | Đơn giản, giống Input cũ | Phải giữ tham chiếu action; dễ rải khắp nơi | Bên trong InputReader, không ở nơi khác |

Khuyến nghị: generated class bọc trong **một ScriptableObject `InputReader`**, mọi hệ thống tham chiếu asset này qua Inspector. ScriptableObject sống xuyên scene, không cần singleton, mock được trong test.

```csharp
using UnityEngine;
using UnityEngine.InputSystem;

[CreateAssetMenu(menuName = "Game/Input Reader")]
public class InputReader : ScriptableObject, GameInput.IPlayerActions {
    GameInput input;                                   // class sinh từ GameInput.inputactions

    public Vector2 Move { get; private set; }
    public bool JumpHeld { get; private set; }
    public event System.Action JumpPressed, AttackPressed, PausePressed;

    float jumpBufferedAt = -10f;

    void OnEnable() {
        if (input == null) { input = new GameInput(); input.Player.SetCallbacks(this); }
        EnableGameplay();
    }
    void OnDisable() { input?.Disable(); Move = Vector2.zero; JumpHeld = false; }   // SO giữ state xuyên Play khi tắt Domain Reload

    public void EnableGameplay() { input.UI.Disable(); input.Player.Enable(); }
    public void EnableUI()       { input.Player.Disable(); input.UI.Enable(); Move = Vector2.zero; }

    public void OnMove(InputAction.CallbackContext ctx) => Move = ctx.ReadValue<Vector2>();

    public void OnJump(InputAction.CallbackContext ctx) {
        if (ctx.performed) { JumpHeld = true; jumpBufferedAt = Time.unscaledTime; JumpPressed?.Invoke(); }
        else if (ctx.canceled) JumpHeld = false;
    }
    public void OnAttack(InputAction.CallbackContext ctx) { if (ctx.performed) AttackPressed?.Invoke(); }
    public void OnPause(InputAction.CallbackContext ctx)  { if (ctx.performed) PausePressed?.Invoke(); }
    public void OnInteract(InputAction.CallbackContext ctx) { }

    /// Input buffer: nhấn trong `window` giây gần đây thì tính, và tiêu thụ luôn.
    public bool ConsumeJump(float window = 0.12f) {
        if (Time.unscaledTime - jumpBufferedAt > window) return false;
        jumpBufferedAt = -10f;
        return true;
    }
}
```

Phải implement **mọi** phương thức của `IPlayerActions`, kể cả để trống — thêm action vào asset là lỗi biên dịch nhắc bạn xử lý. Đó là lý do chọn interface thay cho `action.performed += …` từng cái.

## "Pressed this frame" và bẫy FixedUpdate

`action.WasPressedThisFrame()` trả `true` trong **frame render** có sự kiện nhấn. Gọi nó trong `FixedUpdate` thì: frame có 2 bước physics → nhảy đôi; frame không có bước physics nào → mất nhấn. Đây là nguồn phổ biến nhất của "thỉnh thoảng bấm nhảy không nhảy" và không tái hiện được vì phụ thuộc FPS. Cách đúng đã ở [[unity-physics]]: đọc trong callback/`Update`, giữ cờ hoặc timestamp, tiêu thụ trong `FixedUpdate`. `ConsumeJump` ở trên là dạng có buffer sẵn — 100–150ms theo [[game-feel]].

`InputSystem.settings.updateMode` mặc định `ProcessEventsInDynamicUpdate`. Đổi sang `ProcessEventsInFixedUpdate` làm `WasPressedThisFrame` đúng trong FixedUpdate nhưng **sai trong Update** — đừng đổi để chữa một chỗ rồi hỏng chỗ khác.

## Rebinding lúc chạy

```csharp
InputActionRebindingExtensions.RebindingOperation op;

public void StartRebind(InputAction action, int bindingIndex, System.Action onDone) {
    action.Disable();                                  // BẮT BUỘC — action đang bật thì rebind ném lỗi
    op = action.PerformInteractiveRebinding(bindingIndex)
        .WithControlsExcluding("<Mouse>/position")
        .WithControlsExcluding("<Mouse>/delta")
        .WithCancelingThrough("<Keyboard>/escape")
        .OnMatchWaitForAnother(0.1f)                   // chờ 100ms để bắt cả tổ hợp
        .OnCancel(o => Finish(action, onDone))
        .OnComplete(o => {
            PlayerPrefs.SetString("bindings", action.actionMap.asset.SaveBindingOverridesAsJson());
            Finish(action, onDone);
        })
        .Start();
}

void Finish(InputAction action, System.Action onDone) { op?.Dispose(); op = null; action.Enable(); onDone(); }

// Lúc khởi động: input.asset.LoadBindingOverridesFromJson(PlayerPrefs.GetString("bindings", ""));
```

Ba chi tiết hay thiếu: **composite** (WASD là một `2DVector` với 4 binding con) — `bindingIndex` phải trỏ vào binding con có `isPartOfComposite`, không phải binding cha; **binding của scheme khác** — rebind phím trên keyboard không được đụng binding gamepad, lọc bằng `action.bindings[i].groups`; và **trùng phím** — Input System không cấm hai action cùng phím, bạn phải tự kiểm và hỏi "đổi hay hoán". Luôn có nút Reset (`action.RemoveAllBindingOverrides()`). JSON override lưu theo **id** binding, không phải theo thứ tự — sửa asset không làm mất setting người chơi.

## Đổi thiết bị nóng và glyph đúng

Người chơi rút tay cầm giữa trận: game phải pause và hiện "Tay cầm đã ngắt", không phải để nhân vật đứng chịu đòn. `InputSystem.onDeviceChange` với `InputDeviceChange.Disconnected` là chỗ móc. Với `PlayerInput`, `onControlsChanged` báo scheme mới (`"Gamepad"`, `"Keyboard&Mouse"`); với generated class, đọc `ctx.control.device` trong callback và tự đổi scheme khi thiết bị khác scheme hiện tại.

Glyph "Nhấn [A] để nhặt" lấy từ binding thật, không hardcode:

```csharp
string label = interactAction.GetBindingDisplayString(
    InputBinding.MaskByGroup(currentScheme), out string deviceLayout, out string controlPath);
// controlPath = "buttonSouth" → tra sprite trong TMP Sprite Asset theo deviceLayout ("DualShockGamepad" / "XInputController")
```

`controlPath` mới là khoá tra sprite; `label` chỉ là chữ dự phòng. Bẫy: chuột rung nhẹ trên bàn cũng đổi scheme về Keyboard&Mouse, glyph nhấp nháy A ↔ E. Chỉ đổi scheme khi có **nhấn nút**, bỏ qua `Mouse/delta` và `Mouse/position`.

## Deadzone và processor — trong asset, không trong code

Stick gamepad cũ trôi 0.05–0.1 khi thả. Processor **Stick Deadzone** (min 0.125, max 0.925 mặc định) đặt trên **binding gamepad** của action Move — không đặt trên action, vì nó sẽ áp lên cả WASD và làm phím "chưa đủ nghiêng". Scale Vector 2 cho độ nhạy, Invert Vector 2 cho đảo trục Y. Tất cả trong asset để designer chỉnh không cần build.

Setting của người chơi (độ nhạy, đảo Y) đổi processor lúc chạy mà không sửa asset:

```csharp
input.Player.Look.ApplyParameterOverride("scaleVector2:x", sensitivity);   // Input System 1.5+
input.Player.Look.ApplyParameterOverride("invertVector2:invertY", invertY);
```

## Mobile

- **On-Screen Stick / On-Screen Button** (có sẵn trong package) gửi sự kiện như một `Gamepad` ảo — cùng action map, không cần code riêng. Đủ cho 90% game.
- Đa chạm thật (hai ngón cùng lúc, cử chỉ) dùng **`EnhancedTouch`**: `EnhancedTouchSupport.Enable()` rồi `Touch.activeTouches`. Không bật thì `Touchscreen.current` chỉ tiện cho một ngón.
- **Chạm xuyên qua UI** — chạm nút Pause mà nhân vật bắn. `EventSystem.current.IsPointerOverGameObject()` không tham số với Input System mới **luôn sai và có warning**; phải truyền `touchId`, và **không gọi trong callback action** (UI chưa xử lý xong frame đó). Kiểm trong `Update` trước khi tiêu thụ chạm, hoặc cấu hình để action Fire chỉ nhận từ vùng joystick — hoặc đơn giản nhất: UI chiếm layer trên, mọi chạm gameplay đi qua một `Image` trong suốt có `IPointerDownHandler`, UI ăn chạm trước theo đúng luật raycast.

## UI navigation bằng gamepad

Thay `StandaloneInputModule` bằng **`InputSystemUIInputModule`** trên EventSystem, trỏ vào map UI của asset. Hai bệnh: (1) **mất selected object** — bấm chuột ra vùng trống là `EventSystem.currentSelectedGameObject = null`, D-pad không còn di chuyển được gì. Chữa: mỗi màn hình nhớ `lastSelected`, và trong `Update` nếu `currentSelectedGameObject == null` mà có input Navigate thì `SetSelectedGameObject(lastSelected)`. (2) **focus mặc định** khi mở panel — gọi `EventSystem.current.SetSelectedGameObject(firstButton)` trong `OnEnable` sau một frame (panel chưa layout xong ở frame đầu). Cả hai đều là yêu cầu ở [[ux-flow]]; Unity không làm giúp.

## Input trong pause

`Time.timeScale = 0` **không** dừng Input System — nó đo thời gian bằng đồng hồ thực riêng. Hệ quả hai chiều: `Hold` interaction (giữ 0.4s để chạy) vẫn kích trong pause, tốt cho "giữ để bỏ qua cutscene"; nhưng logic tự viết cộng `Time.deltaTime` để đo giữ nút thì đứng — dùng `Time.unscaledDeltaTime` cho mọi thứ input. `FixedUpdate` không chạy khi `timeScale = 0`, nên bất kỳ cờ input nào chỉ được tiêu thụ trong `FixedUpdate` sẽ tích luỹ trong pause và nổ ra lúc resume — reset cờ khi vào pause. Xem thứ tự thực thi ở [[unity-game-loop]].

## Trợ năng — rẻ nếu làm trong InputReader

Vì mọi input qua một cửa, ba việc ở [[accessibility]] chỉ tốn vài dòng: **toggle thay hold** (Sprint/Aim/Crouch — `if (A11y.HoldToToggle) held = !held` trong callback `performed`), **remap** (đã có ở trên), và **chống bấm nhầm** cho hành động không hoàn được — Hold interaction 0.5s cho "Xoá save", hoặc xác nhận hai bước. Mashing (bấm liên tục để thoát QTE) phải có lựa chọn thay bằng giữ.

## Bẫy lộ ra khi build

- File C# sinh từ asset không được regenerate trên máy build — **commit file `.cs` đó**, đừng để trong `.gitignore`.
- `Keyboard.current` / `Gamepad.current` là **null** khi không có thiết bị (mobile không có bàn phím, PC chưa cắm tay cầm). Mọi truy cập trực tiếp phải kiểm null; qua action thì không cần.
- **Supported Devices** trong Input System settings: đã liệt kê thì thiết bị ngoài danh sách bị bỏ qua hoàn toàn — tay cầm Android lạ "không nhận" là vì đây.
- WebGL: trình duyệt không báo gamepad cho tới khi người chơi **bấm một nút** trên nó — màn hình "Press any button" là bắt buộc, không phải trang trí.
- Android: nhiều tay cầm Bluetooth map sai layout; test ít nhất Xbox và một tay cầm rẻ tiền không tên trước khi ship.

## Kiểm tra nhanh
- Mở **Window > Analysis > Input Debugger**, mở menu trong game: map Player hiện *Disabled*, map UI *Enabled*? Đóng menu thì ngược lại?
- Giới hạn 30 FPS (`Application.targetFrameRate = 30`), bấm nhảy 20 lần dồn dập: đủ 20 lần nhảy, không nhảy đôi?
- Rút tay cầm giữa gameplay: game pause trong 1 frame, glyph đổi sang bàn phím; cắm lại nhận trong 1 giây?
- Rebind Jump sang phím khác, tắt mở game: phím mới còn? Bấm Reset về mặc định được?
- Mobile: chạm nút Pause 20 lần — nhân vật không bắn/nhảy lần nào?

Quyết định đầu tiên và quan trọng nhất: **để PhysX/Box2D điều khiển nhân vật, hay tự viết chuyển động và chỉ dùng physics để phát hiện va chạm?** Phần lớn game cảm giác tốt chọn cách hai. Phần lớn prototype chọn cách một rồi mất ba tuần chống lại engine.

## Ba cách điều khiển và khi nào dùng

| Cách | Cảm giác | Dùng khi |
|---|---|---|
| **Dynamic Rigidbody** — `AddForce`, để engine tính | Trôi, có quán tính, khó kiểm soát chính xác | Xe, bóng, vật thể ném, ragdoll, mọi thứ *nên* tuân vật lý |
| **Kinematic Rigidbody + tự tính** — đặt `linearVelocity` hoặc `MovePosition`, engine chỉ báo va chạm | Chính xác từng frame, vẫn tương tác được với dynamic body | Nhân vật hành động, platformer, top-down. **Mặc định nên chọn.** |
| **Tự viết hoàn toàn** — `Raycast`/`Cast` rồi tự dời transform | Kiểm soát tuyệt đối, xác định | Platformer 2D chính xác cao, game có replay/rollback, fighting game |

Nhân vật bằng dynamic rigidbody có ba bệnh kinh điển: trượt trên dốc, bật lên khi va cạnh, và không thể "dừng ngay" khi nhả phím vì ma sát là chuyện của engine. Sửa được, nhưng mỗi lần sửa là một hack chống lại solver. `CharacterController` có sẵn là kinematic dạng đơn giản — dùng được cho 3D nếu không cần tương tác vật lý phức tạp, nhưng nó không có bước lên bậc mượt và không đẩy được dynamic body nếu bạn không tự viết.

## FixedUpdate — nơi vật lý sống

Physics chạy theo bước cố định (`Time.fixedDeltaTime`, mặc định 0.02s = 50Hz), **không đồng bộ với render**. Một frame render có thể chạy 0, 1 hoặc 2 bước physics. Hậu quả:

- Đọc input trong `FixedUpdate` → **mất nhấn**: nút bấm và nhả trong một frame render 16ms có thể rơi giữa hai bước physics 20ms. Đọc input trong `Update`, giữ vào cờ, tiêu thụ trong `FixedUpdate`.
- Đặt velocity trong `Update` → bước physics chạy 2 lần với cùng giá trị hoặc 0 lần → giật.
- Camera follow trong `Update` bám theo rigidbody không bật interpolation → nhân vật rung ở nhịp lệch 60/50Hz.

```csharp
public class KinematicMover2D : MonoBehaviour {
    [SerializeField] float speed = 8f;
    Rigidbody2D rb;
    Vector2 moveInput;
    bool jumpPressed;                       // cờ giữ input giữa các bước

    void Awake() {
        rb = GetComponent<Rigidbody2D>();
        rb.bodyType = RigidbodyType2D.Kinematic;
        rb.interpolation = RigidbodyInterpolation2D.Interpolate;   // bắt buộc nếu camera bám theo
    }

    void Update() {
        moveInput = InputReader.Move;        // đọc mỗi frame render
        if (InputReader.JumpPressedThisFrame) jumpPressed = true;  // giữ, không ghi đè bằng false
    }

    void FixedUpdate() {
        var v = rb.linearVelocity;           // Unity 6; bản 2022 là rb.velocity
        v.x = moveInput.x * speed;
        if (jumpPressed) { v.y = 14f; jumpPressed = false; }        // tiêu thụ cờ
        rb.linearVelocity = v;
    }
}
```

**Interpolation** là cài đặt bị bỏ quên nhiều nhất. Không bật thì mọi thứ dynamic/kinematic nhìn rung nhẹ khi camera bám theo, và người ta đi tối ưu frame rate thay vì bật một checkbox. Bật `Interpolate` cho nhân vật và thứ camera nhìn vào; để `None` cho hàng trăm vật thể nền để tiết kiệm.

Nếu game cần physics mượt hơn ở 120Hz: giảm `Fixed Timestep` xuống 0.01 **và** kiểm tra `Maximum Allowed Timestep` để không rơi vào vòng xoáy chết — frame chậm → nhiều bước physics → frame càng chậm. Khi frame time vượt `Maximum Allowed Timestep`, Unity bỏ bước và game chạy chậm lại (slow motion) thay vì đóng băng.

## Collision matrix là thiết kế, không phải cấu hình

`Project Settings > Physics > Layer Collision Matrix`. Đây là công cụ tối ưu **và** công cụ thiết kế mạnh nhất trong physics, và thường bị để mặc định (mọi layer va chạm với mọi layer).

Bố cục layer đã chứng minh hiệu quả ở game hành động:

```
Player          va với: Ground, Enemy, EnemyHitbox, Pickup, Trigger
PlayerHitbox    va với: Enemy                     (chỉ để phát hiện đánh trúng)
Enemy           va với: Ground, Player, PlayerHitbox
EnemyHitbox     va với: Player
Projectile      va với: Ground, Enemy hoặc Player (tuỳ chủ)
Pickup          va với: Player                    (không va với Ground — dùng trigger, không rơi)
Debris/VFX      va với: Ground                    (KHÔNG với nhau — 200 mảnh vỡ va nhau là cách nhanh nhất giết frame)
```

Ba luật rút ra:
- **Hitbox và hurtbox là layer riêng**, không phải collider trên cùng layer với thân. Nếu không, đòn đánh trúng "thân" thay vì trúng vùng bạn muốn, và bạn không thể có i-frame chỉ bằng tắt một collider.
- **Thứ nhiều (đạn, mảnh vỡ, particle collider) không được va với nhau.** Chi phí va chạm tăng theo bình phương số vật thể trong cùng ô của broadphase.
- Mọi `Raycast`/`OverlapCircle` trong code **luôn truyền LayerMask**. Không truyền là quét mọi layer, kể cả trigger và VFX.

## Raycast — làm đúng để không cấp phát

```csharp
// ❌ cấp phát mảng mới mỗi lần gọi
Collider2D[] hits = Physics2D.OverlapCircleAll(pos, radius, enemyMask);

// ✅ buffer dùng lại — Unity 6 dùng ContactFilter2D + mảng cấp sẵn
static readonly Collider2D[] buf = new Collider2D[32];
static ContactFilter2D enemyFilter = new ContactFilter2D {
    useLayerMask = true, layerMask = enemyMask, useTriggers = false
};

int n = Physics2D.OverlapCircle(pos, radius, enemyFilter, buf);
for (int i = 0; i < n; i++) { /* buf[i] */ }
```

Kích cỡ buffer là quyết định thiết kế: 32 nghĩa là đòn đánh trúng tối đa 32 mục tiêu, cái thứ 33 bị bỏ qua **âm thầm**. Log warning khi `n == buf.Length` để biết mình đang mất.

Với 3D, `Physics.RaycastNonAlloc`, `OverlapSphereNonAlloc` tương tự. `Physics.queriesHitTriggers` mặc định `true` — raycast của bạn trúng trigger vùng nhận pickup và bạn tự hỏi vì sao "đạn nổ giữa không trung".

**Ground check** đúng là `BoxCast`/`CapsuleCast` xuống một đoạn ngắn (0.05–0.1) từ đáy collider, không phải một `Raycast` đơn từ tâm — ray đơn trượt khỏi mép nền và nhân vật "rơi" khi đứng nửa người ngoài rìa. Ba ray (trái/giữa/phải) là lựa chọn rẻ nếu không muốn BoxCast.

## Platformer: vật lý là để cảm giác, không phải để đúng

Platformer hay không dùng gia tốc trọng trường thật. Xem [[game-feel]] cho lý thuyết; phần Unity:

```csharp
[SerializeField] float jumpHeight = 3f, timeToApex = 0.4f, maxFallSpeed = 20f;
float gravity, jumpVelocity;
Vector2 v;

void Awake() {
    gravity = -2f * jumpHeight / (timeToApex * timeToApex);   // suy từ chiều cao và thời gian, không chọn tay
    jumpVelocity = -gravity * timeToApex;
}

void FixedUpdate() {
    float g = gravity;
    if (v.y < 0) g *= 2f;                                   // rơi nhanh hơn bay lên — cảm giác "nặng"
    else if (!InputReader.JumpHeld) g *= 3f;                // nhả nút thì cắt nhảy
    v.y += g * Time.fixedDeltaTime;
    v.y = Mathf.Max(v.y, -maxFallSpeed);                    // kẹp tốc độ rơi, không thì xuyên nền ở fps thấp
    rb.linearVelocity = v;
}
```

Đặt `rb.gravityScale = 0` và tự cộng trọng trường: designer nói "nhảy cao 3 ô, lên đỉnh trong 0.4s" thì số này vào thẳng Inspector, không phải mò `gravityScale` và lực nhảy đến khi trông ổn.

Coyote time (nhảy được 0.1s sau khi rời mép) và jump buffer (nhấn nhảy 0.1s trước khi chạm đất vẫn nhảy) là hai bộ đếm 5 dòng code mỗi cái, và là khác biệt giữa "chặt" và "khó chịu". Cả hai nằm trong `Update`, không phải `FixedUpdate`, vì chúng đo thời gian thật của người chơi.

## Va chạm tốc độ cao và xuyên vật

Đạn nhanh xuyên qua tường mỏng vì ở bước này nó ở bên trái, bước sau đã bên phải. Ba cách theo thứ tự nên thử:
1. **Đạn là raycast**, không phải collider. Mỗi bước physics cast từ vị trí cũ tới vị trí mới. Rẻ nhất, chính xác nhất, chuẩn cho súng.
2. `collisionDetectionMode = Continuous` trên vật thể nhanh. Tốn hơn nhưng vẫn rẻ nếu chỉ vài vật thể. `ContinuousDynamic` chỉ khi cả hai đều chuyển động nhanh.
3. Tăng tần số physics — cách tệ nhất vì phạt toàn bộ game cho vài viên đạn.

Tường mỏng hơn quãng đường vật đi trong một bước (tốc độ × 0.02) sẽ bị xuyên với Discrete. Tính con số này ra khi thiết kế level, đừng đợi QA báo.

## Trigger, OnCollision và những gì thật sự được gọi

- `OnTriggerEnter` yêu cầu **ít nhất một bên có Rigidbody** (kinematic cũng được). Hai collider tĩnh không bao giờ báo gì với nhau — nguồn của 90% câu hỏi "vì sao trigger không chạy".
- Kinematic 2D chỉ nhận va chạm với dynamic, trừ khi bật `useFullKinematicContacts`. Muốn hai kinematic (player và enemy đều kinematic) biết nhau chạm: bật cờ này hoặc dùng overlap thủ công.
- `OnCollisionEnter` được gọi trong bước physics, tức là **trước** `Update` của frame đó. Spawn/Destroy trong callback này an toàn, nhưng đổi `transform` của chính body đang va chạm giữa lúc solver chạy thì cho kết quả khó lường — đặt cờ, xử lý trong `FixedUpdate` kế.
- `Destroy` không xoá ngay. Object bị destroy vẫn có thể nhận thêm một `OnTriggerEnter` trong cùng bước. Dùng cờ `isDead`, đừng trông vào việc object "đã chết".

## Rigidbody và transform — đừng đụng cả hai

Ghi `transform.position` trực tiếp trên object có Rigidbody: engine phải đồng bộ lại, mất interpolation, và có thể teleport xuyên vật. Dời rigidbody bằng `rb.MovePosition` (kinematic) hoặc đặt `rb.position` rồi để bước physics kế xử lý. Đổi scale của collider lúc chạy là cách tốn nhất — engine dựng lại shape. Nếu cần thay đổi kích cỡ hitbox theo animation, bật/tắt nhiều collider con thay vì scale một cái.

Parent một Rigidbody dưới một Rigidbody khác gây hành vi kỳ lạ (con vừa theo cha vừa theo solver). Vật thể "gắn vào" (nhân vật đứng trên thuyền) làm bằng cách cộng vận tốc của nền vào vận tốc nhân vật, không phải parent.

## Bẫy lộ ra khi build

- `Physics.autoSyncTransforms` tắt mặc định từ 2018 — đặt transform rồi raycast **cùng frame** có thể trúng vị trí cũ. Gọi `Physics.SyncTransforms()` nếu bắt buộc, nhưng tốt hơn là không xen kẽ.
- Trên mobile, `Time.fixedDeltaTime = 0.02` với game 30 FPS nghĩa là 1–2 bước physics mỗi frame; nếu frame tụt xuống 20 FPS là 3 bước, mỗi bước tốn thêm. Đo tổng thời gian `FixedUpdate.PhysicsFixedUpdate` trong Profiler, không chỉ tính trung bình.
- `Rigidbody2D.simulated = false` rẻ hơn tắt GameObject khi pool đạn — không phải dựng lại body.
- Mesh Collider lồi (`convex`) giới hạn 255 đỉnh, không lồi thì không va được với mesh collider khác. Vật thể động dùng compound của Box/Capsule, mesh collider chỉ cho địa hình tĩnh.

## Kiểm tra nhanh
- Nhân vật đứng yên trên dốc 30° có trượt không? Có thì bạn đang dùng dynamic mà chưa xử lý ma sát/dốc.
- Bật `Window > Analysis > Physics Debugger`: có collider nào không nên tồn tại (trên VFX, trên UI, trên mesh trang trí) không?
- Profiler cột `Physics.Processing` ở cảnh đông nhất < 2ms?
- Camera bám nhân vật ở 144Hz có rung không? Không rung là interpolation đúng.
- Bắn đạn nhanh nhất vào tường mỏng nhất trong game 20 lần: xuyên bao nhiêu lần?

Save là hệ thống duy nhất mà **bug phát hiện sau khi phát hành không sửa được bằng patch**: file hỏng đã nằm trên máy người chơi. Mọi quyết định dưới đây xoay quanh một câu: *file save từ bản 1.0 phải nạp được ở bản 1.8, kể cả khi app bị giết đúng lúc đang ghi.*

Quyết định nền: **một class `SaveData` phẳng có field `version`, serialize ra JSON, ghi atomic vào `persistentDataPath`, và lưu id string thay cho mọi tham chiếu asset.**

## PlayerPrefs chỉ cho settings

Âm lượng, ngôn ngữ, chất lượng đồ hoạ: `PlayerPrefs`. Tiến trình: **không bao giờ**. Trên Windows nó nằm trong Registry (giới hạn ~1MB, không sao lưu được, không đọc bằng tay); trên Android là file XML mất khi xoá app; không có version, không atomic, không cùng file với tiến trình để đồng bộ cloud. [[progression]] đã cảnh báo; node này nói phần thay thế.

## Mô hình `SaveData`

```csharp
using System; using System.Collections.Generic;

[Serializable]
public sealed class SaveData {
    public int version = SaveMigrator.Current;
    public long savedAtUnixMs;                 // KHÔNG dùng DateTime — JsonUtility không serialize
    public double playtimeSec;                 // đơn điệu tăng, dùng giải quyết conflict cloud
    public int level;
    public int gold;
    public List<string> unlockedItemIds = new();
    public List<InventoryEntry> inventory = new();     // KHÔNG Dictionary — JsonUtility không hỗ trợ
    public List<string> openedChestIds = new();

    // Field cũ giữ lại để migration đọc được. Không dùng ở nơi khác.
    public float legacy_coins;
    public List<int> legacy_unlockIndices;
}

[Serializable] public struct InventoryEntry { public string itemId; public int count; }
```

Phẳng, không kế thừa, không property, không nullable. Field mới thêm vào **không cần migration**: JsonUtility để nguyên giá trị khởi tạo nếu JSON thiếu key. Chỉ đổi tên hay đổi nghĩa mới cần.

| | `JsonUtility` | Newtonsoft (`com.unity.nuget.newtonsoft-json`) |
|---|---|---|
| Dictionary, polymorphism, nullable, property | Không | Có |
| Cần `[Serializable]`, field public hoặc `[SerializeField]` | Có | Không |
| Tốc độ, cấp phát | Nhanh, ít GC | Chậm hơn 3–10x, nhiều GC |
| IL2CPP stripping | An toàn (dùng serializer của engine) | Reflection → cần `link.xml`/`[Preserve]` |
| Đọc JSON tuỳ ý (`JObject`) để migrate | Không | Có |

Bắt đầu bằng `JsonUtility`. Chuyển sang Newtonsoft khi cần Dictionary thật hoặc migration phải đọc JSON cũ theo cây. Không dùng `BinaryFormatter`: bị đánh dấu lỗi bảo mật, .NET đã bỏ, và không migrate được.

## Ghi atomic

App bị giết giữa `File.WriteAllText` để lại file cụt. `JsonUtility.FromJson` trên file cụt trả `null` hoặc ném lỗi, và người chơi mất 40 giờ. Ghi ra file tạm rồi hoán đổi:

```csharp
using System.IO; using UnityEngine;

public static class SaveIO {
    public static void WriteAtomic(string path, string json) {
        var tmp = path + ".tmp";
        File.WriteAllText(tmp, json);
        if (File.Exists(path)) File.Replace(tmp, path, path + ".bak");  // rename trên Unix: nguyên tử; giữ bản cũ làm .bak
        else File.Move(tmp, path);
    }

    public static SaveData ReadWithFallback(string path) {
        foreach (var p in new[] { path, path + ".bak" }) {
            if (!File.Exists(p)) continue;
            try {
                var data = JsonUtility.FromJson<SaveData>(File.ReadAllText(p));
                if (data != null) return SaveMigrator.Migrate(data);
            } catch (System.Exception e) { Debug.LogWarning($"Save hỏng: {p} — {e.Message}"); }
        }
        return null;
    }
}
```

Save 50KB ghi mất 1–20ms trên mobile: chấp nhận trên main thread ở checkpoint. Save vượt 500KB thì serialize trên main thread, ghi ở `Task.Run` (không WebGL). Trên WebGL, `System.IO` ghi vào bộ nhớ; phải gọi `FS.syncfs` từ jslib để đẩy xuống IndexedDB, không thì reload trang là mất.

## `persistentDataPath` không giống nhau

| Nền tảng | Đường dẫn | Bẫy |
|---|---|---|
| Windows | `%USERPROFILE%\AppData\LocalLow\<Company>\<Product>` | Đổi Company/Product Name sau phát hành = người chơi "mất save" |
| macOS | `~/Library/Application Support/<Company>/<Product>` | Sandbox App Store đổi đường dẫn |
| Android | `/storage/emulated/0/Android/data/<package>/files` | Xoá app là mất; `allowBackup` mặc định sao lưu lên Google |
| iOS | `<App>/Documents` | **Mặc định lên iCloud backup**; cache lớn ở đây bị Apple từ chối — đánh `Device.SetNoBackupFlag` cho cache, giữ save được backup |
| WebGL | `/idbfs/<hash>` trong IndexedDB | Cần `syncfs`; người dùng xoá site data là mất |

Editor dùng đường dẫn của Windows/macOS với Company/Product của project — khác build. "Save mất khi test trên máy" đa phần là hai đường dẫn khác nhau.

## Migration theo chuỗi

```csharp
using System.IO; using System.Linq; using UnityEngine;

public static class SaveMigrator {
    public const int Current = 3;

    public static SaveData Migrate(SaveData d) {
        if (d.version > Current)
            throw new InvalidDataException($"Save từ bản mới hơn (v{d.version} > v{Current})");   // KHÔNG ghi đè
        while (d.version < Current) {
            switch (d.version) {
                case 1: From1To2(d); break;
                case 2: From2To3(d); break;
                default: throw new InvalidDataException($"Thiếu migration từ v{d.version}");
            }
            d.version++;
        }
        return d;
    }

    // v1 lưu vàng là float 'coins'
    static void From1To2(SaveData d) { d.gold = Mathf.RoundToInt(d.legacy_coins); d.legacy_coins = 0; }

    // v2 lưu unlock bằng chỉ số trong bảng; v3 bằng id
    static void From2To3(SaveData d) {
        if (d.legacy_unlockIndices != null)
            d.unlockedItemIds = d.legacy_unlockIndices.Select(LegacyItemTable.IdAt).Where(id => id != null).ToList();
        d.legacy_unlockIndices = null;
    }
}
```

Ba luật: mỗi bước chỉ biết v(n) và v(n+1); **không bao giờ sửa bước cũ** (save v1 ngoài kia vẫn phải đi qua đúng con đường đó); field `legacy_` ở lại trong class vĩnh viễn. Khi class có 15 field legacy, đó là lúc chuyển migration sang Newtonsoft `JObject` và xoá chúng. Save có `version` lớn hơn `Current` (người chơi hạ cấp app) thì từ chối nạp và **không ghi đè**.

## Slot, autosave, backup xoay vòng

```
<persistentDataPath>/saves/
  slot0/manual.json  manual.json.bak  auto_0.json  auto_1.json  auto_2.json
```

Autosave ghi xoay vòng `auto_{n % 3}`, giữ ba bản gần nhất. Kích hoạt ở checkpoint, hết màn, `OnApplicationPause(true)` (xem [[unity-game-loop]]), và tối đa mỗi 2–3 phút. **Không** ghi mỗi khi vàng đổi: 500 lần ghi một giờ vừa tốn vừa tăng cửa sổ bị giết giữa chừng. Nạp: `manual` → `manual.bak` → `auto` mới nhất còn parse được, và **báo cho người chơi** khi phải lùi bản.

## Lưu id, không lưu tham chiếu

`JsonUtility.ToJson` gặp field kiểu `ItemData` (SO) hay prefab sẽ ghi `{"instanceID": 21744}` — vô nghĩa ở lần mở sau. Mọi thứ tham chiếu asset lưu bằng **id string ổn định** khai trong SO, **không dùng `name`** (đổi tên asset là mất save):

```csharp
[CreateAssetMenu(menuName = "Game/Item Database")]
public sealed class ItemDatabase : ScriptableObject {
    [SerializeField] ItemData[] items;
    Dictionary<string, ItemData> byId;

    public ItemData Get(string id) {
        byId ??= items.ToDictionary(i => i.Id);
        if (byId.TryGetValue(id, out var d)) return d;
        Debug.LogWarning($"Item '{id}' không còn trong game — save cũ");   // KHÔNG crash
        return null;
    }
}
```

Validator trong Editor kiểm tra: mọi `ItemData` trong project có trong database, id không trùng, id không rỗng (xem [[unity-editor-tools]]). Với Addressables, id chính là address và `LoadAssetAsync<ItemData>(id)` thay database; xem [[unity-build-platform]]. Item bị xoá khỏi game giữa hai bản: giữ id trong bảng "tombstone" đổi thành vật phẩm bù, đừng để `null` rơi vào inventory.

## Đừng lưu vị trí object trong scene

Cám dỗ lớn là lưu transform của mọi object "để nạp lại y như cũ". Kết quả: save 5MB, phụ thuộc vào scene không đổi, và bug mỗi khi designer dời một cái thùng. Lưu **trạng thái có ý nghĩa thiết kế**: `openedChestIds`, `killedBossIds`, `currentCheckpointId`. Scene nạp lại từ prefab rồi áp trạng thái.

Object thật sự cần lưu (game sandbox, immersive sim) mang component `SaveId` với GUID sinh trong Editor và serialize vào scene. Bẫy: duplicate object là duplicate GUID; prefab instance chia GUID của prefab. Validator kiểm tra trùng, và GUID sinh lại khi `OnValidate` phát hiện trùng trong scene.

## Mã hoá: chống ai?

Mọi thứ trên client đều đọc được nếu người chơi đủ quyết tâm. Hai mục tiêu thật:
- **Chống sửa casual** (mở Notepad đổi `gold: 999999`): AES với key trong code + HMAC-SHA256 của nội dung. Ngăn 95% người thử, không ngăn Cheat Engine. Giá: không debug được bằng mắt; giữ cờ ghi JSON thô trong Development Build.
- **Kinh tế cạnh tranh, leaderboard, mua bán**: client chỉ là cache; server giữ sự thật. Không mã hoá nào thay được.

XOR với chuỗi cố định không phải mã hoá; đó là tự trấn an. Nếu chỉ chống casual, checksum đủ và rẻ.

## Cloud save và conflict

Steam Cloud, Google Play Games, iCloud KVS, Unity Cloud Save: cơ chế khác, bài toán giống nhau — máy A và máy B cùng có save đã đổi. Timestamp thua khi đồng hồ hai máy lệch (và người chơi đổi giờ máy để hack quà ngày). Dùng `playtimeSec` (đơn điệu, không phụ thuộc đồng hồ) làm tiêu chí chính, timestamp làm tie-break. Khi cả hai bản đều "tiến xa hơn" ở mặt khác nhau: **hỏi người chơi** với hai dòng tóm tắt ("Cấp 12, 4g20p" vs "Cấp 9, 2g05p"), không tự merge từng field.

## Test bằng save cũ

Giữ `Tests/SaveFixtures/v1.json`, `v2.json`… **từ mỗi bản đã phát hành**, và một EditMode test nạp từng file → `Migrate` → kiểm tra bất biến (`gold >= 0`, mọi `itemId` resolve được, `version == Current`). Thêm ba fixture ác: file rỗng, file cụt nửa, file có `version: 99`. Chạy trong CI. Không có test này, migration đúng hôm viết và sai ba bản sau khi ai đó đổi tên field.

## IL2CPP stripping xoá thứ bạn cần

Managed Stripping Level `Medium`/`High` bỏ code không được tham chiếu tĩnh. `JsonUtility` an toàn. Newtonsoft dùng reflection: constructor không tham số, setter private, class chỉ xuất hiện trong generic bị strip → field im lặng về `null`/`0`, **không lỗi**. Chữa:

```xml
<!-- Assets/link.xml -->
<linker>
  <assembly fullname="Game.Core">
    <namespace fullname="Game.Save" preserve="all"/>
  </assembly>
</linker>
```

hoặc `[UnityEngine.Scripting.Preserve]` trên class. Test save/load **trên máy thật với đúng stripping level của bản release**; Editor dùng Mono, không strip gì. Chi tiết ở [[unity-build-platform]].

## Bẫy lộ ra khi build

- `float.ToString()`/`Parse` không chỉ định culture trên máy `vi-VN`, `de-DE` đổi `1.5` thành `1,5`. `JsonUtility` không ảnh hưởng; mọi CSV, key tự ghép, hay `Newtonsoft` với converter tự viết phải dùng `CultureInfo.InvariantCulture`.
- Lưu trong `OnDestroy` khi scene unload: object khác đã bị destroy, `SaveData` ghi ra một nửa trạng thái. Lưu **trước** khi gọi `LoadSceneAsync`.
- Danh sách chỉ thêm không xoá (`killLog`, `visitedRooms` theo lần) lớn 10KB mỗi giờ chơi; sau 100 giờ, ghi save mất 200ms. Cap hoặc gộp thành số đếm.
- `Application.Quit()` trên iOS không tồn tại, `OnApplicationQuit` không được gọi trên mobile. Điểm lưu cuối là `OnApplicationPause(true)`.
- Đổi `Product Name` để rebrand → `persistentDataPath` đổi → mọi người chơi bắt đầu lại. Nếu bắt buộc, code dò đường dẫn cũ và di dời.

## Kiểm tra nhanh
- Script lưu 1.000 lần trong vòng lặp, `adb shell am force-stop` ngẫu nhiên giữa chừng: file luôn parse được, hoặc `.bak` cứu được?
- Nạp fixture v1 từ bản phát hành đầu: chơi tiếp được, không `NullReferenceException`, không item `null`?
- Đổi tên một asset `ItemData` trong Editor: save cũ vẫn resolve đúng?
- Build IL2CPP, stripping `High`, cài máy thật: save → tắt app → mở lại khớp Editor?
- File save sau 10 giờ chơi dưới 200KB?

Quyết định quan trọng nhất không phải "UGUI hay UI Toolkit" — mà là **bạn sẽ tổ chức Canvas thế nào trước khi vẽ màn hình thứ hai**. Một Canvas duy nhất chứa cả HUD, menu, popup và số sát thương bay lên là cách phổ biến nhất để có UI chạy 60 FPS trong Editor và 35 FPS trên điện thoại, vì mỗi lần một số đổi là toàn bộ mesh của Canvas đó được dựng lại.

Lý thuyết về thang đo, trạng thái `focused`, ba tầng HUD đã có ở [[ui-design]] và [[ux-hud]]. Node này chỉ nói phần Unity làm sai ở đâu.

## UGUI hay UI Toolkit — năm 2026

| | UGUI (Canvas) | UI Toolkit |
|---|---|---|
| HUD, popup in-game, mobile | **Dùng** — ổn định, mọi package bên thứ ba hỗ trợ | Được, nhưng còn thiếu ở dưới |
| World-space (health bar trên đầu enemy, bảng trong 3D) | Có | **Không** ở runtime (chỉ screen overlay / render texture) |
| Shader, material, particle trong UI | Có — mọi `Graphic` là mesh, gắn material tuỳ ý | Rất hạn chế |
| Animation bằng Animator / tween | Có | Chỉ USS transition, không có Animator |
| Editor tool, cửa sổ, inspector | Được nhưng không ai làm | **Dùng** — Unity 6 khuyến nghị |
| UI dạng document nhiều text (wiki in-game, settings dài) | Được | Tốt hơn — layout flex, styling tập trung |
| AI agent sửa trực tiếp | Prefab YAML, khó | UXML/USS là text, dễ |

Kết luận thực dụng: **UGUI cho mọi thứ người chơi nhìn thấy trong game, UI Toolkit cho mọi thứ trong Editor** ([[unity-editor-tools]]). Lý do không chuyển hết sang UI Toolkit năm 2026 là ba thứ ở bảng trên — world-space, shader/particle trong UI, và Animator. Game nào không cần cả ba (game text, quản lý, puzzle phẳng) thì UI Toolkit là lựa chọn hợp lý, nhưng đó là thiểu số.

## Canvas rebuild — nguồn chi phí thật

Cơ chế: một `Graphic` bất kỳ (Image, Text, RawImage) trong Canvas đổi vertex — đổi màu, đổi text, đổi `fillAmount`, đổi vị trí — đánh dấu Canvas **dirty**. Cuối frame, `Canvas.BuildBatch` dựng lại mesh của **toàn bộ Canvas đó**, không chỉ phần tử đổi. Canvas 300 phần tử mà một con số nhảy mỗi frame là 300 phần tử được dựng lại mỗi frame: 1.5–3 ms trên Snapdragon 6xx, tức 10–20% ngân sách 16 ms.

Cách sửa là tách Canvas theo **tần suất đổi**, không theo chức năng:

```
Canvas_Static      — khung HUD, icon, nền: không bao giờ dirty
Canvas_HUD         — máu, mana, cooldown: đổi vài lần/giây (throttle 10Hz)
Canvas_Dynamic     — số sát thương, combo counter: đổi mỗi frame
Canvas_Menu        — tắt hẳn khi không mở (SetActive false, không phải alpha 0)
```

Canvas con (nested Canvas) cũng cô lập rebuild — thêm component `Canvas` vào child là đủ, nó kế thừa Scaler của cha. Quy tắc: **thứ đổi mỗi frame không được ở chung Canvas với thứ không bao giờ đổi.** Fade bằng `CanvasGroup.alpha` (không dirty), không tween `Image.color` (dirty).

## Raycast Target — tắt mặc định

Mỗi `Image` và `Text` tạo ra có `Raycast Target` bật. `GraphicRaycaster` duyệt **mọi** raycast target trong Canvas cho mỗi sự kiện pointer — trên mobile là mỗi frame có ngón tay chạm. HUD 200 phần tử trong đó 6 cái bấm được → 194 phép kiểm tra thừa mỗi frame chạm.

Tắt trên mọi thứ không nhận input; chỉ giữ trên Button, Toggle, Slider handle, vùng chặn click của popup. Ép bằng một menu item duyệt prefab và tắt cho `Graphic` không có `Selectable` cùng GameObject — 20 dòng, xem [[unity-editor-tools]].

## Layout Group lồng nhau là chi phí bậc thang

`VerticalLayoutGroup` chứa `HorizontalLayoutGroup` chứa `ContentSizeFitter`: mỗi tầng chạy layout hai lượt (đo rồi xếp), và một tầng dirty kéo mọi tầng cha dirty theo. Ba tầng lồng với 50 phần tử là ~0.5 ms; sáu tầng là frame spike thấy được khi mở túi đồ.

Luật:
- Layout Group chỉ ở **một tầng**, cho danh sách thật sự động. Layout cố định thì đặt anchor tay.
- Danh sách trên 30 mục (inventory, leaderboard, shop) dùng **virtualized list**: chỉ tạo đủ cell lấp `ScrollRect` viewport + 2, tái dùng khi cuộn. Tự viết 150 dòng hoặc dùng package; **không** `Instantiate` 500 cell rồi ẩn.

## TextMeshPro — ba việc phải làm

Từ Unity 6, TextMeshPro nằm trong package `com.unity.ugui` 2.0, namespace vẫn `TMPro`.

**Không cấp phát khi đổi số.** `label.text = $"{hp}/{max}"` tạo string mới mỗi frame → GC. Dùng `label.SetText("{0}/{1}", hp, max)` — TMP format số vào buffer nội bộ, 0 B alloc.

**Atlas Static cho font ship, Dynamic chỉ để phát triển.** Dynamic atlas thêm glyph lúc chạy — lần đầu gặp chữ mới là một lần render SDF (0.5–2 ms/glyph) đúng lúc người chơi mở màn hình, và glyph không bao giờ được xoá khỏi RAM. Trước khi ship: `Atlas Population Mode = Static`, **Update Atlas Texture** với toàn bộ chuỗi trong game (Unity Localization xuất được danh sách ký tự), bật `Multi Atlas Textures` nếu không đủ.

**Tiếng Việt và font fallback.** Phần lớn font đẹp trên itch/Google Fonts thiếu `ẳ`, `ỡ`, `ữ`. TMP không báo lỗi — nó tìm trong **Fallback Font Assets**, không có thì hiện ô vuông, và lỗi chỉ lộ khi có bản dịch. Dán chuỗi `"ăâđêôơư ắằẳẵặ ấầẩẫậ ếềểễệ ốồổỗộ ớờởỡợ ứừửữự"` vào một TMP text ngay tuần đầu; cần fallback thì thêm Noto Sans và chấp nhận dấu không cùng nét. CJK gần như luôn cần font riêng và atlas 4096.

SDF: `Sampling Point Size` 60–90, `Padding` ≥ 10% point size — outline/glow ăn vào padding, thiếu là viền bị cắt. Chữ pixel-art dùng Bitmap, không SDF.

## Scaler và safe area

`Canvas Scaler`: `Scale With Screen Size`, tham chiếu 1920×1080, `Match Width Or Height`. Hệ số match:
- **PC/console, tỉ lệ chủ yếu 16:9 → `Match = 1`** (theo chiều cao), như [[ui-design]] khuyến nghị: ultrawide chỉ thêm khoảng trống hai bên.
- **Mobile, tỉ lệ từ 4:3 (iPad) đến 21:9 → `Match = 0.5`**: không bên nào phình quá; đổi lại phải kiểm tra ở cả hai cực.

Safe area: notch, camera đục lỗ, thanh home gesture. Mọi thứ bấm được nằm trong một RectTransform con được kéo về `Screen.safeArea`:

```csharp
[RequireComponent(typeof(RectTransform))]
public class SafeAreaFitter : MonoBehaviour {
    RectTransform rt;
    Rect lastSafe; Vector2Int lastScreen;

    void Awake() { rt = GetComponent<RectTransform>(); Apply(); }

    void Update() {                                   // một phép so sánh struct mỗi frame, rẻ
        if (Screen.safeArea != lastSafe || Screen.width != lastScreen.x || Screen.height != lastScreen.y)
            Apply();
    }

    void Apply() {
        lastSafe = Screen.safeArea;
        lastScreen = new Vector2Int(Screen.width, Screen.height);
        Vector2 min = lastSafe.position, max = lastSafe.position + lastSafe.size;
        min.x /= Screen.width;  min.y /= Screen.height;
        max.x /= Screen.width;  max.y /= Screen.height;
        rt.anchorMin = min; rt.anchorMax = max;
        rt.offsetMin = rt.offsetMax = Vector2.zero;   // anchor lo hết, không còn offset tay
    }
}
```

Nền, hình trang trí nằm **ngoài** SafeArea để tràn hết màn; nút và text nằm **trong**. Test bằng `Device Simulator` với iPhone 15 + Galaxy S24 Ultra + iPad là đủ ba cực.

Anchor thay hardcode: mỗi phần tử anchor vào góc/cạnh gần nhất, phần tử kéo giãn có anchor min/max khác nhau và `offset` là lề. Nếu code UI đang nhân `Screen.width` với hệ số, anchor đã sai.

## Kiến trúc: View không biết gì

Áp dụng MVP nhẹ — chi tiết pattern và event channel ở [[unity-design-patterns]]:

```csharp
public class HealthView : MonoBehaviour {                 // chỉ vẽ, không logic
    [SerializeField] Image fill;
    [SerializeField] TMP_Text label;
    public void Render(int hp, int max) {
        fill.fillAmount = (float)hp / max;
        label.SetText("{0}/{1}", hp, max);
    }
}

public class HealthPresenter : MonoBehaviour {            // nghe event, đẩy vào View
    [SerializeField] HealthView view;
    [SerializeField] HealthChangedChannel channel;        // ScriptableObject event
    void OnEnable()  => channel.Raised += view.Render;
    void OnDisable() => channel.Raised -= view.Render;
}
```

View không `FindFirstObjectByType<Player>()`, không đọc `PlayerStats` — test được bằng `Render(37, 100)` từ nút debug, đổi nguồn dữ liệu (local → network) không đụng UI.

**Màn hình là prefab có `Show/Hide` async và một stack** — luồng menu ở [[ux-flow]] hiện thực hoá bằng:

```csharp
public abstract class UIScreen : MonoBehaviour {
    [SerializeField] CanvasGroup group;
    [SerializeField] Selectable firstSelected;            // focus mặc định cho gamepad

    public virtual async Awaitable Show() {               // Unity 6 Awaitable; 2022 dùng coroutine/UniTask
        gameObject.SetActive(true);
        group.interactable = group.blocksRaycasts = false;
        await Fade(0f, 1f, 0.15f);
        group.interactable = group.blocksRaycasts = true;
        if (firstSelected) EventSystem.current.SetSelectedGameObject(firstSelected.gameObject);
    }
    public virtual async Awaitable Hide() {
        group.interactable = group.blocksRaycasts = false;
        await Fade(1f, 0f, 0.10f);
        gameObject.SetActive(false);
    }
    async Awaitable Fade(float a, float b, float dur) {
        for (float t = 0; t < dur; t += Time.unscaledDeltaTime) {   // unscaled: menu mở khi timeScale = 0
            group.alpha = Mathf.Lerp(a, b, t / dur);
            await Awaitable.NextFrameAsync();
        }
        group.alpha = b;
    }
}

public class ScreenStack : MonoBehaviour {
    readonly Stack<UIScreen> stack = new();
    public async Awaitable Push(UIScreen s) {
        if (stack.TryPeek(out var top)) top.GetComponent<CanvasGroup>().interactable = false;
        stack.Push(s); await s.Show();
    }
    public async Awaitable Pop() {                        // gắn vào Esc / nút B, mọi màn hình
        if (!stack.TryPop(out var top)) return;
        await top.Hide();
        if (stack.TryPeek(out var below)) below.GetComponent<CanvasGroup>().interactable = true;
    }
}
```

`interactable = false` trên màn dưới là thứ chặn lỗi "bấm xuyên popup vào nút phía sau" — lỗi QA báo nhiều nhất ở menu.

## UI khi `timeScale = 0`

Pause đặt `Time.timeScale = 0` ([[unity-game-loop]]) và UI chết theo nếu không chuẩn bị: Animator trên UI phải để `Update Mode = Unscaled Time`; DOTween thêm `.SetUpdate(true)`; coroutine dùng `WaitForSecondsRealtime`; `Awaitable.WaitForSecondsAsync` **theo scaled time** — dùng vòng `unscaledDeltaTime` như trên. Particle trong UI (confetti màn thắng) bật `Main > Use Unscaled Time`.

## World-space UI

Health bar trên đầu 50 enemy = 50 Canvas world-space = 50 lần rebuild + 50 draw call. Hai lựa chọn tốt hơn:
- **Một Canvas screen-space** duy nhất, mỗi bar là một Image được đặt bằng `Camera.WorldToScreenPoint` mỗi frame — một Canvas dynamic, batch tốt.
- **Không dùng Canvas**: bar là hai `SpriteRenderer` (nền + fill scale theo trục X) hoặc một quad với shader nhận `_Fill` qua MaterialPropertyBlock ([[unity-shader]]). Rẻ nhất, sort chung với sprite thế giới.

Canvas world-space chỉ dành cho thứ ít và cần tương tác thật trong 3D (bảng điều khiển, màn hình máy tính trong game).

## Sprite Atlas và draw call

UI không atlas: mỗi Image dùng texture khác là một draw call. HUD 40 icon = 40 draw call, atlas hoá còn 1–3. Tạo `Sprite Atlas` (Unity 6 mặc định V2), kéo thư mục `Assets/Art/UI` vào, `Include in Build` **bật**. Bẫy: Editor luôn hiện đúng vì Sprite Packer mode `Always Enabled`, còn build thiếu atlas thì sprite hiện **trắng** hoặc rớt về texture rời — không lỗi, không log. Text và Image xen kẽ vẫn phá batch (material khác nhau), nên nhóm Image cạnh Image trong hierarchy khi có thể.

## Localization và chuỗi dài

Unity Localization package: `LocalizeStringEvent` gắn lên TMP text, bảng string là asset, hỗ trợ plural và smart string `{count} vật phẩm`. Cái vỡ là **layout**: "Play" → "Bắt đầu chơi" → "Spiel starten" dài gấp 3. Quy tắc: nút có `Auto Size` với min 60% cỡ gốc, panel text có `ContentSizeFitter` theo chiều dọc, và **test bằng pseudo-locale** (Localization có sẵn: kéo dài chuỗi 30% và thêm dấu) trước khi có bản dịch thật.

## Gamepad, bàn phím, và trợ năng

Input System với `InputSystemUIInputModule` thay `StandaloneInputModule` — chi tiết ở [[unity-input]]. Mỗi màn hình đặt `firstSelected` như code trên; `Navigation` của Selectable để `Explicit` ở layout lưới/phức tạp vì `Automatic` chọn theo khoảng cách hình học và nhảy sai ở grid không đều. Ẩn cursor khi có gamepad input, hiện lại khi chuột động.

Trợ năng ([[accessibility]]) trong Unity gói gọn: một `UiTheme` ScriptableObject giữ hệ số cỡ chữ 1.0/1.25/1.5 và mọi TMP text lấy `fontSize = baseSize * theme.textScale` qua một component `ThemedText`; chế độ contrast cao đổi bảng màu trong cùng asset. Ép ngay từ đầu, không phải retrofit 200 text về sau. Cỡ chữ nhỏ nhất 13 px ở 1080p, 20 px cho console.

## Bẫy lộ ra khi build

- `Canvas` để `Pixel Perfect` bật trên mobile: mỗi frame snap vị trí mọi phần tử → rebuild liên tục khi có tween. Tắt, chỉ bật cho pixel-art game có scaler nguyên.
- `Screen.safeArea` trả về cả màn hình ở frame đầu trên một số Android — vì thế code trên kiểm tra lại trong `Update`, không chỉ `Awake`.
- IL2CPP strip: `LocalizeStringEvent` với `UnityEvent` generic bị strip khi `Managed Stripping Level = High` → thêm `link.xml` cho `Unity.Localization`. Xem [[unity-build-platform]].
- Font Dynamic atlas trên build: glyph mới sinh lúc chạy tốn RAM và không được xoá — game chat tiếng Việt chạy 2 giờ có atlas 8 MB. Static hoặc `Clear Dynamic Data On Build`.
- `EventSystem` nhiều hơn một trong scene (mỗi scene additive tự có) → input UI nhân đôi hoặc mất. Một `EventSystem` ở bootstrap scene, cấm trong scene khác.

## Kiểm tra nhanh

- Profiler > UI module: `Canvas.BuildBatch` ở HUD tĩnh (không đánh, không nhận sát thương) phải **0 lần/giây**. Có là Canvas tách sai.
- Frame Debugger: HUD đầy đủ ≤ 8 draw call UI. Trên 15 là thiếu atlas hoặc Text/Image xen kẽ.
- Tìm mọi `Graphic` có Raycast Target bật: số đó phải ≈ số Selectable + số popup blocker.
- Rút chuột, cắm gamepad, đi hết mọi màn hình bằng D-pad và B: không kẹt ở đâu, không màn nào mất focus.
- Device Simulator iPhone 15 landscape + Galaxy Fold mở: không nút nào dưới notch, không text nào tràn.

Quyết định đầu tiên: **hiệu ứng này có cần gameplay đọc được nó không, và máy yếu nhất có chạy compute shader không?** Hai câu đó chọn Particle System hay VFX Graph, và chọn sai là làm lại toàn bộ thư viện hiệu ứng. Quyết định thứ hai, đắt hơn về hiệu năng: **ngân sách overdraw** — một tấm khói 512×512 phủ nửa màn hình tốn hơn 2000 tia lửa 8×8.

Số liệu hitstop, biên độ rung, thứ tự ưu tiên juice đã ở [[game-feel]]. Node này nói cách nối chúng thành pipeline trong Unity mà không cấp phát, không rò và không nát trên mobile.

## Particle System (Shuriken) hay VFX Graph

| | Particle System | VFX Graph |
|---|---|---|
| Chạy trên | CPU (job hoá, Burst) | GPU compute shader |
| Số hạt thoải mái | 1–5 nghìn toàn cảnh | Hàng trăm nghìn – triệu |
| Gameplay đọc/ghi hạt | `GetParticles`/`SetParticles`, `OnParticleCollision`, trigger module | Gần như không — GPU không trả về CPU |
| Va chạm với thế giới | Collision module với collider thật | Chỉ depth buffer / SDF |
| Mobile | Mọi máy | Cần compute (GLES 3.1+/Vulkan/Metal) — Android tầm thấp và driver Mali cũ **hỏng hoặc rớt** |
| 2D sorting với sprite | `Sorting Layer` + `Order in Layer` trên renderer | Được qua Sorting Group nhưng lệch với sprite thường |
| Chỉnh trong Editor | Inspector module, designer quen | Node graph, cần người hiểu shader |
| Draw call | 1 mỗi system (1 material) | 1 mỗi output context |

Luật thực dụng: **Shuriken là mặc định**. VFX Graph chỉ khi cần số lượng (mưa, tuyết, đám đông hạt ma thuật, portal 3D) **và** nền tảng đích là PC/console hoặc mobile tầm trung trở lên có kiểm tra `SystemInfo.supportsComputeShaders` với fallback Shuriken. Game 2D pixel gần như không có lý do dùng VFX Graph.

## Ngân sách: overdraw, không phải số hạt

Fill rate là giới hạn thật trên mobile. Mỗi hạt là một quad bán trong suốt; GPU tô **mọi pixel** của quad kể cả pixel alpha 0, và tô lại pixel đó cho từng hạt chồng lên. Khói 30 hạt 256×256 chồng nhau ở giữa màn hình = một pixel bị tô 15–30 lần. Mali-G52 ở 1080p chịu được ~3–4 lần toàn màn hình mỗi frame ở 60 FPS — vụ nổ đó một mình đã ăn hết.

Đo: **Rendering Debugger** (Window > Analysis > Rendering Debugger) > Rendering > `Full Screen Debug Mode = Overdraw`. Vùng đỏ đậm là nơi cần cắt. Trong URP, chế độ Overdraw của Scene view cũ không dùng được — chỉ Rendering Debugger.

Cách cắt, theo hiệu quả:
1. **Ít hạt to hơn nhiều hạt nhỏ, nhưng texture sát mép** — sprite khói không nên có 40% viền trong suốt; cắt mesh hạt hoặc dùng `Render Mode = Mesh` với hình bát giác thay quad.
2. **Không quá 2 lớp alpha phủ cùng vùng**: một lớp khói + một lớp lửa. Lớp thứ ba (glow toàn màn) làm bằng Volume, không bằng hạt.
3. Texture hạt 64–128 px là đủ; 512 chỉ cho hạt duy nhất chiếm nửa màn.
4. `Soft Particles` tắt trên mobile (đọc depth mỗi pixel).

Ngân sách tham khảo cho game hành động mobile: ≤ 300 hạt sống cùng lúc toàn cảnh, ≤ 12 ParticleSystem đang phát, hiệu ứng lớn nhất ≤ 60 hạt. PC gấp 10 lần và vẫn không thấy trên Profiler.

## Pool ParticleSystem — bắt buộc

`Instantiate(hitPrefab)` mỗi cú đánh + `Destroy(go, 2f)`: 40 cú đánh/giây trong boss fight = 40 lần cấp phát + 40 lần huỷ, GC spike mỗi vài giây. Pool:

```csharp
public class VfxPool : MonoBehaviour {
    [SerializeField] ParticleSystem prefab;
    [SerializeField] int prewarm = 8;
    readonly Stack<ParticleSystem> free = new();

    void Awake() { for (int i = 0; i < prewarm; i++) free.Push(Create()); }

    ParticleSystem Create() {
        var ps = Instantiate(prefab, transform);
        var main = ps.main;
        main.playOnAwake = false;                            // prefab pool KHÔNG tự phát khi SetActive
        main.stopAction = ParticleSystemStopAction.Callback; // báo về khi mọi hạt chết
        ps.gameObject.AddComponent<VfxReturn>().pool = this;
        ps.gameObject.SetActive(false);
        return ps;
    }

    public ParticleSystem Play(Vector3 pos, Quaternion rot) {
        var ps = free.Count > 0 ? free.Pop() : Create();     // hết thì mở rộng, log warning để chỉnh prewarm
        ps.transform.SetPositionAndRotation(pos, rot);
        ps.gameObject.SetActive(true);
        ps.Play(withChildren: true);
        return ps;
    }

    public void Return(ParticleSystem ps) {
        ps.Stop(true, ParticleSystemStopBehavior.StopEmittingAndClear);  // xoá hạt còn sống ở cả con
        ps.gameObject.SetActive(false);
        free.Push(ps);
    }
}

public class VfxReturn : MonoBehaviour {
    public VfxPool pool;
    void OnParticleSystemStopped() => pool.Return(GetComponent<ParticleSystem>());
}
```

Ba bẫy cụ thể:
- **`OnParticleSystemStopped` chỉ được gọi khi hệ không loop** và mọi hạt đã chết. Một child để `Looping` bật (thường là glow nền) là cả hệ không bao giờ trả về pool. Kiểm tra mọi child.
- **Child không reset** nếu chỉ `Stop()` trên cha không có `withChildren` — hạt con còn treo ở vị trí cũ, lần phát sau thấy "tàn dư" ở chỗ đánh trước. Luôn `Stop(true, StopEmittingAndClear)`.
- **`Play On Awake` bật trên prefab pool**: `SetActive(true)` là phát ngay ở vị trí cũ, trước khi `SetPositionAndRotation` — một frame hạt xuất hiện sai chỗ. Tắt trong prefab, không chỉ trong code.

`Stop Action = Disable` là lựa chọn không cần script cho hiệu ứng không pool (một lần mỗi màn), nhưng nó không báo về nên không tái dùng được.

## Gắn vào bone và bẫy scale

Hiệu ứng theo tay (trail kiếm, lửa trên vũ khí) parent vào bone. Bone có scale không đồng nhất, hoặc nhân vật có `localScale = (-1, 1, 1)` để quay mặt (2D) → hạt bị bóp, lật, hoặc bay ngược. Sửa bằng **`Scaling Mode`** trong Main module:
- `Hierarchy` — hạt scale theo mọi scale cha: hợp cho hiệu ứng "thuộc về" vật (aura quanh enemy to nhỏ khác nhau).
- `Local` — chỉ scale của chính ParticleSystem: **mặc định nên chọn** cho hạt gắn bone.
- `Shape` — chỉ vùng phát scale, hạt giữ kích cỡ: cho hiệu ứng phủ bề mặt.

Khói, lửa từ vật đang di chuyển (xe, đạn) đặt **`Simulation Space = World`** — hạt đã phát ra ở lại đúng chỗ trong thế giới, không kéo theo vật. `Local` cho hạt phải bám (aura, shield). Trộn hai cái trong một hệ không được; dùng hai hệ con.

## Sorting trong 2D

`ParticleSystemRenderer` có `Sorting Layer` và `Order in Layer` như SpriteRenderer. Hiệu ứng trúng đòn để layer `FX`, order cao hơn nhân vật; khói bụi chân để layer nhân vật, order thấp hơn. Trong cùng layer và order, Unity sort theo khoảng cách camera — hạt và sprite ở cùng Z tranh nhau flicker. **`Sorting Fudge`** (số âm là vẽ sau, tức nằm trên) dịch hệ hạt trong hàng đợi sort mà không đổi Z. Hạt trong cùng một hệ sort theo `Sort Mode` (By Distance / Oldest / Youngest in Front) — hiệu ứng nổ dùng *Youngest in Front* để hạt mới nằm trên hạt đang tan.

Sprite Renderer với `Sorting Group` gom nhân vật + hiệu ứng thành một khối sort, tránh hạt của enemy A xuyên lên nhân vật B đứng trước.

## Pipeline hit effect — 0 đến 150 ms

Thứ tự thời gian cho một đòn trúng tầm trung, mọi số lấy từ `FeelConfig` ([[game-feel]]):

| Thời điểm | Việc | Trong Unity |
|---|---|---|
| 0 ms | SFX, flash trắng bắt đầu, hitstop bắt đầu, burst hạt, impulse camera | Cùng một hàm `OnHit`, cùng frame va chạm — không đợi animation |
| 0–70 ms | Hitstop: nhân vật và mục tiêu đứng hình, hạt **vẫn chạy** | Local clock = 0 cho hai thực thể; hạt dùng unscaled hoặc không chịu clock |
| 70 ms | Flash tắt, knockback bắt đầu, hitstop kết thúc | `MaterialPropertyBlock` `_FlashAmount = 0`; velocity đẩy |
| 70–150 ms | Knockback giảm dần, camera hồi | Impulse decay do Cinemachine lo |
| 150 ms | Hết; hạt tan tự do đến ~400 ms | `OnParticleSystemStopped` trả pool |

**Hitstop bằng `Time.timeScale` hay clock riêng?**

| | `Time.timeScale = 0` | Local time scale trên thực thể |
|---|---|---|
| Code | 5 dòng, xem [[game-feel]] | Mỗi thực thể có `Delta` riêng, mọi movement/animator nhân theo |
| Hạt, UI, audio | **Cũng đứng** — hạt hit spark đóng băng (chấp nhận được), số sát thương bay ngừng (khó chịu), audio không dừng | Chạy bình thường |
| Nhiều mục tiêu, multiplayer | Không dùng được — dừng cả thế giới | Đúng cách duy nhất |
| Physics | `FixedUpdate` ngừng theo | Phải tự nhân velocity |

Game một người chơi, nhịp chặt (platformer, beat 'em up): `timeScale` đủ, chỉ cần bật `Use Unscaled Time` trên hạt số sát thương và Animator UI. Game nhiều thực thể hoặc online: clock riêng —

```csharp
public class LocalClock : MonoBehaviour {
    public float Scale { get; private set; } = 1f;
    float resumeAt;
    public float Delta => Time.deltaTime * Scale;          // mọi chuyển động của thực thể đọc cái này
    public void Hitstop(float seconds) { Scale = 0f; resumeAt = Time.unscaledTime + seconds; }
    void Update() { if (Scale == 0f && Time.unscaledTime >= resumeAt) Scale = 1f; }
}
```

Animator của thực thể nhận `animator.speed = clock.Scale`. Rigidbody thì lưu velocity, đặt 0, trả lại — đừng đổi `timeScale` vì thế giới khác vẫn chạy.

Flash trắng qua `MaterialPropertyBlock` (không `renderer.material` — tạo instance rò) ở [[unity-shader]]; rung camera qua `CinemachineImpulseSource.GenerateImpulse(direction * strength)` với **hướng đòn**, không rung vô hướng — [[unity-camera]]. Hạ boss: cùng pipeline, số gấp đôi và thêm Volume pulse bên dưới.

## Trail, Line, Decal

**`TrailRenderer`** cho vệt kiếm/đạn: `time` 0.1–0.2 s, `minVertexDistance` 0.1 để không sinh vertex mỗi frame. Bẫy: **teleport** (respawn, dash xa, pool tái dùng) kéo một vệt dài xuyên màn hình từ vị trí cũ tới mới. Gọi `trail.Clear()` ngay sau khi đặt vị trí, hoặc `emitting = false` một frame. Trail cũng không hiểu pool: bật lại object ở chỗ khác là vệt nối.

**`LineRenderer`** cho laser: `positionCount = 2`, `useWorldSpace = true`, texture scroll bằng `material.mainTextureOffset` qua MaterialPropertyBlock. Độ rộng theo `widthCurve`, đầu laser là một ParticleSystem riêng.

**URP Decal Projector** (vết đạn, máu trên sàn): cần thêm `Decal Renderer Feature` vào URP Renderer. Chi phí mỗi decal ≈ một draw call và một lần đọc depth trong box chiếu; 30–50 decal đồng thời ổn trên mobile với kỹ thuật `Screen Space`, `DBuffer` tốn hơn nhưng đúng ánh sáng. Giới hạn số decal bằng ring buffer, xoá cái cũ nhất.

## Screen-space qua Volume weight

Chromatic aberration, vignette đập khi trúng đòn: **không** chỉnh trực tiếp `profile` của Volume toàn cục — trong Editor đó là ScriptableObject, chỉnh là sửa asset vĩnh viễn (cùng bẫy ở [[data-driven-design]]). Tạo một `Volume` riêng, `Is Global`, `Weight = 0`, profile chỉ chứa Vignette intensity 0.45 + Chromatic 0.6, rồi tween **weight**:

```csharp
[SerializeField] Volume hitVolume;                        // weight 0 khi nghỉ
Coroutine pulse;

public void Pulse(float peak = 1f, float duration = 0.18f) {
    if (pulse != null) StopCoroutine(pulse);
    pulse = StartCoroutine(Run(peak, duration));
}
IEnumerator Run(float peak, float dur) {
    for (float t = 0; t < dur; t += Time.unscaledDeltaTime) {   // unscaled: đang hitstop
        hitVolume.weight = peak * (1f - t / dur);
        yield return null;
    }
    hitVolume.weight = 0f; pulse = null;
}
```

Máu thấp thì một Volume khác weight theo `1 - hp/max`. Volume weight blend rẻ; số Volume có `override` chồng nhau mới tốn.

## Kỹ thuật nhỏ quyết định "punch"

- **Burst thay rate.** Nổ = `Emission > Bursts` 1 lần 24 hạt tại t=0, rate 0. Rate over time 200 trong 0.1 s cho hình rải, mềm — không có cú đấm.
- **Sub Emitter** `On Birth`/`On Death` cho tia lửa sinh khói nhỏ khi tắt — một prefab, một lần gọi, thay vì ba hệ tự phối thời gian.
- **Texture Sheet Animation** module cho flipbook nổ 4×4 (CPU đổi UV) đủ cho Shuriken; flipbook trong shader (Shader Graph `Flipbook` node) khi cần blend giữa hai frame — mượt hơn ở tốc độ thấp, chi phí shader cao hơn.
- **Lights module: mỗi hạt là một Point Light thật.** URP giới hạn 8 đèn phụ mỗi object (Forward) — 10 tia lửa có light là đèn bị cắt ngẫu nhiên và frame rụng. Chỉ cho 1–2 hạt/hệ, `Ratio` 0.1, và tắt trên mobile. Ánh sáng "giả" bằng hạt additive to mờ rẻ hơn 50 lần.
- **Timeline** cho sequence lớn (ultimate, cắt cảnh boss chết): Control Track điều khiển nhiều ParticleSystem theo thời gian, designer scrub được. Không code chuỗi `WaitForSeconds` cho hiệu ứng dài hơn 0.5 s.

## Bẫy lộ ra khi build

- Prefab hạt dùng material `Particles/Standard Unlit` của Built-in — Editor hiện đúng nhờ fallback, build URP ra **hồng**. Mọi hạt dùng `Universal Render Pipeline/Particles/Unlit`.
- Shader variant của particle (soft particles, flipbook blending, distortion) làm build lâu thêm phút và **lần đầu phát hiệu ứng khựng** vì compile shader lúc chạy. Warm-up bằng `ShaderVariantCollection` ở màn load — [[unity-shader]].
- VFX Graph trên máy không có compute: không lỗi, hiệu ứng chỉ **không hiện**. Kiểm tra `SystemInfo.supportsComputeShaders` lúc boot và đổi prefab.
- `Max Particles` mặc định 1000 mỗi hệ — pool 16 hệ nổ là 16000 hạt tiềm năng, mỗi hạt ~100 B trạng thái. Hạ về đúng burst + margin (32–64).
- Sprite 2D game có `Order in Layer` trên hạt nhưng camera Perspective: hạt ở Z khác sprite bị sort theo khoảng cách, không theo order. Camera Orthographic hoặc `Transparency Sort Mode = Custom Axis (0,1,0)` trong Graphics settings.

## Kiểm tra nhanh

- Rendering Debugger > Overdraw khi nổ to nhất: không vùng nào đỏ đậm quá 10% màn hình.
- Frame Debugger: số draw call tăng khi phát hiệu ứng lớn nhất ≤ 6 (mỗi hệ con là 1; cùng material vẫn không batch giữa hệ).
- Profiler > `ParticleSystem.Update` ở cảnh đông nhất < 1 ms; GC Alloc khi phát 100 hit liên tiếp = 0 B.
- Phát cùng một hiệu ứng ở hai chỗ cách 50 m liên tiếp: chỗ thứ hai không có tàn dư hay vệt trail nối.
- Đặt `timeScale = 0.1` (slow-mo debug): hạt hit vẫn phát đúng vị trí và số sát thương vẫn bay — tức unscaled đã đặt đúng chỗ.
